      "content": "import { CommandService, type RegisteredCommand } from './commands/service.js'\nimport { commandLogObserver } from './commands/logging.js'\nimport { RuntimeCompatibilityRegistry } from './runtime-compatibility.js'\nimport type { HostLogService } from './logs/service.js'\nimport type { DshSessionStorageRetirementReport, InboundHookDecisionRecord } from '@nekro-nxt/storage-sqlite'\nimport { LlmProviderRemovalCoordinator } from './llm-provider-removal.js'\nimport { LlmProviderTestResults } from './llm-provider-test-results.js'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { BUILTIN_ADAPTER_CONTRIBUTIONS } from '@nekro-nxt/adapter-builtin-roster'\nimport {\n  AdapterRegistry,\n  type AdapterConnectionRuntime,\n  type AdapterHostContributionV2,\n  type AdapterLocalChannelPort,\n  type AdapterTransportService,\n  type RegisteredAdapterHandle,\n} from '@nekro-nxt/adapter-sdk'\nimport { prepareDataRootMoveRollover } from './data-root-move.js'\nimport { ChannelRuntime, type ExtensionJobFiring, type InboundHookDecision } from '@nekro-nxt/channel-runtime'\nimport { adapterSupportsPart, isAdminConsoleOutbound, UNSUPPORTED_PART } from '@nekro-nxt/channel-runtime'\nimport { ExtensionOutboundProcessor, outboundOrderFor } from './extension-outbound.js'\nimport {\n  AgentIdSchema,\n  AssetIdSchema,\n  ChannelIdSchema,\n  CommandDefinitionSchema,\n  ConnectionIdSchema,\n  configSecretKeys,\n  hostLayerAsCapabilities,\n  parseJsonValue,\n  type JsonValue,\n  DEFAULT_CHANNEL_CONTEXT_POLICY,\n  DshNxtHostUiSchema,\n  AuthoringTaskIdSchema,\n  HostApiContracts,\n  OutboundIntentIdSchema,\n  EXTENSION_COMMAND_PROFILES,\n  ExtensionIdSchema,\n  ExtensionCommandProfileIdSchema,\n  HostUiPageInstanceIdSchema,\n  type AgentId,\n  type ChannelId,\n  type ConnectionId,\n  type DshPluginPackageId,\n  type ExtensionId,\n  type ExtensionRevisionId,\n} from '@nekro-nxt/contracts'\nimport type { AgentRevisionContent } from '@nekro-nxt/core'\nimport { AssetService, CoreService } from '@nekro-nxt/core'\nimport {\n  AuthoringArtifactStore,\n  DynamicAuthoringService,\n  configSecretReferences,\n  ExtensionBuilder,\n  ExtensionLifecycleCoordinator,\n  ExtensionService,\n  ExtensionSourceStore,\n  hostUiPermissionDigest,\n  layerConfigSchema,\n  type Revision,\n} from '@nekro-nxt/extension-runtime'\nimport {\n  ChannelHistoryPurgeBlockedError,\n  completeDshSessionStoragePreparation,\n  openMigratedCoreDatabase,\n  prepareDshSessionStorage,\n  SqliteCoreRepository,\n  SqliteHostSecurityRepository,\n  type ChannelHistoryPurgePreview,\n  type CoreDatabase,\n  type DshSessionStoragePreparation,\n} from '@nekro-nxt/storage-sqlite'\nimport { randomUUID } from 'node:crypto'\nimport {\n  ChannelHistoryPurgeRefusedError,\n  HISTORY_PURGE_PREPARED_GRACE_MS,\n  type ChannelHistoryPurgeOutcome,\n  type ChannelHistoryPurgeView,\n} from './channel-history-purge.js'\nimport { mkdir, rm } from 'node:fs/promises'\nimport path from 'node:path'\nimport { monotonicFactory } from 'ulid'\nimport { createProductionAdapterTransport } from './adapter-transport.js'\nimport { AuthoringApplicationService } from './authoring-application.js'\nimport { ConnectionApplicationService } from './connection-application.js'\nimport { LocalCredentialStore } from './credentials.js'\nimport { redactInboundEvent } from './credential-redaction.js'\nimport { SecretRegistry } from './secret-registry.js'\nimport { CredentialLibrary, namedCredentialId } from './credentials-library.js'\nimport { CredentialRequests } from './credential-requests.js'\nimport { ModelProviderAccess, openModelOptions } from './model-provider-access.js'\nimport { GitBash } from './git-bash.js'\nimport { downloadMirror } from './product-updates.js'\nimport { GithubCli } from './github-cli.js'\nimport { createGithubPlatform } from './linked-accounts/github.js'\nimport { commandAccountsOf, LinkedAccountLibrary } from './linked-accounts/library.js'\nimport { LinkedAccountPlatforms } from './linked-accounts/platform.js'\nimport { CandidateVerifier } from './candidate-verifier.js'\nimport { VerificationBrowser } from './verification-browser.js'\nimport { DshPluginPackageInstaller } from './dsh-plugin-installer.js'\nimport type { PersistentAdapterPort } from './persistent-extension-mounts.js'\nimport { verifyImportedExtensionRevision } from './imported-extension-verifier.js'\nimport { AuthoringTestConfig } from './authoring-test-config.js'\nimport { createExtensionEgress } from './extension-egress.js'\nimport { ExtensionInboundHookGate } from './extension-inbound-hooks.js'\nimport { voiceTranscriptionAnnotator } from './voice-transcription.js'\nimport { ExtensionJobScheduler, scheduledJob, sqliteNxtJobs, syncDeclaredJobs } from './extension-jobs.js'\nimport { ScheduledTasks, type JobFireOutcome } from './scheduled-tasks.js'\nimport { CodeRunNode } from './code-run-node.js'\nimport { McpStatusRegistry } from './mcp-servers.js'\nimport {\n  createNxtProductBackends,\n  memoryNxtJobs,\n  messagePartsText,\n  memoryNxtStorage,\n  previewPlatformResult,\n  sqliteNxtStorage,\n  type NxtProductFacts,\n} from './extension-host-backends.js'\nimport { memoryIndexEngine, sqliteIndexEngine } from './extension-index.js'\nimport { RetrievalRuntime } from './retrieval-runtime.js'\nimport {\n  AddonRegistry,\n  browserAddon,\n  gitBashAddon,\n  githubCliAddon,\n  mediaAddon,\n  nodeAddon,\n  retrievalAddon,\n  speechAddon,\n  syncProgramEnvironment,\n} from './addons.js'\nimport { CommandProfiles } from './command-profiles.js'\nimport { dataRootCommandConfinement } from './command-confinement.js'\nimport { ConfinedProgramRunner, createProgramSandbox } from './confined-program.js'\nimport { ExtensionFileStore } from './extension-files.js'\nimport { MediaFfmpeg } from './media-ffmpeg.js'\nimport { MediaToolkit } from './media-toolkit.js'\nimport { SpeechCloud } from './speech-cloud.js'\nimport { LocalSpeech } from './speech-local.js'\nimport { SpeechService } from './speech-service.js'\nimport {\n  ExtensionLibrary,\n  memoryLibraryRegistry,\n  sqliteLibraryRegistry,\n  type LibraryRegistry,\n} from './extension-library.js'\nimport type { NxtPlatformResult } from '@nekro-nxt/extension-sdk'\nimport { createNxtHostService, type NxtServiceBackends } from './extension-host-service.js'\nimport { ChannelExtensionRuntimeHost, createChannelAsset, DshHostRuntime, type DshHostRuntimeOptions } from './index.js'\nimport { NotificationService } from './notifications.js'\nimport { CommunityService } from './community.js'\nimport { ExtensionActionService } from './extension-governance/actions.js'\nimport { commandPrefix, ExtensionCommandPort, waitingRunCommands } from './extension-governance/commands.js'\nimport { ExtensionGovernanceTools } from './extension-governance/tool-port.js'\nimport { ExtensionConfigService } from './extension-governance/config-service.js'\nimport { AdministratorService } from './extension-governance/administrators.js'\nimport { CommunitySyncService } from './extension-governance/community-sync.js'\nimport { ExtensionDataService } from './extension-governance/data-service.js'\nimport { ExtensionRequestService } from './extension-governance/requests.js'\nimport { createMigrationStorage } from './extension-data-migration.js'\nimport { commandBotMember } from './commands/bot-member.js'\nimport { CommunityFeedbackService } from './community-feedback.js'\nimport { runtimeFeedbackSources, type FeedbackEnvironment } from './feedback-runtime.js'\nimport { channelMemberRelations } from './channel-member-relations.js'\nimport { ChannelPrompts } from './channel-prompts.js'\nimport { messageGapMs, readMessagePacing } from './message-pacing.js'\nimport { readExtensionDownloadLimit } from './extension-download-settings.js'\nimport { readCompactionSettings } from './compaction-settings.js'\nimport { readModelFallbackSettings } from './model-fallback-settings.js'\nimport { readSubConversationRetention } from './sub-conversation-settings.js'\nimport type { HostRestart, HostRestartRequester } from './host-restart.js'\n\n/** How often ended sub-conversations past their retention are removed. */\nconst SUB_CONVERSATION_SWEEP_MS = 60 * 60 * 1000\nexport type { ConnectionTestResult } from './connection-application.js'\n/**\n * Single source of truth for the NekroNxt Server main assembly. Extracts the\n * inline composition previously duplicated across tests into one reusable\n * entry that owns every service the domain API drives. Assembly order mirrors\n * the M1–M5 vertical-slice tests; disposal waits for resources to settle in\n * reverse order (docs/06).\n */\n/** Due-job handlers decide quickly; a slow one wakes the agent as if it had no handler. */\nconst JOB_HANDLER_TIMEOUT_MS = 15_000\nconst JOB_NOTE_MAX_CHARS = 2000\n\n/** Paused creation tasks nobody continued for this long are archived. */\nconst AUTHORING_PAUSE_ARCHIVE_MS = 30 * 24 * 60 * 60 * 1000\n/** Community reviews take minutes; the agent hears the result within a few minutes of it settling. */\nconst EXTENSION_REVIEW_POLL_MS = 3 * 60 * 1000\n\nexport interface NekroRuntimeOptions {\n  readonly logs?: HostLogService\n  readonly feedbackEnvironment?: FeedbackEnvironment\n  /** Production startup keeps inbound facts durable while migration and recovery settle. */\n  readonly deferAdmission?: boolean\n  /** Core domain SQLite file path (opened + migrated). */\n  readonly coreDatabasePath: string\n  /** DSH Session SQLite file path (host-owned). */\n  readonly sessionDatabasePath: string\n  /** Asset blob content-addressed storage root. */\n  readonly assetRoot: string\n  /** Local Extension source Revision root. */\n  readonly extensionDataRoot: string\n  /** Extension build-artifact cache root. */\n  readonly extensionCacheRoot: string\n  /** Managed DSH package installation root. Defaults to `<data>/dsh`. */\n  readonly dshPluginRoot?: string\n  /** Host-owned private credential directory; secrets never enter Core records. */\n  readonly credentialRoot?: string\n  /** DSH-owned model settings and credential documents. */\n  readonly llmSettingsPath?: string\n  readonly llmCredentialPath?: string\n  /** Absolute workspace root for explicitly granted development capabilities. */\n  readonly developmentWorkspaceRoot?: string\n  /** Inject a real or test LLM adapter into the DSH Host. */\n  readonly configureLlm?: (context: Context) => Promise<void> | void\n  /** Idle rollover threshold in ms; default 6h, `false` disables. */\n  readonly idleRolloverMs?: number | false\n  readonly now?: () => number\n  readonly nextUlid?: () => string\n  readonly notifications?: { readonly fetch?: typeof fetch }\n  /** NekroNXT 社区地址（默认正式社区）与测试用 fetch。 */\n  readonly community?: { readonly url?: string | undefined; readonly fetch?: typeof fetch }\n  /** Replaced by an offline Fake for tests and AI validation; production uses fetch/ws. */\n  readonly adapterTransport?: AdapterTransportService\n  /** Overrides first-party Adapter composition for isolated tests and custom hosts. */\n  readonly adapterContributions?: readonly AdapterHostContributionV2[]\n}\n\n/** One deliberate entity registry the domain API reads for its authoritative projection. */\nexport interface AgentEntity {\n  readonly agentId: AgentId\n  readonly channelId: ChannelId\n  readonly connectionId: ConnectionId\n  readonly revisionId: string\n  readonly createdAt: number\n}\n\n/** `<root>/<agentId>`; rejects ids that could escape the root. */\nexport const agentWorkspacePath = (root: string, agentId: AgentId): string => {\n  if (agentId === '.' || agentId === '..' || /[\\\\/]/u.test(agentId)) throw new Error(`无效的智能体 ID：${agentId}`)\n  return path.join(root, agentId)\n}\n\n/** Stored hook decision in the Channel Runtime shape. */\nconst inboundDecision = (record: InboundHookDecisionRecord): InboundHookDecision => ({\n  trigger: record.trigger,\n  hidden: record.hidden,\n  ...(record.annotation === null ? {} : { annotation: record.annotation }),\n  ...(record.hostAnnotations === null || record.hostAnnotations === undefined || record.hostAnnotations.length === 0\n    ? {}\n    : { hostAnnotations: record.hostAnnotations }),\n})\n\nexport class NekroRuntime {\n  readonly #unsubscribeLogFacts: (() => void) | undefined\n  readonly logs: HostLogService | undefined\n  readonly feedback: CommunityFeedbackService\n  upgradeBackupId: string | undefined\n  readonly repository: SqliteCoreRepository\n  readonly compatibility: RuntimeCompatibilityRegistry\n  readonly hostSecurity: SqliteHostSecurityRepository\n  readonly assetService: AssetService\n  readonly core: CoreService\n  readonly authoring: AuthoringApplicationService\n  readonly host: DshHostRuntime\n  readonly channels: ChannelRuntime\n  readonly commands: CommandService\n  readonly internalConnectionId: ConnectionId\n  /** Parent of every agent workspace (`<root>/<agentId>/`). */\n  readonly workspaceRoot: string\n  /** Directory of the Core database: the Host's data root. */\n  readonly dataRoot: string\n  readonly extensionService: ExtensionService\n  /** Install, enable, switch and remove Extensions (one host instance plus agent attachments each). */\n  readonly extensions: ExtensionLifecycleCoordinator\n  /** Data versions, copies, migrations and data packages of installed extensions. */\n  readonly extensionData: ExtensionDataService\n  /** Which community release each local version is, and what the newest public release means here. */\n  readonly communitySync: CommunitySyncService\n  /** Lifecycle actions shared by the workshop, `/ext` commands and agent tools. */\n  readonly extensionActions: ExtensionActionService\n  /** Requests administrators confirm, and the record of what agents did on their own. */\n  readonly extensionRequests: ExtensionRequestService\n  /** Instance administrators: the console plus listed platform accounts. */\n  readonly administrators: AdministratorService\n  /** Set by the Host routes so request changes reach the Web. */\n  publishExtensionRequestChange: (() => void) | undefined\n  /** Restarting the service (#123); set by the executable host once it listens, absent in embedded and test hosts. */\n  hostRestart: HostRestart | undefined\n  /** Configuration writes of every source and their history. */\n  readonly extensionConfig: ExtensionConfigService\n  /** Set by the Host routes so configuration written outside a request reaches the Web. */\n  publishExtensionsChange: (() => void) | undefined\n  readonly credentials: LocalCredentialStore\n  readonly notifications: NotificationService\n  readonly community: CommunityService\n  readonly dshPluginInstaller: DshPluginPackageInstaller\n  readonly sessionStoragePreparation: DshSessionStoragePreparation\n  readonly sessionStorageRetirement: DshSessionStorageRetirementReport | undefined\n  readonly #database: CoreDatabase\n  readonly #now: () => number\n  readonly connections: ConnectionApplicationService\n  readonly adapters: AdapterRegistry\n  readonly #jobScheduler: ExtensionJobScheduler\n  readonly scheduledTasks: ScheduledTasks\n  readonly channelPrompts: ChannelPrompts\n  readonly mcpStatus: McpStatusRegistry\n  /** The agent's outbound processors: every agent message passes them before sending and after delivery. */\n  readonly outbound: ExtensionOutboundProcessor\n  /** Work files of installed extensions; host services that run programs read and create them by `fileId`. */\n  readonly extensionFiles: ExtensionFileStore\n  readonly #previewFiles: ExtensionFileStore\n  readonly authoringTestConfig: AuthoringTestConfig\n  readonly codeRunNode: CodeRunNode\n  readonly githubCli: GithubCli\n  readonly verificationBrowser: VerificationBrowser\n  #verificationOrigin: string | undefined\n  #candidateVerifier: CandidateVerifier | undefined\n  #subConversationChanges = new Set<() => void>()\n  #subConversationSweep: ReturnType<typeof setInterval> | undefined\n  /** Named credentials. */\n  readonly credentialLibrary: CredentialLibrary\n  /** Linked third-party accounts, granted to agents' commands per agent. */\n  readonly linkedAccounts: LinkedAccountLibrary\n  /** Credentials agents asked for that nobody has added yet. */\n  readonly credentialRequests: CredentialRequests\n  /** Which model providers agents and extensions may call through the host. */\n  readonly modelProviderAccess: ModelProviderAccess\n  readonly retrieval: RetrievalRuntime\n  readonly addons: AddonRegistry\n  /** Speech to text with the provider the `speech` add-on uses. */\n  readonly speech: SpeechService\n  readonly speechCloud: SpeechCloud\n  readonly #localSpeech: LocalSpeech\n  /** Host-side media processing on the `media` add-on (附加功能 F8). */\n  readonly media: MediaToolkit\n  /** Programs of the add-ons run by their command profiles (附加功能 F7). */\n  readonly commandProfiles: CommandProfiles\n  readonly #disposePrograms: () => Promise<void>\n  readonly #hostClientDiagnostics = new Map<\n    ExtensionId,\n    {\n      readonly revisionId: ExtensionRevisionId\n      readonly status: 'loaded' | 'failed'\n      readonly message?: string\n      readonly observedAt: number\n    }\n  >()\n  readonly #agents = new Map<AgentId, AgentEntity>()\n  #commandGovernance: ExtensionCommandPort | undefined\n  readonly #unsubscribeDynamicApproval: () => void\n  #started = false\n  #reviewWatch: ReturnType<typeof setInterval> | undefined\n  #disposed = false\n  #disposePromise: Promise<void> | undefined\n\n  private constructor(input: {\n    readonly logs?: HostLogService\n    readonly feedbackEnvironment?: FeedbackEnvironment | undefined\n    readonly database: CoreDatabase\n    readonly deferCommandExecution: boolean\n    readonly compatibility: RuntimeCompatibilityRegistry\n    readonly repository: SqliteCoreRepository\n    readonly hostSecurity: SqliteHostSecurityRepository\n    readonly assetService: AssetService\n    readonly core: CoreService\n    readonly host: DshHostRuntime\n    readonly channels: ChannelRuntime\n    readonly internalConnectionId: ConnectionId\n    readonly workspaceRoot: string\n    readonly dataRoot: string\n    readonly extensionService: ExtensionService\n    readonly extensionBuilder: ExtensionBuilder\n    readonly adapterPort: { current?: PersistentAdapterPort }\n    readonly credentials: LocalCredentialStore\n    readonly notifications: NotificationService\n    readonly community: CommunityService\n    readonly dshPluginInstaller: DshPluginPackageInstaller\n    readonly unsubscribeDynamicApproval: () => void\n    readonly sessionStoragePreparation: DshSessionStoragePreparation\n    readonly sessionStorageRetirement?: DshSessionStorageRetirementReport\n    readonly now: () => number\n    readonly adapters: AdapterRegistry\n    readonly jobScheduler: ExtensionJobScheduler\n    readonly scheduledTasks: ScheduledTasks\n    readonly channelPrompts: ChannelPrompts\n    readonly mcpStatus: McpStatusRegistry\n    readonly outbound: ExtensionOutboundProcessor\n    readonly extensionFiles: ExtensionFileStore\n    readonly previewFiles: ExtensionFileStore\n    readonly authoringTestConfig: AuthoringTestConfig\n    readonly codeRunNode: CodeRunNode\n    readonly githubCli: GithubCli\n    readonly verificationBrowser: VerificationBrowser\n    readonly credentialLibrary: CredentialLibrary\n    readonly linkedAccounts: LinkedAccountLibrary\n    readonly credentialRequests: CredentialRequests\n    readonly modelProviderAccess: ModelProviderAccess\n    readonly retrieval: RetrievalRuntime\n    readonly addons: AddonRegistry\n    readonly speech: SpeechService\n    readonly speechCloud: SpeechCloud\n    readonly localSpeech: LocalSpeech\n    readonly media: MediaToolkit\n    readonly commandProfiles: CommandProfiles\n    readonly disposePrograms: () => Promise<void>\n    readonly adapterHandles: readonly RegisteredAdapterHandle[]\n    readonly adapterRuntimes: Map<ConnectionId, AdapterConnectionRuntime>\n    readonly adapterTransport: AdapterTransportService\n  }) {\n    this.logs = input.logs\n    this.#database = input.database\n    this.repository = input.repository\n    this.hostSecurity = input.hostSecurity\n    this.assetService = input.assetService\n    this.core = input.core\n    this.host = input.host\n    this.authoring = new AuthoringApplicationService(this)\n    this.channels = input.channels\n    this.commands = new CommandService({\n      deferExecution: input.deferCommandExecution,\n      repository: this.repository,\n      core: this.core,\n      channels: () => this.channels,\n      ...(input.logs === undefined\n        ? {}\n        : {\n            observer: commandLogObserver(input.logs, (channelId) => this.repository.getChannel(channelId)?.displayName),\n          }),\n      now: input.now,\n      running: (id) => this.host.sessionStatus(id) === 'running',\n      extensions: (agentId) => this.#extensionCommands(agentId),\n      governance: () => this.#commandGovernance,\n      compactionThreshold: () => this.host,\n      botMemberId: (event) =>\n        commandBotMember(event, {\n          core: this.core,\n          channel: (channelId) => this.repository.getChannel(channelId),\n          account: (connectionId) =>\n            this.connections.adapterConnectionDiagnostic(connectionId)?.accountReference ??\n            this.repository.getConnection(connectionId)?.accountKey,\n        }),\n    })\n    if (input.logs) {\n      const observed = new Map<string, string>()\n      this.#unsubscribeLogFacts = this.channels.subscribeFacts((fact) => {\n        if (fact.kind !== 'outbound') return\n        try {\n          const { intent, deliveries } = this.repository.getOutbound(OutboundIntentIdSchema.parse(fact.sourceId))\n          const delivered = deliveries.filter((delivery) => delivery.state === 'sent').length\n          const signature = `${intent.state}:${delivered}`\n          if (observed.get(intent.id) === signature) return\n          if (observed.size >= 1000) observed.delete(observed.keys().next().value!)\n          observed.set(intent.id, signature)\n          const admin = isAdminConsoleOutbound(intent.sourceTurnId)\n          const agentId =\n            admin || intent.agentRevisionId === undefined\n              ? undefined\n              : this.repository.getAgentRevision(intent.agentRevisionId)?.agentId\n          const channel = this.core.getChannel(fact.channelId)\n          const connectionId = channel?.connectionId\n          const summary = {\n            planned: '消息已排队',\n            sending: '正在发送消息',\n            sent: '消息已送达',\n            'partially-sent': '消息部分送达',\n            failed: '消息发送失败',\n            unknown: '消息是否送达尚未确认',\n          } as const\n          const failures = deliveries.flatMap(({ sequence, receipt }) => {\n            if (receipt?.status === 'failed') return [{ sequence, ...receipt.failure, diagnostic: receipt.diagnostic }]\n            if (receipt?.status === 'unknown')\n              return [{ sequence, kind: 'unknown', message: receipt.message, diagnostic: receipt.diagnostic }]\n            return []\n          })\n          const reason = failures[0]?.message\n          const target = channel?.displayName ?? '频道'\n          input.logs!.write({\n            level:\n              intent.state === 'failed'\n                ? 'error'\n                : intent.state === 'unknown' || intent.state === 'partially-sent'\n                  ? 'warn'\n                  : 'debug',\n            message: `${target} · ${summary[intent.state]}（${delivered}/${deliveries.length} 条已送达）${reason ? `：${reason}` : ''}`,\n            source: { kind: 'system', id: 'delivery', name: '消息投递' },\n            scope: {\n              channelId: fact.channelId,\n              episodeId: intent.episodeId,\n              operationId: intent.id,\n              ...(agentId ? { agentId } : {}),\n              ...(connectionId ? { connectionId } : {}),\n            },\n            details: {\n              actor: admin ? 'admin' : intent.commandExecutionId === undefined ? 'agent' : 'command',\n              state: intent.state,\n              delivered,\n              total: deliveries.length,\n              failures: failures.slice(0, 20),\n            },\n          })\n        } catch {\n          /* A diagnostic observer must not change delivery outcomes. */\n        }\n      })\n    }\n    this.internalConnectionId = input.internalConnectionId\n    this.workspaceRoot = input.workspaceRoot\n    this.dataRoot = input.dataRoot\n    this.extensionService = input.extensionService\n    this.credentials = input.credentials\n    this.notifications = input.notifications\n    this.community = input.community\n    this.dshPluginInstaller = input.dshPluginInstaller\n    this.#unsubscribeDynamicApproval = input.unsubscribeDynamicApproval\n    this.compatibility = input.compatibility\n    this.sessionStoragePreparation = input.sessionStoragePreparation\n    this.sessionStorageRetirement = input.sessionStorageRetirement\n    this.#now = input.now\n    this.adapters = input.adapters\n    this.#jobScheduler = input.jobScheduler\n    this.scheduledTasks = input.scheduledTasks\n    this.codeRunNode = input.codeRunNode\n    this.githubCli = input.githubCli\n    this.verificationBrowser = input.verificationBrowser\n    this.credentialLibrary = input.credentialLibrary\n    this.linkedAccounts = input.linkedAccounts\n    this.credentialRequests = input.credentialRequests\n    this.modelProviderAccess = input.modelProviderAccess\n    this.retrieval = input.retrieval\n    this.addons = input.addons\n    this.speech = input.speech\n    this.speechCloud = input.speechCloud\n    this.#localSpeech = input.localSpeech\n    this.media = input.media\n    this.commandProfiles = input.commandProfiles\n    this.#disposePrograms = input.disposePrograms\n    this.channelPrompts = input.channelPrompts\n    this.mcpStatus = input.mcpStatus\n    this.outbound = input.outbound\n    this.extensionFiles = input.extensionFiles\n    this.#previewFiles = input.previewFiles\n    this.authoringTestConfig = input.authoringTestConfig\n    this.feedback = new CommunityFeedbackService(\n      this.repository,\n      this.community,\n      runtimeFeedbackSources(this, input.feedbackEnvironment ?? { hostKind: 'server', releaseId: 'development' }),\n      input.now,\n    )\n    this.connections = new ConnectionApplicationService(\n      this,\n      input.now,\n      input.adapterRuntimes,\n      input.adapterTransport,\n      input.adapterHandles,\n      () => ({ started: this.#started, disposed: this.#disposed }),\n    )\n    input.adapterPort.current = {\n      register: (owner, contribution) => this.registerAdapter(owner, contribution),\n      mountConnections: (adapterKey) => this.mountAdapterConnections(adapterKey),\n    }\n    this.extensionData = new ExtensionDataService({\n      repository: this.repository,\n      assets: this.assetService,\n      now: this.#now,\n    })\n    this.administrators = new AdministratorService({\n      repository: this.repository,\n      now: this.#now,\n      connectionName: (connectionId) => {\n        const connection = this.repository.getConnection(connectionId)\n        return (\n          connection?.alias ?? this.adapters.get(connection?.adapterKey ?? '')?.descriptor.displayName ?? '平台连接'\n        )\n      },\n    })\n    this.publishExtensionRequestChange = undefined\n    this.hostRestart = undefined\n    this.publishExtensionsChange = undefined\n    this.extensions = new ExtensionLifecycleCoordinator(\n      this.repository,\n      this.extensionService,\n      input.extensionBuilder,\n      new ChannelExtensionRuntimeHost(this.channels, this.host, {\n        waitUntilSafe: async (adapterKey) => {\n          await this.connections.waitUntilSafe(adapterKey)\n        },\n        assertKeyAvailable: (adapterKey, extensionId) => {\n          const registered = this.adapters.get(adapterKey)\n          const owned = this.adapters.getByOwner(`extension:${extensionId}`)\n          if (registered && registered !== owned) throw new Error(`Adapter key already registered: ${adapterKey}`)\n          return Promise.resolve()\n        },\n      }),\n      { now: this.#now, compatibility: this.compatibility, data: this.extensionData },\n    )\n    this.communitySync = new CommunitySyncService({\n      repository: this.repository,\n      community: this.community,\n      lineage: this.extensionService,\n      now: this.#now,\n    })\n    this.extensionActions = new ExtensionActionService(this)\n    this.extensionRequests = new ExtensionRequestService(this, this.#now)\n    this.extensionConfig = new ExtensionConfigService(this, this.#now)\n    this.#commandGovernance = new ExtensionCommandPort(this)\n  }\n\n  #extensionCommands(agentId: AgentId): readonly RegisteredCommand[] {\n    const activations = this.repository.listActivations(agentId)\n    const revisions = new Map(activations.map((activation) => [activation.extensionId, activation.extensionRevisionId]))\n    const commands = new Map<string, RegisteredCommand>()\n    for (const command of this.host.commandHandlers(agentId)) {\n      if (revisions.get(command.revision.extensionId) !== command.revision.id) continue\n      const fullName = `${command.revision.extensionId}:${command.definition.name}`\n      commands.set(fullName, {\n        definition: command.definition,\n        invoke: command.invoke,\n        fullName,\n        source: this.repository.getExtension(command.revision.extensionId)?.displayName ?? command.revision.extensionId,\n        extensionRevisionId: command.revision.id,\n      })\n    }\n    // Committed activations retain command identity while safe-gap waiting, detaching or restoring.\n    // Only a live attachment supplies an invocable handler; disabling removes the activation.\n    for (const activation of activations) {\n      const revision = this.repository.getExtensionRevision(activation.extensionRevisionId)\n      const manifest = revision === undefined ? undefined : this.extensionService.revisionManifest(revision)\n      for 