    {
      "path": "packages/core/src/index.ts",
      "content": "import type { AdapterChannelInboundEvent, AdapterConnectionInboundEvent } from '@nekro-nxt/adapter-sdk'\nimport type {\n  AgentId,\n  AgentRevisionId,\n  AssetId,\n  ChannelEventId,\n  AdapterActivityKey,\n  ChannelId,\n  ChannelMemberId,\n  ConnectionId,\n  ConnectionEventId,\n  JsonValue,\n  LogicalMessageId,\n  MessagePart,\n  PlatformIdentityId,\n  PromptDocumentV1,\n  ResponseTimingSettings,\n} from '@nekro-nxt/contracts'\nimport {\n  COMPACTION_THRESHOLD,\n  CompactionThresholdRatioSchema,\n  roundRatio,\n  AgentIdSchema,\n  AgentRevisionIdSchema,\n  AgentFallbackModelsSchema,\n  AgentAliasesSchema,\n  ResponseTimingSettingsSchema,\n  AgentSubConversationModelsSchema,\n  ChannelEventIdSchema,\n  AdapterActivityKeySchema,\n  ChannelIdSchema,\n  ChannelMemberIdSchema,\n  ConnectionIdSchema,\n  ConnectionEventIdSchema,\n  LogicalMessageIdSchema,\n  messagePartAssetIds,\n  messagePartsSearchText,\n  PlatformIdentityIdSchema,\n  normalizePromptDocument,\n  promptDocumentFromText,\n  promptDocumentPlainText,\n  PromptDocumentV1Schema,\n  JsonValueSchema,\n} from '@nekro-nxt/contracts'\nimport { createHash } from 'node:crypto'\nimport { monotonicFactory } from 'ulid'\nimport { z } from 'zod'\n\nexport * from './assets.js'\n\nexport interface AgentModelSelection {\n  readonly provider: string\n  readonly model: string\n  readonly reasoningEffort?: string | undefined\n}\n\nexport type ImageDetail = 'low' | 'auto' | 'high'\n\nexport interface ImageUnderstandingPolicy {\n  readonly history: {\n    readonly mode: 'persistent-distinct'\n    readonly detail: ImageDetail\n    readonly restoreAfterCompaction: {\n      readonly recentMessages: number\n      readonly maxImages: number\n    }\n  }\n  readonly textModel:\n    | { readonly mode: 'disabled' }\n    | {\n        readonly mode: 'auxiliary'\n        readonly model: AgentModelSelection\n        readonly maxTokens: number\n      }\n}\n\nexport type DynamicClientApprovalPolicy = 'manual' | 'automatic'\n\n/** Which model writes one kind of compaction summary: the kind's default, or a model chosen for this agent. */\nexport type AgentCompactionModelChoice =\n  { readonly mode: 'follow' } | { readonly mode: 'custom'; readonly model: AgentModelSelection }\n\n/**\n * The two compactions differ in what they can reuse. In-session compaction replays the conversation as the request\n * prefix, so following the main model (and its thinking level) keeps the provider's cache; compaction into a new\n * session writes a fresh transcript and by default follows the host's compaction model instead.\n */\nexport interface AgentCompactionPolicy {\n  readonly inSession: AgentCompactionModelChoice\n  readonly newSession: AgentCompactionModelChoice\n  /**\n   * Share of the context window at which the conversation compacts; omitted is the default. The current model's\n   * window narrows it when it is used, since the model can change after it is saved.\n   */\n  readonly thresholdRatio?: number | undefined\n}\n\n/** One model this agent may open a sub-conversation with, named so the agent can pick it. */\nexport interface SubConversationModelCandidate {\n  readonly name: string\n  readonly model: AgentModelSelection\n  /** What it is good for, shown to the agent when it chooses. */\n  readonly guidance: string\n}\n\n/**\n * Models this agent may open sub-conversations with. Without a `default`, a sub-conversation the agent opens without\n * naming a model follows the main model, as it did before candidates existed.\n */\nexport interface SubConversationModelPolicy {\n  readonly candidates: readonly SubConversationModelCandidate[]\n  readonly default?: string\n}\n\nexport interface AgentRevisionContent {\n  readonly displayName: string\n  readonly persona: string\n  readonly personaDocument?: PromptDocumentV1\n  readonly model: AgentModelSelection\n  readonly capabilities?: Partial<AgentCapabilityGrants>\n  readonly imagePolicy?: ImageUnderstandingPolicy\n  readonly dynamicClientApprovalPolicy?: DynamicClientApprovalPolicy\n  /** Omitted on revise keeps the current choices; omitted on create follows both defaults. */\n  readonly compaction?: AgentCompactionPolicy\n  /** Omitted on revise keeps the current candidates; omitted on create offers none. */\n  readonly subConversationModels?: SubConversationModelPolicy\n  /** Models to switch to, in order, when the main model fails; omitted on revise keeps them, on create none. */\n  readonly fallbackModels?: readonly AgentModelSelection[]\n  /** Extra names that wake the agent in smart mode; omitted on revise keeps them, on create none. */\n  readonly aliases?: readonly string[]\n}\n\n/** Non-versioned presentation of an intelligent agent; never part of an AgentRevision. */\nexport interface AgentAppearance {\n  /** Identity hue in degrees, 0–359. */\n  readonly hue?: number\n  readonly avatarAssetId?: AssetId\n}\n\nexport interface AgentDefinitionRecord {\n  readonly id: AgentId\n  readonly currentRevisionId: AgentRevisionId\n  readonly createdAt: number\n  readonly appearance?: AgentAppearance\n}\n\nexport interface AgentRevisionRecord extends Omit<\n  AgentRevisionContent,\n  | 'capabilities'\n  | 'imagePolicy'\n  | 'personaDocument'\n  | 'compaction'\n  | 'subConversationModels'\n  | 'fallbackModels'\n  | 'aliases'\n> {\n  readonly id: AgentRevisionId\n  readonly agentId: AgentId\n  readonly revision: number\n  readonly capabilities: AgentCapabilityGrants\n  readonly imagePolicy: ImageUnderstandingPolicy\n  readonly dynamicClientApprovalPolicy: DynamicClientApprovalPolicy\n  readonly compaction: AgentCompactionPolicy\n  readonly subConversationModels: SubConversationModelPolicy\n  readonly fallbackModels: readonly AgentModelSelection[]\n  readonly aliases: readonly string[]\n  readonly personaDocument: PromptDocumentV1\n  readonly contentDigest: string\n  readonly createdAt: number\n}\n\nexport interface ConnectionRecord {\n  readonly id: ConnectionId\n  readonly adapterKey: string\n  /** Stable Adapter-scoped account identity used to prevent duplicate active Connections. */\n  readonly accountKey?: string\n  /** Optional user-facing identifier; the Adapter still owns platform identity. */\n  readonly alias?: string\n  readonly config: JsonValue\n  readonly credentialRefs: Readonly<Record<string, string>>\n  readonly activityTriggerDefaults: readonly AdapterActivityKey[]\n  readonly createdAt: number\n}\n\nexport interface ArchivedConnectionRecord extends ConnectionRecord {\n  readonly archivedAt: number\n}\n\nexport interface ChannelRecord {\n  readonly id: ChannelId\n  readonly connectionId: ConnectionId\n  readonly platformChannelId: string\n  readonly kind: 'internal' | 'direct' | 'group'\n  readonly displayName?: string\n  readonly localDisplayName?: string\n  readonly platformDisplayName?: string\n  readonly preferredProcessingFeedback?: 'auto' | 'off'\n  /** Set only for the built-in Channel atomically created with this intelligent-agent. */\n  readonly autoCreatedForAgentId?: AgentId\n  readonly createdAt: number\n}\n\n/** A channel lookup used by stable references, including tombstoned rows. */\nexport interface ChannelReferenceRecord {\n  readonly channel: ChannelRecord\n  readonly removed: boolean\n}\n\nexport interface PlatformIdentityRecord {\n  readonly id: PlatformIdentityId\n  readonly connectionId: ConnectionId\n  readonly platformUserId: string\n  readonly displayName?: string\n  /**\n   * The connection's own account. `member`: the Adapter marked this platform user as itself; `account`: the platform\n   * user id the Adapter reported for the whole connection (at most one per connection).\n   */\n  readonly self?: 'member' | 'account'\n}\n\n/**\n * Platform user id of the stand-in identity for a connection's own account when the Adapter cannot tell its real id.\n * It is never handed back to an Adapter as a platform user id.\n */\nexport const SELF_PLACEHOLDER_PLATFORM_USER_ID = 'nxt:self'\n\nexport interface ChannelMemberRecord {\n  readonly id: ChannelMemberId\n  readonly channelId: ChannelId\n  readonly platformIdentityId: PlatformIdentityId\n  readonly displayName?: string\n}\n\nexport interface PlatformUserDirectoryRecord {\n  readonly identityId: PlatformIdentityId\n  readonly displayName?: string\n  readonly connection: {\n    readonly id: ConnectionId\n    readonly adapterKey: string\n    readonly alias?: string\n    readonly createdAt: number\n  }\n  readonly activeChannels: readonly {\n    readonly id: ChannelId\n    readonly kind: ChannelRecord['kind']\n    readonly displayName?: string\n  }[]\n  readonly historicalOnly: boolean\n}\n\nexport type BindingTriggerPolicy = 'always' | 'mentioned-or-replied' | 'smart' | 'command' | 'observe-only'\n\nexport interface BindingRecord {\n  readonly channelId: ChannelId\n  readonly agentId: AgentId\n  readonly triggerPolicy: BindingTriggerPolicy\n  /**\n   * Channel-scoped pause, independent of the response rule: every automatic trigger (messages, platform events,\n   * jobs, extension wake-ups) is ignored while true. Kept across rule edits, reset when the agent changes.\n   */\n  readonly paused: boolean\n  readonly processingFeedback: 'auto' | 'off'\n  /** Messages from another local agent's account: `observe` keeps them as context unless they @ or reply to this agent. */\n  readonly localAgentMessages: 'observe' | 'trigger'\n  /** Missing keys inherit the concrete Connection default. */\n  readonly activityTriggerOverrides: Readonly<Record<AdapterActivityKey, boolean>>\n  /** When the agent speaks: waiting for a speaker to finish, and smart-mode wakes. Missing keys use the defaults. */\n  readonly responseTiming: ResponseTimingSettings\n  readonly boundAt: number\n}\n\nexport interface ChannelEventRecord {\n  readonly id: ChannelEventId\n  readonly logicalMessageId: LogicalMessageId\n  readonly channelId: ChannelId\n  readonly platformMessageId?: string\n  readonly kind: AdapterChannelInboundEvent['kind']\n  readonly activityKey?: AdapterActivityKey\n  readonly targetPlatformMessageId?: string\n  readonly targetLogicalMessageId?: LogicalMessageId\n  readonly senderMemberId?: AdapterChannelInboundEvent['senderMemberId']\n  readonly parts: readonly MessagePart[]\n  readonly sourceTimestamp: number\n  readonly receivedAt: number\n  readonly dedupeKey: string\n  readonly facts?: Readonly<Record<string, JsonValue>>\n  readonly searchText: string\n}\n\nexport interface ConnectionEventRecord {\n  readonly id: ConnectionEventId\n  readonly connectionId: ConnectionId\n  readonly activityKey: AdapterActivityKey\n  readonly summary: string\n  readonly actorIdentityId?: PlatformIdentityId\n  readonly subjectIdentityId?: PlatformIdentityId\n  readonly sourceTimestamp: number\n  readonly receivedAt: number\n  readonly dedupeKey: string\n  readonly facts?: Readonly<Record<string, JsonValue>>\n}\n\nexport interface PlatformMessageReferenceRecord {\n  readonly logicalMessageId: LogicalMessageId\n  readonly authoredByAgent: boolean\n}\n\nexport interface CreateAgentCommit {\n  readonly definition: AgentDefinitionRecord\n  readonly revision: AgentRevisionRecord\n}\n\nexport interface CreateAgentWithChannelCommit extends CreateAgentCommit {\n  readonly channel: ChannelRecord\n  readonly binding: BindingRecord\n}\n\nexport interface AppendChannelEventCommit {\n  readonly event: ChannelEventRecord\n  readonly inserted: boolean\n}\n\nexport interface AppendConnectionEventCommit {\n  readonly event: ConnectionEventRecord\n  readonly inserted: boolean\n}\n\nexport interface CoreRepository {\n  createAgent(commit: CreateAgentCommit): void\n  createAgentWithChannel(commit: CreateAgentWithChannelCommit): void\n  tombstoneAgent(id: AgentId, deletedAt: number): void\n  updateAgentAppearance(id: AgentId, appearance: AgentAppearance, updatedAt: number): void\n  getAgent(id: AgentId): CreateAgentCommit | undefined\n  listAgents(): readonly CreateAgentCommit[]\n  getAgentRevision(id: AgentRevisionId): AgentRevisionRecord | undefined\n  getAgentRevisionByDigest(agentId: AgentId, contentDigest: string): AgentRevisionRecord | undefined\n  listAgentRevisions(agentId: AgentId): readonly AgentRevisionRecord[]\n  getNextAgentRevisionNumber(agentId: AgentId): number\n  appendAgentRevision(\n    definition: AgentDefinitionRecord,\n    revision: AgentRevisionRecord,\n    expectedCurrentRevisionId: AgentRevisionId,\n  ): void\n  activateAgentRevision(\n    definition: AgentDefinitionRecord,\n    revision: AgentRevisionRecord,\n    expectedCurrentRevisionId: AgentRevisionId,\n  ): void\n  createConnection(record: ConnectionRecord): void\n  updateConnectionAlias(id: ConnectionId, alias?: string): void\n  updateConnectionConfig(id: ConnectionId, config: JsonValue): void\n  updateConnectionProvisioning(\n    id: ConnectionId,\n    config: JsonValue,\n    credentialRefs: Readonly<Record<string, string>>,\n  ): void\n  updateConnectionActivityTriggerDefaults(id: ConnectionId, activityKeys: readonly AdapterActivityKey[]): void\n  archiveConnection(id: ConnectionId, archivedAt: number): void\n  restoreConnection(id: ConnectionId): void\n  purgeConnection(id: ConnectionId): void\n  getConnection(id: ConnectionId): ConnectionRecord | undefined\n  getArchivedConnection(id: ConnectionId): ArchivedConnectionRecord | undefined\n  listArchivedConnections(): readonly ArchivedConnectionRecord[]\n  listConnectionIdsByAdapter(adapterKey?: string): readonly ConnectionId[]\n  appendConnectionEvent(candidate: ConnectionEventRecord): AppendConnectionEventCommit\n  listConnectionEvents(\n    connectionId: ConnectionId,\n    options?: {\n      readonly before?: { readonly receivedAt: number; readonly id: ConnectionEventId }\n      readonly limit?: number\n    },\n  ): readonly ConnectionEventRecord[]\n  createChannel(record: ChannelRecord): void\n  ensureChannel(record: ChannelRecord): ChannelRecord\n  tombstoneChannel(id: ChannelId, deletedAt: number): void\n  updateChannelDisplayName(id: ChannelId, displayName: string, source?: 'local' | 'platform'): void\n  getChannel(id: ChannelId): ChannelRecord | undefined\n  getChannelByPlatformId(connectionId: ConnectionId, platformChannelId: string): ChannelRecord | undefined\n  listChannelIdsByConnection(connectionId: ConnectionId): readonly ChannelId[]\n  /** Inserts or refreshes an identity; a `self` mark is only ever raised here, never cleared. */\n  ensurePlatformIdentity(record: PlatformIdentityRecord): PlatformIdentityRecord\n  getPlatformIdentity(id: PlatformIdentityId): PlatformIdentityRecord | undefined\n  /** Makes one identity the connection's reported account; the previous account identity stays a `member` self. */\n  markAccountIdentity(connectionId: ConnectionId, identityId: PlatformIdentityId): void\n  getAccountIdentity(connectionId: ConnectionId): PlatformIdentityRecord | undefined\n  /** The channel member backed by a self identity: the account first, then a real member, then the placeholder. */\n  findSelfChannelMember(channelId: ChannelId): ChannelMemberRecord | undefined\n  listPlatformUsers(): readonly PlatformUserDirectoryRecord[]\n  ensureChannelMember(record: ChannelMemberRecord): ChannelMemberRecord\n  getChannelMember(id: ChannelMemberId): ChannelMemberRecord | undefined\n  getChannelMemberByIdentity(\n    channelId: ChannelId,\n    platformIdentityId: PlatformIdentityId,\n  ): ChannelMemberRecord | undefined\n  replaceBinding(record: BindingRecord): BindingRecord\n  clearBinding(channelId: ChannelId): void\n  getBinding(channelId: ChannelId): BindingRecord | undefined\n  listBindings(channelId: ChannelId): readonly BindingRecord[]\n  appendChannelEvent(\n    candidate: ChannelEventRecord,\n    assetOccurrences?: readonly { readonly partIndex: number; readonly assetId: AssetId }[],\n  ): AppendChannelEventCommit\n  getChannelEvent(id: ChannelEventId): ChannelEventRecord | undefined\n  listChannelEvents(\n    channelId: ChannelId,\n    options?: {\n      readonly before?: { readonly receivedAt: number; readonly id: ChannelEventId }\n      readonly limit?: number\n    },\n  ): readonly ChannelEventRecord[]\n  resolvePlatformMessage(\n    connectionId: ConnectionId,\n    channelId: ChannelId,\n    platformMessageId: string,\n  ): PlatformMessageReferenceRecord | undefined\n  resolveLogicalMessage(\n    connectionId: ConnectionId,\n    channelId: ChannelId,\n    logicalMessageId: LogicalMessageId,\n  ): PlatformMessageReferenceRecord | undefined\n  resolveLogicalMessagePlatformId(\n    connectionId: ConnectionId,\n    channelId: ChannelId,\n    logicalMessageId: LogicalMessageId,\n  ): string | undefined\n}\n\nexport interface CoreServiceOptions {\n  readonly now?: () => number\n  readonly nextUlid?: () => string\n}\n\n/** What the user wants an account used for. Told to the agent only; the token's own permissions are the limit. */\nexport const COMMAND_ACCOUNT_USAGES = ['read', 'issues', 'pull-requests', 'push'] as const\nexport const CommandAccountUsageSchema = z.enum(COMMAND_ACCOUNT_USAGES)\n\n/**\n * One linked account the agent's commands act as; the account itself lives in the host's 关联账号 library. `service`\n * is the platform. Grants saved before linked accounts name the account without its `acc_` prefix; the host resolves\n * both forms.\n */\nexport const CommandAccountGrantSchema = z\n  .object({\n    service: z.literal('github'),\n    accountId: z.string().trim().min(1).max(72),\n    /** Empty gives the agent no hint about use. */\n    usage: z.array(CommandAccountUsageSchema).max(4).default([]),\n  })\n  .strict()\n\nexport type CommandAccountGrant = z.infer<typeof CommandAccountGrantSchema>\n\nexport const AgentCapabilityGrantsSchema = z\n  .object({\n    subagents: z.boolean().default(false),\n    fileTools: z.boolean().default(false),\n    webSearch: z.boolean().default(false),\n    dynamicCreation: z.boolean().default(false),\n    developmentShell: z.boolean().default(false),\n    unrestrictedFileAccess: z.boolean().default(false),\n    /** Chat-created scheduled tasks; on unless the user turns it off (absent in Revisions before the field). */\n    scheduledTasks: z.boolean().default(true),\n    /** Tool calls from one TypeScript program; only takes effect with `developmentShell`. */\n    codeRun: z.boolean().default(false),\n    /** Network for commands and `run_code` programs; on unless the user turns it off (absent before the field). */\n    commandNetwork: z.boolean().default(true),\n    /** Only administrator-initiated channel turns may send feedback without confirmation. */\n    communityFeedbackAuto: z.boolean().default(false),\n    /** Voice messages are transcribed for the agent when they arrive (附加功能 F10). */\n    voiceTranscription: z.boolean().default(false),\n    /**\n     * How far the agent may take extension work on its own: `manual` stops at a verified candidate; `confirm` lets it\n     * save, enable and switch after an administrator confirms in chat; `autonomous` lets it do so itself while the\n     * extension needs only normal permissions.\n     */\n    extensionAutonomy: z.enum(['manual', 'confirm', 'autonomous']).default('manual'),\n    /** Whose messages may start or change extension work: every channel member, or administrators only. */\n    extensionRequesters: z.enum(['everyone', 'admins']).default('everyone'),\n    /**\n     * Whose messages may make the agent change extension configuration. Members may only cause changes to ordinary\n     * fields of the agent's own configuration even with `everyone`.\n     */\n    extensionConfigRequesters: z.enum(['everyone', 'admins']).default('admins'),\n    /** Linked accounts commands act as, one per platform; empty unless the user grants one (absent before the field). */\n    commandAccounts: z\n      .array(CommandAccountGrantSchema)\n      .max(8)\n      .refine((grants) => new Set(grants.map((grant) => grant.service)).size === grants.length, {\n        message: '每个平台只能授权一个账号。',\n      })\n      .default([]),\n  })\n  .strict()\n  .default({\n    subagents: false,\n    fileTools: false,\n    webSearch: false,\n    dynamicCreation: false,\n    developmentShell: false,\n    unrestrictedFileAccess: false,\n    scheduledTasks: true,\n    codeRun: false,\n    commandNetwork: true,\n    communityFeedbackAuto: false,\n    voiceTranscription: false,\n    extensionAutonomy: 'manual',\n    extensionRequesters: 'everyone',\n    extensionConfigRequesters: 'admins',\n    commandAccounts: [],\n  })\n\nexport type AgentCapabilityGrants = z.infer<typeof AgentCapabilityGrantsSchema>\n\n/** Default-off additions are absent from persisted capabilities so older readers keep accepting unchanged agents. */\nexport type StoredAgentCapabilityGrants = Omit<\n  AgentCapabilityGrants,\n  | 'communityFeedbackAuto'\n  | 'voiceTranscription'\n  | 'extensionAutonomy'\n  | 'extensionRequesters'\n  | 'extensionConfigRequesters'\n> & {\n  readonly communityFeedbackAuto?: boolean\n  readonly voiceTranscription?: boolean\n  readonly extensionAutonomy?: AgentCapabilityGrants['extensionAutonomy']\n  readonly extensionRequesters?: AgentCapabilityGrants['extensionRequesters']\n  readonly extensionConfigRequesters?: AgentCapabilityGrants['extensionConfigRequesters']\n}\nexport const storedAgentCapabilityGrants = (capabilities: AgentCapabilityGrants): StoredAgentCapabilityGrants => {\n  const {\n    communityFeedbackAuto,\n    voiceTranscription,\n    extensionAutonomy,\n    extensionRequesters,\n    extensionConfigRequesters,\n    ...existing\n  } = capabilities\n  return {\n    ...existing,\n    ...(communityFeedbackAuto ? { communityFeedbackAuto: true } : {}),\n    ...(voiceTranscription ? { voiceTranscription: true } : {}),\n    ...(extensionAutonomy === 'manual' ? {} : { extensionAutonomy }),\n    ...(extensionRequesters === 'everyone' ? {} : { extensionRequesters }),\n    ...(extensionConfigRequesters === 'admins' ? {} : { extensionConfigRequesters }),\n  }\n}\n\nconst AgentModelSelectionSchema = z\n  .object({\n    provider: z.string().trim().min(1),\n    model: z.string().trim().min(1),\n    reasoningEffort: z.string().trim().min(1).optional(),\n  })\n  .strict()\n\nexport const ImageUnderstandingPolicySchema = z\n  .object({\n    history: z\n      .object({\n        mode: z.literal('persistent-distinct').default('persistent-distinct'),\n        detail: z.enum(['low', 'auto', 'high']).default('auto'),\n        restoreAfterCompaction: z\n          .object({\n            recentMessages: z.number().int().min(1).max(100).default(32),\n            maxImages: z.number().int().min(0).max(50).default(12),\n          })\n          .strict()\n          .default({ recentMessages: 32, maxImages: 20 }),\n      })\n      .strict()\n      .default({\n        mode: 'persistent-distinct',\n        detail: 'auto',\n        restoreAfterCompaction: { recentMessages: 32, maxImages: 12 },\n      }),\n    textModel: z\n      .discriminatedUnion('mode', [\n        z.object({ mode: z.literal('disabled') }).strict(),\n        z\n          .object({\n            mode: z.literal('auxiliary'),\n            model: AgentModelSelectionSchema,\n            maxTokens: z.number().int().min(256).max(8192).default(2048),\n          })\n          .strict(),\n      ])\n      .default({ mode: 'disabled' }),\n  })\n  .strict()\n  .default({\n    history: {\n      mode: 'persistent-distinct',\n      detail: 'auto',\n      restoreAfterCompaction: { recentMessages: 32, maxImages: 12 },\n    },\n    textModel: { mode: 'disabled' },\n  })\n\nexport const DEFAULT_IMAGE_UNDERSTANDING_POLICY: ImageUnderstandingPolicy =\n  ImageUnderstandingPolicySchema.parse(undefined)\n\nexport const DynamicClientApprovalPolicySchema = z.enum(['manual', 'automatic']).default('manual')\n\nconst AgentCompactionModelChoiceSchema = z.discriminatedUnion('mode', [\n  z.object({ mode: z.literal('follow') }).strict(),\n  z.object({ mode: z.literal('custom'), model: AgentModelSelectionSchema }).strict(),\n])\n\nexport const DEFAULT_AGENT_COMPACTION_POLICY: AgentCompactionPolicy = {\n  inSession: { mode: 'follow' },\n  newSession: { mode: 'follow' },\n}\n\nexport const AgentCompactionPolicySchema = z\n  .object({\n    inSession: AgentCompactionModelChoiceSchema,\n    newSession: AgentCompactionModelChoiceSchema,\n    thresholdRatio: CompactionThresholdRatioSchema.optional(),\n  })\n  .strict()\n  .default(DEFAULT_AGENT_COMPACTION_POLICY)\n\n/** Whether a policy follows every default, which is how every Revision written before these choices reads. */\nexport const isDefaultCompactionPolicy = (policy: AgentCompactionPolicy): boolean =>\n  policy.inSession.mode === 'follow' && policy.newSession.mode === 'follow' && policy.thresholdRatio === undefined\n\n/** Two decimals, and the default itself stored as no choice, so picking 80 % again leaves the Revision unchanged. */\nconst thresholdChoice = (ratio: number | undefined): { readonly thresholdRatio?: number } => {\n  if (ratio === undefined) return {}\n  const rounded = roundRatio(ratio)\n  return rounded === COMPACTION_THRESHOLD.default ? {} : { thresholdRatio: rounded }\n}\n\nexport const DEFAULT_SUB_CONVERSATION_MODEL_POLICY: SubConversationModelPolicy = { candidates: [] }\n\nexport const SubConversationModelPolicySchema = AgentSubConversationModelsSchema.default(() => ({ candidates: [] }))\n\nconst subConversationModelPolicy = (\n  parsed: z.infer<typeof SubConversationModelPolicySchema>,\n): SubConversationModelPolicy => ({\n  candidates: parsed.candidates.map((candidate) => ({\n    name: candidate.name,\n    model: modelSelection(candidate.model),\n    guidance: candidate.guidance,\n  })),\n  ...(parsed.default === undefined ? {} : { default: parsed.default }),\n})\n\nexport function parseSubConversationModelPolicy(input: unknown): SubConversationModelPolicy {\n  return subConversationModelPolicy(SubConversationModelPolicySchema.parse(input))\n}\n\nexport const FallbackModelsSchema = AgentFallbackModelsSchema.default(() => [])\n\nexport function parseFallbackModels(input: unknown): readonly AgentModelSelection[] {\n  return FallbackModelsSchema.parse(input).map(modelSelection)\n}\n\nexport function parseAgentCompactionPolicy(input: unknown): AgentCompactionPolicy {\n  const parsed = AgentCompactionPolicySchema.parse(input)\n  return {\n    inSession: compactionChoice(parsed.inSession),\n    newSession: compactionChoice(parsed.newSession),\n    ...thresholdChoice(parsed.thresholdRatio),\n  }\n}\n\nexport function parseImageUnderstandingPolicy(input: unknown): ImageUnderstandingPolicy {\n  return ImageUnderstandingPolicySchema.parse(input)\n}\n\nexport const ConnectionAliasSchema = z\n  .string()\n  .trim()\n  .max(80)\n  .transform((value) => value || undefined)\n\nexport function normalizeConnectionAlias(alias: string | undefined): string | undefined {\n  return alias === undefined ? undefined : ConnectionAliasSchema.parse(alias)\n}\n\nconst agentRevisionContentSchema = z\n  .object({\n    displayName: z.string().trim().min(1).max(80),\n    persona: z.string().max(64 * 1024),\n    personaDocument: PromptDocumentV1Schema.optional(),\n    model: AgentModelSelectionSchema,\n    capabilities: AgentCapabilityGrantsSchema,\n    imagePolicy: ImageUnderstandingPolicySchema,\n    dynamicClientApprovalPolicy: DynamicClientApprovalPolicySchema,\n    compaction: AgentCompactionPolicySchema,\n    subConversationModels: SubConversationModelPolicySchema,\n    fallbackModels: FallbackModelsSchema,\n    aliases: AgentAliasesSchema.default(() => []),\n  })\n  .strict()\n  .refine(\n    (content) =>\n      !content.fallbackModels.some(\n        (model) => model.provider === content.model.provider && model.model === content.model.model,\n      ),\n    { message: '备用模型不能和主模型相同。', path: ['fallbackModels'] },\n  )\n\nexport function parseAgentCapabilityGrants(input: unknown): AgentCapabilityGrants {\n  return AgentCapabilityGrantsSchema.parse(input)\n}\n\nexport function parseStoredAgentCapabilityGrants(input: unknown): AgentCapabilityGrants {\n  return AgentCapabilityGrantsSchema.parse(input)\n}\n\nconst connectionInputSchema = z\n  .object({\n    adapterKey: z\n      .string()\n      .trim()\n      .regex(/^[a-z0-9][a-z0-9-]*$/),\n    config: z.json(),\n    credentialRefs: z.record(z.string().min(1), z.string().trim().min(1)).default({}),\n    activityTriggerDefaults: z.array(AdapterActivityKeySchema).default([]),\n    accountKey: z.string().trim().min(1).optional(),\n    alias: ConnectionAliasSchema.optional(),\n  })\n  .strict()\n\nconst channelInputSchema = z\n  .object({\n    connectionId: z.string().trim().min(1),\n    platformChannelId: z.string().trim().min(1),\n    kind: z.enum(['internal', 'direct', 'group']),\n    displayName: z.string().trim().min(1).max(120).optional(),\n  })\n  .strict()\n\nconst observedIdentitySchema = z\n  .object({\n    connectionId: z.string().trim().min(1),\n    channelId: z.string().trim().min(1),\n    platformUserId: z.string().trim().min(1),\n    displayName: z.string().trim().min(1).max(120).optional(),\n    observedAt: z.number().int().safe().nonnegative(),\n    self: z.boolean().optional(),\n  })\n  .strict()\n\nconst connectionIdentitySchema = observedIdentitySchema.omit({ channelId: true })\n\nconst assertRealPlatformUserId = (platformUserId: string): void => {\n  if (platformUserId.trim() === SELF_PLACEHOLDER_PLATFORM_USER_ID)\n    throw new Error(`${SELF_PLACEHOLDER_PLATFORM_USER_ID} is reserved for the account placeholder.`)\n}\n\nconst bindingInputSchema = z\n  .object({\n    channelId: z.string().trim().min(1),\n    agentId: z.string().trim().min(1),\n    triggerPolicy: z.enum(['always', 'mentioned-or-replied', 'smart', 'command', 'observe-only']),\n    processingFeedback: z.enum(['auto', 'off']).default('auto'),\n    localAgentMessages: z.enum(['observe', 'trigger']).default('observe'),\n    activityTriggerOverrides: z.record(AdapterActivityKeySchema, z.boolean()).default({}),\n    responseTiming: ResponseTimingSettingsSchema.default({}),\n  })\n  .strict()\n\nconst canonicalJson = (value: JsonValue): string => {\n  const stack: Array<{ readonly value: JsonValue; readonly close?: string }> = [{ value }]\n  let output = ''\n  while (stack.length > 0) {\n    const current = stack.pop()!\n    if (current.close !== undefined) {\n      output += current.close\n      continue\n    }\n    const item = current.value\n    if (item === null || typeof item === 'boolean' || typeof item === 'number' || typeof item === 'string') {\n      output += JSON.stringify(item)\n      continue\n    }\n    if (Array.isArray(item)) {\n      output += '['\n      stack.push({ value: null, close: ']' })\n      for (let index = item.length - 1; index >= 0; index -= 1) {\n        if (index < item.length - 1) stack.push({ value: null, close: ',' })\n        stack.push({ value: item[index]! })\n      }\n      continue\n    }\n    output += '{'\n    stack.push({ value: null, close: '}' })\n    const entries = Object.entries(item).sort(([left], [right]) => left.localeCompare(right))\n    for (let index = entries.length - 1; index >= 0; index -= 1) {\n      const [key, child] = entries[index]!\n      if (index < entries.length - 1) stack.push({ value: null, close: ',' })\n      stack.push({ value: child })\n      stack.push({ value: null, close: ':' })\n      stack.push({ value: null, close: JSON.stringify(key) })\n    }\n  }\n  return output\n}\n\ntype NormalizedAgentRevisionContent = Omit<\n  AgentRevisionContent,\n  | 'capabilities'\n  | 'imagePolicy'\n  | 'personaDocument'\n  | 'dynamicClientApprovalPolicy'\n  | 'compaction'\n  | 'subConversationModels'\n  | 'fallbackModels'\n  | 'aliases'\n> & {\n  readonly capabilities: AgentCapabilityGrants\n  readonly imagePolicy: ImageUnderstandingPolicy\n  readonly personaDocument: PromptDocumentV1\n  readonly dynamicClientApprovalPolicy: DynamicClientApprovalPolicy\n  readonly compaction: AgentCompactionPolicy\n  readonly subConversationModels: SubConversationModelPolicy\n  readonly fallbackModels: readonly AgentModelSelection[]\n  readonly aliases: readonly string[]\n}\n\nconst parseAgentRevisionContent = (input: AgentRevisionContent): NormalizedAgentRevisionContent => {\n  const parsed = agentRevisionContentSchema.parse(input)\n  const personaDocument = normalizePromptDocument(parsed.personaDocument ?? promptDocumentFromText(parsed.persona))\n  const persona = promptDocumentPlainText(personaDocument)\n  if (parsed.personaDocument !== undefined && persona !== parsed.persona) {\n    throw new Error('Agent persona must match the plain-text projection of personaDocument.')\n  }\n  return {\n    displayName: parsed.displayName,\n    persona,\n    personaDocument,\n    model: {\n      provider: parsed.model.provider,\n      model: parsed.model.model,\n      ...(parsed.model.reasoningEffort === undefined ? {} : { reasoningEffort: parsed.model.reasoningEffort }),\n    },\n    capabilities: parsed.capabilities,\n    imagePolicy: parsed.imagePolicy,\n    dynamicClientApprovalPolicy: parsed.dynamicClientApprovalPolicy,\n    compaction: parseAgentCompactionPolicy(parsed.compaction),\n    subConversationModels: subConversationModelPolicy(parsed.subConversationModels),\n    fallbackModels: parsed.fallbackModels.map(modelSelection),\n    aliases: parsed.aliases,\n  }\n}\n\nfunction modelSelection(model: z.infer<typeof AgentModelSelectionSchema>): AgentModelSelection {\n  return {\n    provider: model.provider,\n    model: model.model,\n    ...(model.reasoningEffort === undefined ? {} : { reasoningEffort: model.reasoningEffort }),\n  }\n}\n\nconst compactionChoice = (choice: z.infer<typeof AgentCompactionModelChoiceSchema>): AgentCompactionModelChoice =>\n  choice.mode === 'follow'\n    ? { mode: 'follow' }\n    : {\n        mode: 'custom',\n        model: {\n          provider: choice.model.provider,\n          model: choice.model.model,\n          ...(choice.model.reasoningEffort === undefined ? {} : { reasoningEffort: choice.model.reasoningEffort }),\n        },\n      }\n\nconst compactionChoicePayload = (choice: AgentCompactionModelChoice): JsonValue =>\n  choice.mode === 'follow'\n    ? { mode: 'follow' }\n    : {\n        mode: 'custom',\n        model: {\n          provider: choice.model.provider,\n          model: choice.model.model,\n          reasoningEffort: choice.model.reasoningEffort ?? null,\n        },\n      }\n\nconst normalizedRevisionPayload = (content: NormalizedAgentRevisionContent): JsonValue => ({\n  displayName: content.displayName,\n  personaDocument: content.personaDocument,\n  model: {\n    provider: content.model.provider,\n    model: content.model.model,\n    reasoningEffort: content.model.reasoningEffort ?? null,\n  },\n  capabilities: {\n    subagents: content.capabilities.subagents,\n    fileTools: content.capabilities.fileTools,\n    webSearch: content.capabilities.webSearch,\n    dynamicCreation: content.capabilities.dynamicCreation,\n    developmentShell: content.capabilities.developmentShell,\n    unrestrictedFileAccess: content.capabilities.unrestrictedFileAccess,\n    // The default leaves the digest of every earlier Revision unchanged; only turning it off is content.\n    ...(content.capabilities.scheduledTasks ? {} : { scheduledTasks: false }),\n    ...(content.capabilities.codeRun ? { codeRun: true } : {}),\n    ...(content.capabilities.commandNetwork ? {} : { commandNetwork: false }),\n    ...(content.capabilities.communityFeedbackAuto ? { communityFeedbackAuto: true } : {}),\n    ...(content.capabilities.voiceTranscription ? { voiceTranscription: true } : {}),\n    ...(content.capabilities.extensionAutonomy === 'manual'\n      ? {}\n      : { extensionAutonomy: content.capabilities.extensionAutonomy }),\n    ...(content.capabilities.extensionRequesters === 'everyone'\n      ? {}\n      : { extensionRequesters: content.capabilities.extensionRequesters }),\n    ...(content.capabilities.extensionConfigRequesters === 'admins'\n      ? {}\n      : { extensionConfigRequesters: content.capabilities.extensionConfigRequesters }),\n    ...(content.capabilities.commandAccounts.length === 0\n      ? {}\n      : {\n          commandAccounts: [...content.capabilities.commandAccounts]\n            .map((grant) => ({\n              service: grant.service,\n              accountId: grant.accountId,\n              ...(grant.usage.length === 0 ? {} : { usage: [...grant.usage].sort() }),\n            }))\n            .sort((left, right) => left.service.localeCompare(right.service)),\n        }),\n  },\n  imagePolicy: {\n    history: {\n      mode: content.imagePolicy.history.mode,\n      detail: content.imagePolicy.history.detail,\n      restoreAfterCompaction: {\n        recentMessages: content.imagePolicy.history.restoreAfterCompaction.recentMessages,\n        maxImages: content.imagePolicy.history.restoreAfterCompaction.maxImages,\n      },\n    },\n    textModel:\n      content.imagePolicy.textModel.mode === 'disabled'\n        ? { mode: 'disabled' }\n        : {\n            mode: 'auxiliary',\n            model: {\n              provider: content.imagePolicy.textModel.model.provider,\n              model: content.imagePolicy.textModel.model.model,\n              reasoningEffort: content.imagePolicy.textModel.model.reasoningEffort ?? null,\n            },\n            maxTokens: content.imagePolicy.textModel.maxTokens,\n          },\n  },\n  dynamicClientApprovalPolicy: content.dynamicClientApprovalPolicy,\n  // Following every default leaves the digest of every earlier Revision unchanged.\n  ...(isDefaultCompactionPolicy(content.compaction)\n    ? {}\n    : {\n        compaction: {\n          inSession: compactionChoicePayload(content.compaction.inSession),\n          newSession: compactionChoicePayload(content.compaction.newSession),\n          ...(content.compaction.thresholdRatio === undefined\n            ? {}\n            : { thresholdRatio: content.compaction.thresholdRatio }),\n        },\n      }),\n  // Offering no candidates leaves the digest of every earlier Revision unchanged.\n  ...(content.subConversationModels.candidates.length === 0\n    ? {}\n    : {\n        subConversationModels: {\n          candidates: content.subConversationModels.candidates.map((candidate) => ({\n            name: candidate.name,\n            model: {\n              provider: candidate.model.provider,\n              model: candidate.model.model,\n              reasoningEffort: candidate.model.reasoningEffort ?? null,\n            },\n            guidance: candidate.guidance,\n          })),\n          default: content.subConversationModels.default ?? null,\n        },\n      }),\n  // No fallback models leaves the digest of every earlier Revision unchanged.\n  ...(content.fallbackModels.length === 0\n    ? {}\n    : {\n        fallbackModels: content.fallbackModels.map((model) => ({\n          provider: model.provider,\n          model: model.model,\n          reasoningEffort: model.reasoningEffort ?? null,\n        })),\n      }),\n  // Likewise for aliases.\n  ...(content.aliases.length === 0 ? {} : { aliases: [...content.aliases] }),\n})\n\nconst digestRevision = (input: AgentRevisionContent): string => {\n  const content = parseAgentRevisionContent(input)\n  return `v5:sha256:${createHash('sha256')\n    .update('nekro-nxt.agent-revision.v5\\0')\n    .update(canonicalJson(normalizedRevisionPayload(content)))\n    .digest('hex')}`\n}\n\nconst revisionContent = (revision: AgentRevisionRecord): NormalizedAgentRevisionContent => ({\n  displayName: revision.displayName,\n  persona: revision.persona,\n  personaDocument: revision.personaDocument,\n  model: revision.model,\n  capabilities: revision.capabilities,\n  imagePolicy: revision.imagePolicy,\n  dynamicClientApprovalPolicy: revision.dynamicClientApprovalPolicy,\n  compaction: revision.compaction,\n  subConversationModels: revision.subConversationModels,\n  fallbackModels: revision.fallbackModels,\n  aliases: revision.aliases,\n})\n\n/** Revision fields an administrator can tell apart in history; `approvalPolicy` is the dynamic client approval policy. */\nexport type AgentRevisionChangedField =\n  | 'name'\n  | 'persona'\n  | 'model'\n  | 'capabilities'\n  | 'imagePolicy'\n  | 'approvalPolicy'\n  | 'compaction'\n  | 'subConversationModels'\n  | 'fallbackModels'\n  | 'aliases'\n\nconst AGENT_REVISION_FIELDS: readonly (readonly [AgentRevisionChangedField, string])[] = [\n  ['name', 'displayName'],\n  ['persona', 'personaDocument'],\n  ['model', 'model'],\n  ['capabilities', 'capabilities'],\n  ['imagePolicy', 'imagePolicy'],\n  ['approvalPolicy', 'dynamicClientApprovalPolicy'],\n  ['compaction', 'compaction'],\n  ['subConversationModels', 'subConversationModels'],\n  ['fallbackModels', 'fallbackModels'],\n  ['aliases', 'aliases'],\n]\n\nconst payloadField = (payload: JsonValue, key: string): JsonValue =>\n  payload !== null && typeof payload === 'object' && !Array.isArray(payload) ? (payload[key] ?? null) : null\n\n/** Fields that differ between two Revisions, compared on the same normalized payload as the digest. */\nexport const diffAgentRevisions = (\n  previous: AgentRevisionRecord,\n  current: AgentRevisionRecord,\n): readonly AgentRevisionChangedField[] => {\n  const before = normalizedRevisionPayload(revisionContent(previous))\n  const after = normalizedRevisionPayload(revisionContent(current))\n  return AGENT_REVISION_FIELDS.filter(\n    ([, key]) => canonicalJson(payloadField(before, key)) !== canonicalJson(payloadField(after, key)),\n  ).map(([field]) => field)\n}\n\nconst equivalentRevisionContent = (\n  left: NormalizedAgentRevisionContent,\n  right: NormalizedAgentRevisionContent,\n): boolean => canonicalJson(normalizedRevisionPayload(left)) === canonicalJson(normalizedRevisionPayload(right))\n\n/** Product-domain commit service. Every returned record has already crossed the Repository commit point. */\nexport class CoreService {\n  readonly #repository: CoreRepository\n  readonly #now: () => number\n  readonly #nextUlid: () => string\n\n  constructor(repository: CoreRepository, options: CoreServiceOptions = {}) {\n    this.#repository = repository\n    this.#now = options.now ?? Date.now\n    this.#nextUlid = options.nextUlid ?? monotonicFactory()\n  }\n\n  listAgents(): readonly CreateAgentCommit[] {\n    return this.#repository.listAgents()\n  }\n\n  createAgent(input: AgentRevisionContent): CreateAgentCommit {\n    const content = parseAgentRevisionContent(input)\n    const createdAt = this.#timestamp()\n    const agentId = AgentIdSchema.parse(`agt_${this.#nextUlid()}`)\n    const revisionId = AgentRevisionIdSchema.parse(`arev_${this.#nextUlid()}`)\n    const revision: AgentRevisionRecord = {\n      ...content,\n      id: revisionId,\n      agentId,\n      revision: 1,\n      contentDigest: digestRevision(content),\n      createdAt,\n    }\n    const definition: AgentDefinitionRecord = { id: agentId, currentRevisionId: revisionId, createdAt }\n    const commit = { definition, revision }\n    this.#repository.createAgent(commit)\n    return commit\n  }\n\n  createAgentWithChannel(\n    input: AgentRevisionContent,\n    channelInput: {\n      readonly connectionId: ConnectionId\n      readonly kind: ChannelRecord['kind']\n      readonly platformChannelId?: string\n      readonly displayName?: string\n      readonly triggerPolicy: BindingTriggerPolicy\n    },\n  ): CreateAgentWithChannelCommit {\n    if (!this.#repository.getConnection(channelInput.connectionId)) {\n      throw new Error(`Unknown connection: ${channelInput.connectionId}`)\n    }\n    const content = parseAgentRevisionContent(input)\n    const createdAt = this.#timestamp()\n    const agentId = AgentIdSchema.parse(`agt_${this.#nextUlid()}`)\n    const revisionId = AgentRevisionIdSchema.parse(`arev_${this.#nextUlid()}`)\n    const channelId = ChannelIdSchema.parse(`chn_${this.#nextUlid()}`)\n    const revision: AgentRevisionRecord = {\n      ...content,\n      id: revisionId,\n      agentId,\n      revision: 1,\n      contentDigest: digestRevision(content),\n      createdAt,\n    }\n    const definition: AgentDefinitionRecord = { id: agentId, currentRevisionId: revisionId, createdAt }\n    const channel: ChannelRecord = {\n      id: channelId,\n      connectionId: channelInput.connectionId,\n      platformChannelId: channelInput.platformChannelId ?? `internal-${agentId}`,\n      kind: channelInput.kind,\n      ...(channelInput.displayName === undefined ? {} : { displayName: channelInput.displayName }),\n      autoCreatedForAgentId: agentId,\n      createdAt,\n    }\n    const binding: BindingRecord = {\n      channelId,\n      agentId,\n      triggerPolicy: channelInput.triggerPolicy,\n      paused: false,\n      processingFeedback: 'auto',\n      localAgentMessages: 'observe',\n      activityTriggerOverrides: {},\n      responseTiming: {},\n      boundAt: createdAt,\n    }\n    const commit = { definition, revision, channel, binding }\n    this.#repository.createAgentWithChannel(commit)\n    return commit\n  }\n\n  reviseAgent(agentId: AgentId, expectedCurrentRevisionId: AgentRevisionId, input: AgentRevisionContent) {\n    const current = this.#repository.getAgent(agentId)\n    if (!current) throw new Error(`Unknown agent: ${agentId}`)\n    if (current.definition.currentRevisionId !== expectedCurrentRevisionId) {\n      throw new Error(`Agent revision conflict: expected ${expectedCurrentRevisionId}.`)\n    }\n    // Callers that rebuild a revision without these choices (a capability change, a persona import) keep them.\n    const content = parseAgentRevisionContent({\n      ...input,\n      compaction: input.compaction ?? current.revision.compaction,\n      subConversationModels: input.subConversationModels ?? current.revision.subConversationModels,\n      fallbackModels: input.fallbackModels ?? current.revision.fallbackModels,\n      aliases: input.aliases ?? current.revision.aliases,\n    })\n    if (equivalentRevisionContent(content, revisionContent(current.revision))) return current\n    const digest = digestRevision(content)\n    const existi