      "path": "packages/channel-runtime/src/index.ts",
      "content": "import type {\n  AdapterCapabilityState,\n  AdapterChannelInboundEvent,\n  AdapterConnectionRuntime,\n  AdapterDeliveryReceipt,\n  AdapterRuntimeStateStore,\n  InboundCommitResult,\n} from '@nekro-nxt/adapter-sdk'\nimport type {\n  AdmissionId,\n  AgentId,\n  AgentRevisionId,\n  ChannelEventId,\n  ChannelId,\n  ChannelMemberId,\n  ConnectionId,\n  EpisodeHandoffId,\n  EpisodeId,\n  JsonValue,\n  LogicalMessageId,\n  MessagePart,\n  OutboundIntentId,\n  PhysicalDeliveryId,\n} from '@nekro-nxt/contracts'\nimport {\n  AdmissionIdSchema,\n  ChannelMemberIdSchema,\n  EpisodeHandoffIdSchema,\n  EpisodeIdSchema,\n  RESPONSE_WAIT_MIN_QUIET_SECONDS,\n  resolveResponseTiming,\n  type ResolvedResponseTiming,\n} from '@nekro-nxt/contracts'\nimport type {\n  AgentRevisionRecord,\n  AppendChannelEventCommit,\n  BindingRecord,\n  ChannelEventRecord,\n  CoreRepository,\n  CoreService,\n} from '@nekro-nxt/core'\nimport { canonicalJson } from '@nekro-nxt/core'\nimport { monotonicFactory } from 'ulid'\nimport { ChannelDelivery } from './channel-delivery.js'\nexport { supportsPart as adapterSupportsPart, UNSUPPORTED_PART } from './channel-delivery.js'\nimport { ChannelInteractions } from './channel-interactions.js'\nimport { ProcessingFeedback } from './processing-feedback.js'\nimport { ResponseTiming, systemTimers, type ResponseTimerPort, type WaitEndCause } from './response-timing.js'\n\nexport type EpisodeStatus = 'opening' | 'active' | 'closed' | 'failed'\n\nexport interface EpisodeRecord {\n  readonly id: EpisodeId\n  readonly channelId: ChannelId\n  readonly agentId: AgentId\n  readonly agentRevisionId: AgentRevisionId\n  readonly dshSessionId?: string\n  readonly status: EpisodeStatus\n  readonly openedAtEventId: ChannelEventId\n  readonly lastAdmittedEventId?: ChannelEventId\n  readonly closedAtEventId?: ChannelEventId\n  readonly closedAt?: number\n  readonly closeReason?: EpisodeCloseReason\n  readonly createdAt: number\n}\n\nexport type EpisodeCloseReason =\n  | 'manual'\n  | 'context-cleared'\n  | 'context-compacted'\n  | 'idle-timeout'\n  | 'incompatible-revision'\n  | 'incompatible-activation'\n  | 'incompatible-session-storage'\n  | 'unrecoverable-session'\n  | 'permission-revoked'\n  | 'binding-replaced'\n  | 'channel-deleted'\n  | 'stopped'\n\nexport interface EpisodeHandoffRecord {\n  readonly id: EpisodeHandoffId\n  readonly fromEpisodeId: EpisodeId\n  readonly toEpisodeId: EpisodeId\n  readonly sourceEventIds: readonly ChannelEventId[]\n  /** A deterministic verbatim tail carried across Episode boundaries. */\n  readonly recentEventIds: readonly ChannelEventId[]\n  readonly summary: string\n  readonly provider: string\n  readonly model: string\n  readonly createdAt: number\n}\n\nexport type AdmissionState = 'pending' | 'claimed' | 'logged-to-session' | 'cancelled'\n\nexport interface AdmissionRecord {\n  readonly id: AdmissionId\n  readonly episodeId: EpisodeId\n  readonly eventIds: readonly ChannelEventId[]\n  readonly mode: 'followup' | 'inject'\n  readonly state: AdmissionState\n  readonly dshMessageId?: string\n  readonly createdAt: number\n}\n\nexport type OutboundState = 'planned' | 'sending' | 'sent' | 'partially-sent' | 'failed' | 'unknown'\n\nexport const ADMIN_CONSOLE_SOURCE_TURN = 'admin-console'\n\nexport const isAdminConsoleOutbound = (sourceTurnId: string | undefined): boolean =>\n  sourceTurnId === ADMIN_CONSOLE_SOURCE_TURN\n\nexport interface ChannelFact {\n  readonly channelId: ChannelId\n  readonly kind: 'inbound' | 'outbound'\n  readonly sourceId: ChannelEventId | OutboundIntentId\n}\n\nexport interface OutboundIntentRecord {\n  readonly id: OutboundIntentId\n  readonly logicalMessageId: LogicalMessageId\n  readonly agentRevisionId?: AgentRevisionId\n  readonly episodeId?: EpisodeId\n  /** Commands have their own durable source and never require an Episode. */\n  readonly channelId?: ChannelId\n  readonly commandExecutionId?: string\n  readonly commandOrdinal?: number\n  /** Host notice (an extension request or its outcome); neither an agent's message nor a command reply. */\n  readonly noticeKey?: string\n  readonly sourceTurnId?: string\n  readonly parts: readonly MessagePart[]\n  readonly replyTo?: string\n  readonly clientRequestId?: string\n  readonly state: OutboundState\n  readonly createdAt: number\n}\n\nexport interface PhysicalDeliveryRecord {\n  readonly id: PhysicalDeliveryId\n  readonly intentId: OutboundIntentId\n  readonly sequence: number\n  readonly parts: readonly MessagePart[]\n  readonly adapterContext?: JsonValue\n  readonly processingFeedbackLeaseId?: string\n  readonly state: 'planned' | 'sending' | 'sent' | 'failed' | 'unknown'\n  readonly receipt?: AdapterDeliveryReceipt\n  readonly completedAt?: number\n}\n\nexport interface DeliveryReceiptRecord {\n  readonly physicalDeliveryId: PhysicalDeliveryId\n  readonly receipt: AdapterDeliveryReceipt\n  readonly completedAt: number\n}\n\nexport interface OutboundSnapshot {\n  readonly intent: OutboundIntentRecord\n  readonly deliveries: readonly PhysicalDeliveryRecord[]\n  readonly receipts: readonly DeliveryReceiptRecord[]\n}\n\nexport interface ChannelHistoryCursor {\n  readonly occurredAt: number\n  readonly sourceId: string\n}\n\nexport type ChannelHistoryEntry =\n  | {\n      readonly source: 'channel-event'\n      readonly sourceId: ChannelEventId\n      readonly logicalMessageId: LogicalMessageId\n      readonly channelId: ChannelId\n      readonly occurredAt: number\n      readonly senderMemberId?: ChannelEventRecord['senderMemberId']\n      readonly activityKey?: ChannelEventRecord['activityKey']\n      readonly targetLogicalMessageId?: ChannelEventRecord['targetLogicalMessageId']\n      readonly parts: readonly MessagePart[]\n      readonly facts?: ChannelEventRecord['facts']\n    }\n  | {\n      readonly source: 'outbound-intent'\n      readonly sourceId: OutboundIntentId\n      readonly logicalMessageId: LogicalMessageId\n      readonly channelId: ChannelId\n      readonly occurredAt: number\n      readonly parts: readonly MessagePart[]\n      readonly state: OutboundState\n      readonly sourceTurnId?: string\n      readonly commandExecutionId?: string\n      readonly noticeKey?: string\n    }\n\nexport const isConsoleAnchorHistory = (entry: ChannelHistoryEntry): boolean =>\n  entry.source === 'channel-event' && entry.facts?.['consoleAnchor'] === true\n\n/** Narrows a history read or search; every bound is optional and they combine with AND. */\nexport interface ChannelHistoryFilter {\n  /** Inclusive lower bound on `occurredAt`. */\n  readonly since?: number\n  /** Exclusive upper bound on `occurredAt`. */\n  readonly until?: number\n  /** Inbound messages from members whose id equals this or whose display name contains it; outbound ones are left out. */\n  readonly sender?: string\n  /** Only what the channel's own account sent. */\n  readonly ownOnly?: boolean\n}\n\nexport interface ChannelHistorySearchHit {\n  readonly entry: ChannelHistoryEntry\n  readonly rank: number\n}\n\n/** Read-only, Channel-scoped history seam; callers never receive database handles or cross-channel rows. */\nexport interface ChannelHistoryRepository {\n  /** Resolve one logical message only inside the supplied Channel. */\n  getChannelHistoryEntryByLogicalMessageId(\n    channelId: ChannelId,\n    logicalMessageId: LogicalMessageId,\n  ): ChannelHistoryEntry | undefined\n  listChannelHistory(\n    channelId: ChannelId,\n    options?: { readonly before?: ChannelHistoryCursor; readonly limit?: number } & ChannelHistoryFilter,\n  ): readonly ChannelHistoryEntry[]\n  /** Project only facts that were admitted or sent by one Episode; results are newest-first. */\n  listEpisodeHistory(\n    episodeId: EpisodeId,\n    options?: { readonly before?: ChannelHistoryCursor; readonly limit?: number },\n  ): readonly ChannelHistoryEntry[]\n  /** Whitespace-separated terms must all appear; results are newest-first. */\n  searchChannelHistory(\n    channelId: ChannelId,\n    query: string,\n    options?: { readonly before?: ChannelHistoryCursor; readonly limit?: number } & ChannelHistoryFilter,\n  ): readonly ChannelHistorySearchHit[]\n}\n\nexport interface RuntimeRepository {\n  getEpisode(id: EpisodeId): EpisodeRecord | undefined\n  getActiveEpisode(channelId: ChannelId, agentId: AgentId): EpisodeRecord | undefined\n  listRecoverableEpisodes(): readonly EpisodeRecord[]\n  listActiveEpisodesForAgent(agentId: AgentId): readonly EpisodeRecord[]\n  getEpisodeHandoffTo(episodeId: EpisodeId): EpisodeHandoffRecord | undefined\n  createEpisode(record: EpisodeRecord): void\n  activateEpisode(id: EpisodeId, dshSessionId: string): EpisodeRecord\n  updateEpisodeRevision(\n    id: EpisodeId,\n    expectedRevisionId: AgentRevisionId,\n    targetRevisionId: AgentRevisionId,\n  ): EpisodeRecord\n  closeEpisode(\n    id: EpisodeId,\n    reason: EpisodeCloseReason,\n    closedAtEventId: ChannelEventId,\n    closedAt: number,\n  ): EpisodeRecord\n  commitEpisodeRollover(input: {\n    readonly fromEpisodeId: EpisodeId\n    readonly reason: EpisodeCloseReason\n    readonly closedAtEventId: ChannelEventId\n    readonly closedAt: number\n    readonly nextEpisode: EpisodeRecord\n    readonly handoff: EpisodeHandoffRecord\n  }): void\n  failEpisode(id: EpisodeId): void\n  createAdmission(record: AdmissionRecord): void\n  listRecoverableAdmissions(episodeId: EpisodeId): readonly AdmissionRecord[]\n  /** Admitted inbound facts for one Episode, oldest-first within the recent limit. */\n  listAdmittedEvents(episodeId: EpisodeId, limit: number): readonly ChannelEventRecord[]\n  listUnadmittedEvents(channelId: ChannelId, agentId: AgentId, boundAt: number): readonly ChannelEventRecord[]\n  /** Whether the event was already handed to this agent in some Admission of the channel, in any state. */\n  isEventAdmitted(channelId: ChannelId, agentId: AgentId, eventId: ChannelEventId): boolean\n  claimAdmission(id: AdmissionId): void\n  completeAdmission(id: AdmissionId, dshMessageId: string, eventId: ChannelEventId): void\n  findOutboundByClientRequest(\n    agentId: AgentId,\n    channelId: ChannelId,\n    clientRequestId: string,\n  ): OutboundSnapshot | undefined\n  findOutboundByLogicalMessageId(channelId: ChannelId, logicalMessageId: LogicalMessageId): OutboundSnapshot | undefined\n  /** The notice already planned under this key, if any. */\n  findOutboundByNoticeKey?(noticeKey: string): OutboundSnapshot | undefined\n  createOutboundPlan(intent: OutboundIntentRecord, deliveries: readonly PhysicalDeliveryRecord[]): void\n  markIntentSending(id: OutboundIntentId): void\n  markDeliverySending(id: PhysicalDeliveryId): void\n  recordDeliveryReceipt(id: PhysicalDeliveryId, receipt: AdapterDeliveryReceipt, completedAt: number): void\n  completeOutboundIntent(id: OutboundIntentId, state: OutboundState): void\n  getOutbound(id: OutboundIntentId): OutboundSnapshot\n  listUnsettledOutboundIds(): readonly OutboundIntentId[]\n}\n\nexport interface AgentSessionDriver {\n  createSession(input: {\n    readonly episodeId: EpisodeId\n    readonly channelId: ChannelId\n    readonly agentId: AgentId\n    readonly agentRevisionId: AgentRevisionId\n    readonly handoff?: {\n      readonly id: EpisodeHandoffId\n      readonly fromEpisodeId: EpisodeId\n      readonly sourceEventIds: readonly ChannelEventId[]\n      readonly createdAt: number\n      readonly provider: string\n      readonly model: string\n      readonly summary: string\n      readonly recentEvents: readonly ChannelEventRecord[]\n    }\n  }): Promise<string>\n  applyCompatibleRevision(input: {\n    readonly dshSessionId: string\n    readonly episodeId: EpisodeId\n    readonly previousRevision: AgentRevisionRecord\n    readonly targetRevision: AgentRevisionRecord\n  }): Promise<void>\n  sessionStatus(dshSessionId: string): 'idle' | 'running'\n  /** Whether context occupancy warrants idle rollover. Without a measurement, keep the current session. */\n  shouldCompactIdleSession?(dshSessionId: string): boolean\n  /** Resolves after the current DSH turn and all injected work become idle. */\n  whenIdle?(dshSessionId: string): Promise<void>\n  findAdmissionMessage(dshSessionId: string, admissionId: AdmissionId): string | undefined\n  createHandoffSummary(input: {\n    readonly dshSessionId: string\n    readonly episode: EpisodeRecord\n    readonly revision: AgentRevisionRecord\n    readonly sourceEvents: readonly ChannelEventRecord[]\n    readonly previousHandoff?: EpisodeHandoffRecord\n    readonly generatedAt: number\n  }): Promise<{ readonly summary: string; readonly provider: string; readonly model: string }>\n  cancelSession(dshSessionId: string, reason: EpisodeCloseReason): Promise<void>\n  /** Aborts the live turn but keeps the Session and its admitted-but-unconsumed input. */\n  interruptTurn(\n    dshSessionId: string,\n    reason: string,\n  ): Promise<{ readonly interrupted: boolean; readonly retainedPending: number }>\n  /** Channel admissions accepted by the Session inbox that the model has not consumed yet. */\n  listPendingAdmissions(dshSessionId: string): readonly {\n    readonly admissionId: AdmissionId\n    readonly target: 'next-step' | 'next-turn'\n    readonly channelEventIds: readonly ChannelEventId[]\n  }[]\n  admit(input: {\n    readonly dshSessionId: string\n    readonly admissionId: AdmissionId\n    readonly events: readonly ChannelEventRecord[]\n    readonly mode: 'followup' | 'inject'\n    readonly replyRequired: boolean\n    /** Labelled notes keyed by Channel Event, rendered next to that event: NekroNXT's own first, then extensions'. */\n    readonly annotations?: ReadonlyMap<ChannelEventId, readonly InboundAnnotation[]>\n    /** Why a smart-mode wake happened when it does not oblige a reply; rendered after the events. */\n    readonly wakeNote?: string\n  }): Promise<{ readonly dshMessageId: string }>\n  notifyConsoleOutbound(input: {\n    readonly dshSessionId: string\n    readonly channelId: ChannelId\n    readonly logicalMessageId: LogicalMessageId\n    readonly parts: readonly MessagePart[]\n  }): Promise<void>\n}\n\n/** A note shown to the agent next to a message, under its own label such as `语音转写`. */\nexport interface InboundAnnotation {\n  readonly label: string\n  readonly text: string\n}\n\n/** Label of the annotations extensions add. */\nexport const EXTENSION_ANNOTATION_LABEL = '扩展标注'\n\n/**\n * What inbound hooks decided for one Channel Event and one agent; persisted once and never rewritten. `annotation` is\n * what extensions added; `hostAnnotations` are NekroNXT's own notes, such as a voice message transcript.\n */\nexport interface InboundHookDecision {\n  readonly trigger: 'default' | 'suppress' | 'force'\n  readonly hidden: boolean\n  readonly annotation?: string\n  readonly hostAnnotations?: readonly InboundAnnotation[]\n}\n\n/**\n * Extension inbound hooks of the Host. Facts are committed before any hook runs; a decision only changes whether the\n * agent is woken, whether it sees the message and what annotation travels with it.\n */\nexport interface InboundHookGate {\n  /** Whether any enabled extension of this agent observes inbound messages. */\n  covers(agentId: AgentId): boolean\n  /** Runs the hooks with their own timeout, persists the merged decision and returns it; repeat calls return it. */\n  decide(input: {\n    readonly binding: BindingRecord\n    readonly event: ChannelEventRecord\n    readonly defaultTriggered: boolean\n  }): Promise<InboundHookDecision>\n  stored(eventId: ChannelEventId, agentId: AgentId): InboundHookDecision | undefined\n}\n\n/** A scheduled job of an extension or a chat-created task that has come due in one bound channel. */\nexport interface ExtensionJobFiring {\n  readonly channelId: ChannelId\n  readonly agentId: AgentId\n  readonly jobId: string\n  readonly label: string\n  /** Extension display name, or absent for a chat-created task. */\n  readonly extensionName?: string\n  readonly payload: JsonValue\n  /** From the extension's due-job handler: what it found, shown to the agent. */\n  readonly note?: string\n  readonly scheduledAt: number\n  readonly firedAt: number\n}\n\n/** A chat-created task keeps its note as `{ note }`; extension payloads stay JSON for the agent to read. */\nconst chatNote = (job: ExtensionJobFiring): string | undefined =>\n  job.extensionName === undefined &&\n  job.payload !== null &&\n  typeof job.payload === 'object' &&\n  !Array.isArray(job.payload) &&\n  typeof job.payload['note'] === 'string'\n    ? job.payload['note']\n    : undefined\n\nconst jobDetail = (job: ExtensionJobFiring): string => {\n  const chat = chatNote(job)\n  if (chat !== undefined) return `\\n补充：${chat}`\n  const handlerNote = job.note === undefined ? '' : `\\n${job.note}`\n  const empty =\n    job.payload === null ||\n    (typeof job.payload === 'object' && !Array.isArray(job.payload) && Object.keys(job.payload).length === 0)\n  return `${handlerNote}${empty ? '' : `\\n${JSON.stringify(job.payload)}`}`\n}\n\nexport const isExtensionJobEvent = (event: Pick<ChannelEventRecord, 'facts'>): boolean =>\n  event.facts?.['extensionJob'] !== undefined\n\n/** Command gate commits facts and execution records together, before hooks or model admission. */\nexport interface CommandGate {\n  commitInbound(event: AdapterChannelInboundEvent): AppendChannelEventCommit\n  /** Synchronous classification also excludes not-yet-processed commands from backlog/recovery. */\n  excludes(event: ChannelEventRecord): boolean\n  project(event: ChannelEventRecord): ChannelEventRecord\n}\n\nexport interface ChannelRuntimeOptions {\n  /** Persist inbound facts while Host restores required services and optional extensions. */\n  readonly deferAdmission?: boolean\n  /** A compatibility quarantine must not create a failed Episode or processing feedback. */\n  readonly canAdmitAgent?: (agentId: AgentId) => boolean\n  readonly now?: () => number\n  readonly nextUlid?: () => string\n  readonly resolveAdapter: (connectionId: ConnectionId) => AdapterConnectionRuntime | undefined\n  readonly isActivityTriggerAllowed?: (channelId: ChannelId, activityKey: string) => boolean\n  readonly isActivityTriggerEnabledByDefault?: (channelId: ChannelId, activityKey: string) => boolean\n  /** Activities that act on someone trigger only when that someone is the channel's own account. */\n  readonly activityDirectedAt?: (channelId: ChannelId, activityKey: string) => 'member' | 'message' | undefined\n  readonly validateActivityTriggerOverrides?: (\n    channelId: ChannelId,\n    overrides: Readonly<Record<string, boolean>>,\n  ) => void\n  readonly idleRolloverMs?: number | false\n  /**\n   * Episodes the Host wants handed off on their next message, such as every live one after the data directory moved.\n   * `settle` runs once the handoff is committed.\n   */\n  readonly pendingRollover?: {\n    readonly reasonFor: (episode: EpisodeRecord) => EpisodeCloseReason | undefined\n    readonly settle: (episodeId: EpisodeId) => void\n  }\n  /** Pause before a message that follows another one in the same channel, counted from when the earlier one was sent. */\n  readonly messageGapMs?: (channelId: ChannelId, parts: readonly MessagePart[]) => number\n  readonly sleep?: (ms: number, signal: AbortSignal) => Promise<void>\n  /** Timers for waits and debounce; tests pass a manual clock. */\n  readonly timers?: ResponseTimerPort\n  readonly adapterState?: AdapterRuntimeStateStore\n  readonly commands?: CommandGate\n  readonly inboundHooks?: InboundHookGate\n  /** Rewrites an inbound event before it is stored, such as hiding known secrets the sender pasted. */\n  readonly sanitizeInbound?: (event: AdapterChannelInboundEvent) => AdapterChannelInboundEvent\n  /**\n   * Called each time an outbound message's delivery settles, including messages recovered after a restart and\n   * redispatched ones; the callee keeps its own once-only marker. Must not throw or block.\n   */\n  readonly onOutboundSettled?: (snapshot: OutboundSnapshot) => void\n}\n\nexport type ContextResetMode = 'clear' | 'compact'\n\nexport interface ContextResetResult {\n  readonly mode: ContextResetMode\n  readonly closedEpisode: EpisodeRecord\n  readonly nextEpisode?: EpisodeRecord\n}\n\nconst HANDOFF_RECENT_EVENT_LIMIT = 12\n\ntype ChannelInteractionStatus = 'succeeded' | 'partially-succeeded' | 'failed' | 'unknown'\n\nexport interface ChannelInteractionResult {\n  readonly intentId: string\n  readonly status: ChannelInteractionStatus\n  readonly message: string\n  readonly outcomes?: readonly {\n    readonly platformMessageId: string\n    readonly status: string\n    readonly message?: string\n  }[]\n  readonly value?: JsonValue\n}\n\nconst deterministicHandoffFallback = (\n  episode: EpisodeRecord,\n  revision: AgentRevisionRecord,\n  sourceEvents: readonly ChannelEventRecord[],\n): Awaited<ReturnType<AgentSessionDriver['createHandoffSummary']>> => ({\n  summary: [\n    '模型压缩摘要不可用；不要假设旧上下文已经完整恢复。',\n    `旧 Episode：${episode.id}`,\n    `边界锚点：${sourceEvents.map(({ id }) => id).join(' → ') || '无'}`,\n    '需要具体细节时，请使用 conversation_history_search 或 conversation_history_read 回查当前频道原文。',\n  ].join('\\n'),\n  provider: revision.model.provider,\n  model: revision.model.model,\n})\n\nexport interface SendMessageInput {\n  readonly episodeId: EpisodeId\n  readonly parts: readonly MessagePart[]\n  readonly replyTo?: string\n  readonly sourceTurnId?: string\n  readonly clientRequestId?: string\n  readonly signal?: AbortSignal\n  /** Called synchronously once the message is planned, before delivery starts; not called for a repeated request. */\n  readonly onIntentPlanned?: (intent: {\n    readonly id: OutboundIntentId\n    readonly logicalMessageId: LogicalMessageId\n  }) => void\n}\n\nexport interface SendMessageResult {\n  readonly logicalMessageId: LogicalMessageId\n  readonly status: 'sent' | 'partially-sent' | 'failed' | 'unknown'\n  readonly receipts: readonly DeliveryReceiptRecord[]\n}\n\nexport interface RuntimeRecoveryReport {\n  readonly resumedEpisodes: number\n  readonly recoveredAdmissions: number\n  readonly recoveredOutbounds: number\n  readonly unknownDeliveries: number\n}\n\n/** At most this many activities wake the agent in one channel within the window, whatever they are. */\nconst ACTIVITY_WAKE_LIMIT = 3\nconst ACTIVITY_WAKE_WINDOW_MS = 60_000\n\nconst isTriggered = (\n  binding: BindingRecord,\n  event: ChannelEventRecord,\n  isActivityTriggerAllowed: (channelId: ChannelId, activityKey: string) => boolean = () => true,\n  isActivityTriggerEnabledByDefault: (channelId: ChannelId, activityKey: string) => boolean = () => false,\n): boolean => {\n  if (event.facts?.['consoleAnchor'] === true || event.facts?.['selfInteraction'] === true) return false\n  if (event.activityKey !== undefined) {\n    return (\n      binding.triggerPolicy !== 'observe-only' &&\n      isActivityTriggerAllowed(event.channelId, event.activityKey) &&\n      (binding.activityTriggerOverrides[event.activityKey] ??\n        isActivityTriggerEnabledByDefault(event.channelId, event.activityKey))\n    )\n  }\n  switch (binding.triggerPolicy) {\n    case 'always':\n      return true\n    case 'observe-only':\n      return false\n    case 'mentioned-or-replied':\n    case 'smart':\n      return event.facts?.['mentionedBot'] === true || event.facts?.['replyToBot'] === true\n    case 'command':\n      return typeof event.facts?.['command'] === 'string' && event.facts['command'].length > 0\n  }\n}\n\n/** Only display-name changes are model/runtime neutral in M1; every other change requires M2 rollover. */\nexport const isSessionCompatibleRevision = (previous: AgentRevisionRecord, target: AgentRevisionRecord): boolean =>\n  previous.agentId === target.agentId &&\n  previous.persona === target.persona &&\n  previous.model.provider === target.model.provider &&\n  previous.model.model === target.model.model &&\n  previous.model.reasoningEffort === target.model.reasoningEffort &&\n  canonicalJson({ ...previous.capabilities }) === canonicalJson({ ...target.capabilities })\n\nconst laneKey = (channelId: ChannelId, agentId: AgentId): string => `${channelId}\\u0000${agentId}`\n\n/** Channels that only answer commands or only observe never wake the agent on their own, so it cannot wait there. */\nconst waitSupported = (binding: BindingRecord): boolean =>\n  binding.triggerPolicy !== 'command' && binding.triggerPolicy !== 'observe-only'\n\ntype MidSignal = { readonly kind: 'attention' } | { readonly kind: 'name'; readonly name: string }\n\nconst midWakeNote = (signal: MidSignal): string =>\n  signal.kind === 'name'\n    ? `有人提到了「${signal.name}」，所以叫醒了你。这不一定是在跟你说话；不想接话就用 finish_channel_turn 结束，不回也可以。`\n    : '刚才跟你聊天的人接着说了话，所以叫醒了你。这不一定是对你说的；不想接话就用 finish_channel_turn 结束，不回也可以。'\n\ninterface AdmissionWake {\n  /** A finished wait obliges a reply even though its fact is no trigger. */\n  readonly replyRequired?: boolean\n  readonly fromWait?: boolean\n  readonly note?: string\n  /** The message that carries the processing reaction when the waking event is not one, such as a finished wait. */\n  readonly feedbackEvent?: ChannelEventRecord\n}\n\nexport type WaitForMoreResult =\n  | {\n      readonly accepted: true\n      readonly memberId: ChannelMemberId\n      readonly displayName?: string\n      readonly seconds: number\n    }\n  | { readonly accepted: false; readonly reason: string }\n\n/** A finished wait (Decision 2026-10-31 R2): a Host fact that opens the turn in which the agent must answer. */\nexport const isResponseWaitEvent = (event: Pick<ChannelEventRecord, 'facts'>): boolean => {\n  const wait = event.facts?.['responseWait']\n  return wait !== null && typeof wait === 'object' && !Array.isArray(wait)\n}\n\nexport class ChannelStopConflictError extends Error {\n  constructor(message: string) {\n    super(message)\n    this.name = 'ChannelStopConflictError'\n  }\n}\n\n/**\n * The Session Driver throws this when a stored conversation can no longer be read. Recovery then closes only that\n * Episode; the channel starts a fresh one on its next message instead of the whole service staying down.\n */\nexport class UnrecoverableSessionError extends Error {\n  constructor(message: string, options?: ErrorOptions) {\n    super(message, options)\n    this.name = 'UnrecoverableSessionError'\n  }\n}\n\n/**\n * The Episode's Agent Revision names a model provider this host no longer runs, so its Session cannot be resumed.\n * Recovery hands the Episode off to the agent's current Revision; the history stays where it was.\n */\nexport class SessionModelUnavailableError extends Error {\n  constructor(message: string, options?: ErrorOptions) {\n    super(message, options)\n    this.name = 'SessionModelUnavailableError'\n  }\n}\n\n/** Single-lane M1 Runtime. M2 extends the same persisted states with injection and recovery. */\nexport class ChannelRuntime {\n  #admissionState: 'closed' | 'opening' | 'open' | 'disposed'\n  readonly #canAdmitAgent: (agentId: AgentId) => boolean\n  readonly #deferredRecoveryEpisodes = new Set<EpisodeId>()\n  #openingAdmission: Promise<void> | undefined\n  #disposing: Promise<void> | undefined\n  readonly #feedback: ProcessingFeedback\n  readonly #interactions: ChannelInteractions\n  readonly #delivery: ChannelDelivery\n  readonly #core: CoreService\n  readonly #coreRepository: CoreRepository\n  readonly #runtimeRepository: RuntimeRepository\n  readonly #sessionDriver: AgentSessionDriver\n  readonly #resolveAdapter: ChannelRuntimeOptions['resolveAdapter']\n  readonly #isActivityTriggerAllowed: NonNullable<ChannelRuntimeOptions['isActivityTriggerAllowed']>\n  readonly #isActivityTriggerEnabledByDefault: NonNullable<ChannelRuntimeOptions['isActivityTriggerEnabledByDefault']>\n  readonly #activityDirectedAt: NonNullable<ChannelRuntimeOptions['activityDirectedAt']>\n  /** Recent activity events that woke an agent, per channel, for the repeat guard. */\n  readonly #activityWakes = new Map<ChannelId, { readonly eventId: string; readonly at: number }[]>()\n  readonly #commands: CommandGate | undefined\n  readonly #inboundHooks: InboundHookGate | undefined\n  readonly #sanitizeInbound: (event: AdapterChannelInboundEvent) => AdapterChannelInboundEvent\n  readonly #validateActivityTriggerOverrides: NonNullable<ChannelRuntimeOptions['validateActivityTriggerOverrides']>\n  readonly #now: () => number\n  readonly #nextUlid: () => string\n  readonly #idleRolloverMs: number | false\n  readonly #pendingRollover: ChannelRuntimeOptions['pendingRollover']\n  readonly #lanes = new Map<string, Promise<void>>()\n  readonly #bindingTransitions = new Map<ChannelId, Promise<void>>()\n  readonly #factListeners = new Set<(fact: ChannelFact) => void>()\n  readonly #timing: ResponseTiming\n\n  constructor(\n    core: CoreService,\n    coreRepository: CoreRepository,\n    runtimeRepository: RuntimeRepository,\n    sessionDriver: AgentSessionDriver,\n    options: ChannelRuntimeOptions,\n  ) {\n    this.#admissionState = options.deferAdmission === true ? 'closed' : 'open'\n    this.#canAdmitAgent = options.canAdmitAgent ?? (() => true)\n    this.#core = core\n    this.#coreRepository = coreRepository\n    this.#runtimeRepository = runtimeRepository\n    this.#sessionDriver = sessionDriver\n    this.#resolveAdapter = options.resolveAdapter\n    this.#isActivityTriggerAllowed = options.isActivityTriggerAllowed ?? (() => true)\n    this.#isActivityTriggerEnabledByDefault = options.isActivityTriggerEnabledByDefault ?? (() => false)\n    this.#activityDirectedAt = options.activityDirectedAt ?? (() => undefined)\n    this.#commands = options.commands\n    this.#inboundHooks = options.inboundHooks\n    this.#sanitizeInbound = options.sanitizeInbound ?? ((event) => event)\n    this.#validateActivityTriggerOverrides = options.validateActivityTriggerOverrides ?? (() => undefined)\n    this.#now = options.now ?? Date.now\n    this.#nextUlid = options.nextUlid ?? monotonicFactory()\n    this.#idleRolloverMs = options.idleRolloverMs ?? 6 * 60 * 60 * 1000\n    this.#pendingRollover = options.pendingRollover\n    this.#timing = new ResponseTiming(() => this.#timestamp(), options.timers ?? systemTimers)\n    this.#interactions = new ChannelInteractions(\n      core,\n      coreRepository,\n      runtimeRepository,\n      options.resolveAdapter,\n      options.adapterState,\n      () => this.#timestamp(),\n      this.#nextUlid,\n    )\n    this.#feedback = new ProcessingFeedback(coreRepository, options.resolveAdapter, options.adapterState, () =>\n      this.#timestamp(),\n    )\n    this.#delivery = new ChannelDelivery(\n      coreRepository,\n      runtimeRepository,\n      options.resolveAdapter,\n      this.#feedback,\n      () => this.#timestamp(),\n      this.#nextUlid,\n      (fact) => this.#publishFact(fact),\n      { gapMs: options.messageGapMs ?? (() => 0), ...(options.sleep === undefined ? {} : { sleep: options.sleep }) },\n      options.onOutboundSettled,\n    )\n    if (this.#idleRolloverMs !== false && (!Number.isSafeInteger(this.#idleRolloverMs) || this.#idleRolloverMs <= 0)) {\n      throw new TypeError('idleRolloverMs must be a positive integer or false.')\n    }\n  }\n\n  async acceptChannelInbound(input: AdapterChannelInboundEvent): Promise<InboundCommitResult> {\n    const event = this.#sanitizeInbound(input)\n    const commit = this.#commands?.commitInbound(event) ?? this.#core.appendInbound(event)\n    if (this.#commands?.excludes(commit.event)) {\n      this.#publishFact({ channelId: event.channelId, kind: 'inbound', sourceId: commit.event.id })\n      return { channelEventId: commit.event.id, inserted: commit.inserted }\n    }\n    if (commit.inserted) {\n      this.#publishFact({ channelId: event.channelId, kind: 'inbound', sourceId: commit.event.id })\n      const bindings = this.#coreRepository\n        .listBindings(event.channelId)\n        .filter((binding) => this.#admissionState === 'open' && this.#canAdmitAgent(binding.agentId))\n      // Hooks see the committed fact; their decision is stored before any Admission can reference the event.\n      await Promise.all(bindings.map((binding) => this.#decideInboundHooks(binding, commit.event)))\n      await Promise.all(bindings.map((binding) => this.#route(binding, commit.event)))\n    }\n    return {\n      channelEventId: commit.event.id,\n      inserted: commit.inserted,\n    }\n  }\n\n  /**\n   * Commits a due scheduled job as a control fact in its channel and wakes the bound agent like any trigger. The\n   * dedupe key is the job and its scheduled time, so a restart that fires the same occurrence again is a no-op.\n   */\n  async fireExtensionJob(job: ExtensionJobFiring): Promise<InboundCommitResult | undefined> {\n    const channel = this.#coreRepository.getChannel(job.channelId)\n    const binding = this.#coreRepository.getBinding(job.channelId)\n    if (!channel || !binding || binding.agentId !== job.agentId) return undefined\n    const connection = this.#coreRepository.getConnection(channel.connectionId)\n    if (!connection) return undefined\n    const delayMinutes = Math.max(0, Math.round((job.firedAt - job.scheduledAt) / 60_000))\n    const note = job.note ?? chatNote(job)\n    return this.acceptChannelInbound({\n      connectionId: channel.connectionId,\n      channelId: channel.id,\n      adapterKey: connection.adapterKey,\n      kind: 'control',\n      parts: [{ type: 'text', text: `${job.label}${jobDetail(job)}` }],\n      platformTimestamp: job.firedAt,\n      receivedAt: job.firedAt,\n      dedupeKey: `extension-job:${job.jobId}:${job.scheduledAt}`,\n      facts: {\n        extensionJob: {\n          jobId: job.jobId,\n          label: job.label,\n          ...(job.extensionName === undefined ? {} : { extensionName: job.extensionName }),\n          ...(note === undefined ? {} : { note }),\n          scheduledAt: job.scheduledAt,\n          delayMinutes,\n        },\n      },\n    })\n  }\n\n  /**\n   * Decides what one committed message does for one binding (Decision 2026-10-31 响应时机与智能响应): it extends a\n   * wait for its sender, wakes the agent (at once or after the sender's burst), joins a running turn, or stays context.\n   */\n  async #route(binding: BindingRecord, event: ChannelEventRecord): Promise<void> {\n    if (this.#hookDecision(binding, event)?.hidden === true) return\n    const lane = laneKey(binding.channelId, binding.agentId)\n    const timing = resolveResponseTiming(binding.responseTiming)\n    const sender = event.senderMemberId\n    const running = this.#sessionRunning(binding)\n    if (\n      sender !== undefined &&\n      event.kind === 'message-created' &&\n      !isExtensionJobEvent(event) &&\n      this.#timing.waitingFor(lane) === sender\n    ) {\n      this.#timing.extendWait(lane)\n      return\n    }\n    const burst = sender === undefined ? undefined : `${lane}\\u0000${sender}`\n    const strong = this.#triggered(binding, event)\n    const mid = strong ? undefined : this.#midSignal(binding, event, lane, timing)\n    if (\n      !strong &&\n      mid === undefined &&\n      burst !== undefined &&\n      event.kind === 'message-created' &&\n      this.#timing.debouncing(burst)\n    ) {\n      // A plain follow-up from someone whose burst is collecting joins it and restarts the quiet period.\n      this.#timing.debounce(\n        burst,\n        timing.debounceSeconds * 1000,\n        timing.debounceMaxSeconds * 1000,\n        timing.debounceMaxMessages,\n      )\n      return\n    }\n    if (!strong && mid === undefined) {\n      if (running) await this.#withLane(binding.channelId, binding.agentId, () => this.#admit(binding, event))\n      return\n    }\n    this.#timing.cancelWait(lane)\n    const wake = (): Promise<void> =>\n      this.#withLane(binding.channelId, binding.agentId, () => this.#wake(binding, event, mid, timing))\n    if (\n      binding.triggerPolicy === 'smart' &&\n      timing.debounceSeconds > 0 &&\n      sender !== undefined &&\n      event.kind === 'message-created' &&\n      !isExtensionJobEvent(event) &&\n      !running\n    ) {\n      // Collected messages stay unadmitted and join the turn the newest one opens.\n      this.#timing.debounce(\n        burst!,\n        timing.debounceSeconds * 1000,\n        timing.debounceMaxSeconds * 1000,\n        timing.debounceMaxMessages,\n        () => {\n          void wake().catch((error: unknown) => {\n            console.warn(`[nekro-nxt] 频道 ${binding.channelId} 的合并消息没能交给智能体：${String(error)}`)\n          })\n        },\n      )\n      return\n    }\n    await wake()\n  }\n\n  async #wake(\n    binding: BindingRecord,\n    event: ChannelEventRecord,\n    mid: MidSignal | undefined,\n    timing: ResolvedResponseTiming,\n  ): Promise<void> {\n    const current = this.#coreRepository.getBinding(binding.channelId)\n    if (!current || current.agentId !== binding.agentId || current.paused) return\n    if (this.#coreRepository.getChannelEvent(event.id) === undefined) return\n    const lane = laneKey(binding.channelId, binding.agentId)\n    if (mid !== undefined) this.#timing.recordMidWake(lane)\n    if (\n      current.triggerPolicy === 'smart' &&\n      timing.attentionWake &&\n      event.senderMemberId !== undefined &&\n      this.#core.describeChannelMember(event.channelId, event.senderMemberId)?.kind === 'member'\n    ) {\n      this.#timing.noteAttention(lane, event.senderMemberId)\n    }\n    await this.#admit(current, event, undefined, mid === undefined ? {} : { note: midWakeNote(mid) })\n  }\n\n  /** Smart mode's optional wakes: the agent's name or an alias, or someone who was just talking with it. */\n  #midSignal(\n    binding: BindingRecord,\n    event: ChannelEventRecord,\n    lane: string,\n    timing: ResolvedResponseTiming,\n  ): MidSignal | undefined {\n    if (binding.triggerPolicy !== 'smart' || binding.paused) return undefined\n    if (event.kind !== 'message-created' || event.activityKey !== undefined || event.senderMemberId === undefined)\n      return undefined\n    if (this.#commands?.excludes(event) || this.#hookDecision(binding, event)?.trigger === 'suppress') return undefined\n    if (this.#core.describeChannelMember(event.channelId, event.senderMemberId)?.kind !== 'member') return undefined\n    if (!this.#timing.midWakeAvailable(lane, timing.midWakesPerMinute)) return undefined\n    if (timing.attentionWake && this.#timing.inAttention(lane, event.senderMemberId, timing.attentionSeconds * 1000)) {\n      return { kind: 'attention' }\n    }\n    if (timing.nameWake) {\n      const agent = this.#coreRepository.getAgent(binding.agentId)\n      const names = agent === undefined ? [] : [agent.revision.displayName, ...agent.revision.aliases]\n      const text = event.parts\n        .flatMap((part) => (part.type === 'text' ? [part.text] : []))\n        .join('\\n')\n        .toLocaleLowerCase()\n      const name = names.find((candidate) => candidate !== '' && text.includes(candidate.toLocaleLowerCase()))\n      if (name !== undefined) return { kind: 'name', name }\n    }\n    return undefined\n  }\n\n  #sessionRunning(binding: BindingRecord): boolean {\n    const episode = this.#runtimeRepository.getActiveEpisode(binding.channelId, binding.agentId)\n    return episode?.dshSessionId !== undefined && this.#sessionDriver.sessionStatus(episode.dshSessionId) === 'running'\n  }\n\n  /**\n   * Whether a session opened now should offer `waiting-for-more` at all. Pausing is left out on purpose: it is\n   * temporary, and `requestWaitForMore` still refuses while it lasts.\n   */\n  waitForMoreAvailable(channelId: ChannelId): boolean {\n    const binding = this.#coreRepository.getBinding(channelId)\n    return binding !== undefined && waitSupported(binding) && resolveResponseTiming(binding.responseTiming).waitEnabled\n  }\n\n  /**\n   * The agent ended its turn with `waiting-for-more`: wake it once the latest speaker has been quiet for `seconds`,\n   * within the channel's limits. Refused when the channel turned waiting off or the turn itself came from a wait.\n   */\n  requestWaitForMore(input: { readonly episodeId: EpisodeId; readonly seconds: number }): WaitForMoreResult {\n    const episode = this.#runtimeRepository.getEpisode(input.episodeId)\n    const binding = episode === undefined ? undefined : this.#coreRepository.getBinding(episode.channelId)\n    if (episode === undefined || binding === undefined || binding.agentId !== episode.agentId) {\n      return { accepted: false, reason: '这个频道已经不由你负责了。' }\n    }\n    if (binding.paused || !waitSupported(binding)) {\n      return { accepted: false, reason: '这个频道现在不会自动叫你，用不了等待。' }\n    }\n    const timing = resolveResponseTiming(binding.responseTiming)\n    if (!timing.waitEnabled) return { accepted: false, reason: '这个频道关闭了等待，直接回复或者结束这一轮。' }\n    const lane = laneKey(binding.channelId, binding.agentId)\n    if (this.#timing.blocked(lane)) {\n      return { accepted: false, reason: '这一轮是等待结束后开始的，不能再等，现在就回复。' }\n    }\n    const memberId = this.#timing.lastSpeaker(lane)\n    if (memberId === undefined) return { accepted: false, reason: '找不到要等的人。' }\n    const seconds = Math.min(\n      timing.waitMaxQuietSeconds,\n      Math.max(RESPONSE_WAIT_MIN_QUIET_SECONDS, Math.round(Number.isFinite(input.seconds) ? input.seconds : 0)),\n    )\n    const displayName = this.#coreRepository.getChannelMember(memberId)?.displayName\n    this.#timing.startWait(lane, memberId, seconds * 1000, timing.waitMaxTotalSeconds * 1000, (cause, waitedMs) => {\n      void this.#withLane(binding.channelId, binding.agentId, () =>\n        this.#endWait(binding.channelId, binding.agentId, memberId, cause, waitedMs, seconds),\n      ).catch((error: unknown) => {\n        console.warn(`[nekro-nxt] 频道 ${binding.channelId} 的等待结束后没能叫醒智能体：${String(error)}`)\n      })\n    })\n    return { accepted: true, memberId, ...(displayName === undefined ? {} : { displayName }), seconds }\n  }\n\n  /** The member the agent is waiting for in a channel, if any. */\n  responseWait(channelId: ChannelId): { readonly memberId: ChannelMemberId; readonly until: number } | undefined {\n    const binding = this.#coreRepository.getBinding(channelId)\n    return binding === undefined ? undefined : this.#timing.waitState(laneKey(channelId, binding.agentId))\n  }\n\n  async #endWait(\n    channelId: ChannelId,\n    agentId: AgentId,\n    memberId: ChannelMemberId,\n    cause: WaitEndCause,\n    waitedMs: number,\n    quietSeconds: number,\n  ): Promise<void> {\n    const binding = this.#coreRepository.getBinding(channelId)\n    const channel = this.#coreRepository.getChannel(channelId)\n    if (!binding || binding.agentId !== agentId || binding.paused || !channel) return\n    const connection = this.#coreRepository.getConnection(channel.connectionId)\n    if (!connection) return\n    const displayName = this.#coreRepository.getChannelMember(memberId)?.displayName ?? '对方'\n    const waitedSeconds = Math.round(waitedMs / 1000)\n    const at = this.#timestamp()\n    const commit = this.#core.appendInbound({\n      connectionId: channel.connectionId,\n      channelId,\n      adapterKey: connection.adapterKey,\n      kind: 'control',\n      parts: [\n        {\n          type: 'text',\n          text:\n            cause === 'quiet'\n              ? `${displayName} 已经 ${quietSeconds} 秒没再说话`\n              : `已经等了 ${displayName} ${waitedSeconds} 秒`,\n        },\n      ],\n      platformTimestamp: at,\n      receivedAt: at,\n      dedupeKey: `response-wait:${agentId}:${memberId}:${at}`,\n      facts: { responseWait: { memberId, cause, waitedSeconds, quietSeconds } },\n    })\n    if (!commit.inserted) return\n    this.#publishFact({ channelId, kind: 'inbound', sourceId: commit.event.id })\n    // The wait's own fact is no platform message, so the reaction goes on what the member said last.\n    const feedbackEvent = this.#coreRepository\n      .listChannelEvents(channelId, { limit: 50 })\n      .findLast(\n        (candidate) =>\n          candidate.kind === 'message-created' &&\n          candidate.senderMemberId === memberId &&\n          candidate.platformMessageId !== undefined,\n      )\n    await this.#admit(binding, commit.event, undefined, {\n      replyRequired: true,\n      fromWait: true,\n      ...(feedbackEvent === undefined ? {} : { feedbackEvent }),\n    })\n  }\n\n  async #decideInboundHooks(binding: BindingRecord, event: ChannelEventRecord): Promise<void> {\n    const hooks = this.#inboundHooks\n    if (this.#commands?.excludes(event)) return\n    event = this.#commands?.project(event) ?? event\n    if (hooks === undefined || event.kind !== 'message-created' || isExtensionJobEvent(event)) return\n    if (!hooks.covers(binding.agentId) || hooks.stored(event.id, binding.agentId) !== undefined) return\n    await hooks.decide({\n      binding,\n      event,\n      defaultTriggered: isTriggered(\n        binding,\n        event,\n        this.#isActivityTriggerAllowed,\n        this.#isActivityTriggerEnabledByDefault,\n      ),\n    })\n    // The message was published on commit, before the decision; publish it again so clients show the outcome.\n    this.#publishFact({ channelId: event.channelId, kind: 'inbound', sourceId: event.id })\n  }\n\n  #hookDecision(binding: BindingRecord, event: ChannelEventRecord): InboundHookDecision | undefined {\n    return this.#inboundHooks?.stored(event.id, binding.agentId)\n  }\n\n  /** Product trigger rule: binding policy, then a stored hook decision, then scheduled jobs that always wake. */\n  #triggered(binding: BindingRecord, event: ChannelEventRecord): boolean {\n    if (this.#commands?.excludes(event)) return false\n    // Pause outranks every automatic path, including jobs and forced hook decisions.\n    if (binding.paused) return false\n    if (isExtensionJobEvent(event)) return binding.triggerPolicy !== 'observe-only'\n    const decision = this.#hookDecision(binding, event)\n    if (decision?.hidden === true || decision?.trigger === 'suppress') return false\n    if (decision?.trigger === 'force') return binding.triggerPolicy !== 'observe-only'\n    if (this.#isObservedLocalAgentMessage(binding, event)) return false\n    if (!isTriggered(binding, event, this.#isActivityTriggerAllowed, this.#isActivityTriggerEnabledByDefault)) {\n      return false\n    }\n    return event.activityKey === undefined || this.#activityWakesAgent(event)\n  }\n\n  /**\n   * An activity wakes the agent only when someone else did it to the agent's own account. What the account does\n   * itself (a reaction, a poke, a recall) comes back from the platform as an activity too; letting it trigger would\n   * loop. A burst of activities is capped so a missed case still cannot loop.\n   */\n  #activityWakesAgent(event: ChannelEventRecord): boolean {\n    const isSelf = (memberId: unknown): boolean => {\n      const parsed = ChannelMemberIdSchema.safeParse(memberId)\n      return parsed.success && this.#core.describeChannelMember(event.channelId, parsed.data)?.kind === 'self'\n    }\n    if (event.senderMemberId !== undefined && isSelf(event.senderMemberId)) return false\n    const directedAt = this.#activityDirectedAt(event.channelId, event.activityKey!)\n    if (directedAt === 'member' && !isSelf(event.facts?.['targetMemberId'])) return false\n    if (directedAt === 'message') {\n      const channel = this.#coreRepository.getChannel(event.channelId)\n      const target =\n        channel === undefined || event.targetLogicalMessageId === undefined\n          ? undefined\n          : this.#coreRepository.resolveLogicalMessage(\n              channel.connectionId,\n              event.channelId,\n              event.targetLogicalMessageId,\n            )\n      if (target?.authoredByAgent !== true) return false\n    }\n    const recent = (this.#activityWakes.get(event.channelId) ?? []).filter(\n      (wake) => wake.at > event.receivedAt - ACTIVITY_WAKE_WINDOW_MS,\n    )\n    if (recent.some((wake) => wake.eventId === event.id)) return true\n    if (recent.length >= ACTIVITY_WAKE_LIMIT) return false\n    recent.push({ eventId: event.id, at: event.receivedAt })\n    this.#activityWakes.set(event.channelId, recent)\n    return true\n  }\n\n  /**\n   * Another agent on this host speaking in the same group stays context unless it addresses this agent, so two agents\n   * that both answer every message do not answer each other forever.\n   */\n  #isObservedLocalAgentMessage(binding: BindingRecord, event: ChannelEventRecord): boolean {\n    if (binding.localAgentMessages === 'trigger' || event.senderMemberId === undefined) return false\n    if (event.facts?.['mentionedBot'] === true || event.facts?.['replyToBot'] === true) return false\n    return this.#core.describeChannelMember(event.channelId, event.senderMemberId)?.kind === 'local-account'\n  }\n\n  /** A scheduled job wakes the agent without obliging it to speak. */\n  #replyRequired(binding: BindingRecord, events: readonly ChannelEventRecord[]): boolean {\n    return events.some((event) => !isExtensionJobEvent(event) && this.#triggered(binding, event))\n  }\n\n  #visibleEvents(binding: BindingRecord, events: readonly ChannelEventRecord[]): readonly ChannelEventRecord[] {\n    return events\n      .filter((event) => !this.#commands?.excludes(event) && this.#hookDecision(binding, event)?.hidden !== true)\n      .map((event) => this.#commands?.project(event) ?? event)\n  }\n\n  #annotations(\n    binding: BindingRecord,\n    events: readonly ChannelEventRecord[],\n  ): ReadonlyMap<ChannelEventId, readonly InboundAnnotation[]> {\n    const annotations = new Map<ChannelEventId, readonly InboundAnnotation[]>()\n    for (const event of events) {\n      const decision = this.#hookDecision(binding, event)\n      const notes = [\n        ...(decision?.hostAnnotations ?? []),\n        ...(decision?.annotation === undefined || decision.annotation === ''\n          ? []\n          : [{ label: EXTENSION_ANNOTATION_LABEL, text: decision.annotation }]),\n      ]\n      if (notes.length > 0) annotations.set(event.id, notes)\n    }\n    return annotations\n  }\n\n  /** Reopens admission and sweeps durable backlog; repeat after repairing an Agent quarantine. */\n  openAdmission(): Promise<void> {\n    if (this.#admissionState === 'disposed') return Promise.reject(new Error('Channel Runtime is disposed.'))\n    if (this.#openingAdmission !== undefined) return this.#openingAdmission\n    const wasClosed = this.#admissionState === 'closed'\n    this.#admissionState = 'opening'\n    const opening = (async () => {\n      try {\n        // Persisted Admissions must be reconciled before new inbound can enter their lane.\n        await this.#recover(!wasClosed)\n        if (this.#admissionState === 'disposed') return\n        this.#admissionState = 'open'\n        const lanes = this.#coreRepository.listConnectionIdsByAdapter().flatMap((connectionId) =>\n          this.#coreRepository.listChannelIdsByConnection(connectionId).flatMap((channelId) => {\n            const binding = this.#coreRepository.getBinding(channelId)\n            if (!binding || !this.#canAdmitAgent(binding.agentId)) return []\n            return [\n              this.#withLane(channelId, binding.agentId, () =>\n                this.#recoverTriggeredBacklog(channelId, binding.agentId),\n              ),\n            ]\n          }),\n        )\n        const outcomes = await Promise.allSettled(lanes)\n        const failures = outcomes\n          .filter((result): result is PromiseRejectedResult => result.status === 'rejected')\n          .map((result): unknown => result.reason)\n        if (failures.length) throw new AggregateError(failures, 'Unable to open Channel admission.')\n      } catch (error) {\n        if (this.#admissionState !== 'disposed') this.#admissionState = 'closed'\n        throw error\n      }\n    })()\n    this.#openingAdmission = opening\n    void opening\n      .finally(() => {\n        if (this.#openingAdmission === opening) this.#openingAdmission = undefined\n      })\n      .catch(() => undefined)\n    return opening\n  }\n\n  /** Close the gate synchronously, then wait for admitted work and feedback cleanup to settle. */\n  dispose(): Promise<void> {\n    if (this.#disposing !== undefined) return this.#disposing\n    this.#admissionState = 'disposed'\n    this.#timing.dispose()\n    this.#disposing = (async () => {\n      await Promise.allSettled([\n        ...(this.#openingAdmission === undefined ? [] : [this.#openingAdmission]),\n        ...this.#bindingTransitions.values(),\n        ...this.#lanes.values(),\n      ])\n      await this.#feedback.stopProcessingFeedback()\n      this.#factListeners.clear()\n    })()\n    return this.#disposing\n  }\n\n  #runtimeAdmissionOpen(): boolean {\n    return this.#admissionState !== 'closed' && this.#admissionState !== 'disposed'\n  }\n\n  #admissionAllowed(agentId: AgentId): boolean {\n    return this.#runtimeAdmissionOpen() && this.#canAdmitAgent(agentId)\n  }\n\n  async recoverProcessingFeedback(): Promise<void> {\n    for (const connectionId of this.#coreRepository.listConnectionIdsByAdapter())\n      await this.#interactions.ensureInteractionsLoaded(connectionId)\n    await this.#feedback.recoverProcessingFeedback()\n  }\n\n  async stopProcessingFeedback(): Promise<void> {\n    await this.#feedback.stopProcessingFeedback()\n  }\n\n  /** The host's own view of processing feedback on a Connection: undefined while nothing has gone wrong. */\n  processingFeedbackStatus(connectionId: ConnectionId): AdapterCapabilityState | undefined {\n    return this.#feedback.status(connectionId)\n  }\n\n  subscribeProcessingFeedbackStatus(listener: (connectionId: ConnectionId) => void): () => void {\n    return this.#feedback.subscribeStatus(listener)\n  }\n\n  /** Waits for all current Session work on the supplied Connections to reach an idle checkpoint. */\n  async waitUntilConnectionsSafe(connectionIds: readonly ConnectionId[]): Promise<void> {\n    const seen = new Set<string>()\n    const waits = connectionIds.flatMap((connectionId) =>\n      this.#coreRepository.listChannelIdsByConnection(connectionId).flatMap((channelId) => {\n        const binding = this.#coreRepository.getBinding(channelId)\n        if (!binding) return []\n        const key = `${channelId}\\u0000${binding.agentId}`\n        if (seen.has(key)) return []\n        seen.add(key)\n        return [\n          this.#withLane(channelId, binding.agentId, async () => {\n            const episode = this.#runtimeRepository.getActiveEpisode(channelId, binding.agentId)\n            if (episode?.dshSessionId !== undefined) {\n              await (this.#sessionDriver.whenIdle?.(episode.dshSessionId) ?? Promise.resolve())\n            }\n          }),\n        ]\n      }),\n    )\n    const outcomes = await Promise.allSettled(waits)\n    const failures = outcomes\n      .filter((outcome): outcome is PromiseRejectedResult => outcome.status === 'rejected')\n      .map((outcome): unknown => outcome.reason)\n    if (failures.length) throw new AggregateError(failures, 'Adapter connections could not quiesce.')\n  }\n  retractChannelMessage(input: {\n    readonly episodeId: EpisodeId\n    readonly logicalMessageId: LogicalMessageId\n    readonly clientRequestId: string\n  }): Promise<ChannelInteractionResult> {\n    return this.#interactions.retractChannelMessage(input)\n  }\n\n  nudgeChannelMember(input: {\n    readonly episodeId: EpisodeId\n    readonly memberId: ChannelMemberId\n    readonly clientRequestId: string\n  }): Promise<ChannelInteractionResult> {\n    return this.#interactions.nudgeChannelMember(input)\n  }\n\n  invokeChannelPlatformAction(input: {\n    readonly episodeId: EpisodeId\n    readonly action: string\n    readonly args: Readonly<Record<string, JsonValue>>\n    readonly clientRequestId: string\n  }): Promise<ChannelInteractionResult> {\n    return this.#interactions.invokeChannelPlatformAction(input)\n  }\n\n  invokeChannelRawApi(input: {\n    readonly episodeId: EpisodeId\n    readonly api: string\n    readonly params: Readonly<Record<string, JsonValue>>\n    readonly clientRequestId: string\n  }): Promise<ChannelInteractionResult> {\n    return this.#interactions.invokeChannelRawApi(input)\n  }\n\n  subscribeFacts(listener: (fact: ChannelFact) => void): () => void {\n    this.#factListeners.add(listener)\n    return () => this.#factListeners.delete(listener)\n  }\n\n  publishInboundFact(event: ChannelEventRecord): void {\n    this.#publishFact({ channelId: event.channelId, kind: 'inbound', sourceId: event.id })\n  }\n\n  sendHostNotice(input: Parameters<ChannelDelivery['sendHostNotice']>[0]): Promise<SendMessageResult> {\n    return this.#delivery.sendHostNotice(input)\n  }\n\n  sendCommandReply(input: Parameters<ChannelDelivery['sendCommandReply']>[0]): Promise<SendMessageResult> {\n    return this.#delivery.sendCommandReply(input)\n  }\n\n  /**\n   * Pauses or resumes every automatic response in the Channel without touching the response rule. Pausing also\n   * stops the current turn so it takes effect at once; resuming never replays stopped work. Runs in the same lane as\n   * rebinding and admissions and retains the binding generation when the caller passes it.\n   */\n  async setPaused(\n    channelId: ChannelId,\n    paused: boolean,\n    options: { readonly boundAt?: number; readonly guard?: () => void } = {},\n  ): Promise<{ readonly paused: boolean; readonly changed: boolean; readonly stopped: boolean }> {\n    const binding = this.#coreRepository.getBinding(channelId)\n    if (!binding) {\n      options.guard?.()\n      throw new Error('频道还没有绑定智能体。')\n    }\n    return this.#withLane(channelId, binding.agentId, async () => {\n      options.guard?.()\n      const current = this.#coreRepository.getBinding(channelId)\n      if (\n        !current ||\n        current.agentId !== binding.agentId ||\n        (options.boundAt !== undefined && current.boundAt !== options.boundAt)\n      )\n        throw new Error('频道绑定已变化，请重新操作。')\n      const changed = current.paused !== paused\n      if (changed) this.#coreRepository.replaceBinding({ ...current, paused })\n      if (paused) this.#timing.clearLane(laneKey(channelId, current.agentId))\n      const stopped = paused\n        ? (await this.#interruptActiveTurn(channelId, current.agentId)).result === 'stopped'\n        : false\n      return { paused, changed, stopped }\n    })\n  }\n\n  async replaceBinding(input: {\n    readonly channelId: ChannelId\n    readonly agentId: AgentId\n    readonly triggerPolicy: BindingRecord['triggerPolicy']\n    readonly processingFeedback?: BindingRecord['processingFeedback']\n    readonly localAgentMessages?: BindingRecord['localAgentMessages']\n    readonly activityTriggerOverrides?: BindingRecord['activityTriggerOverrides']\n    readonly responseTiming?: BindingRecord['responseTiming']\n  }): Promise<BindingRecord> {\n    if (input.activityTriggerOverrides !== undefined)\n      this.#validateActivityTriggerOverrides(input.channelId, input.activityTriggerOverrides)\n    return this.#withBindingTransition(input.channelId, async () => {\n      const current = this.#coreRepository.getBinding(input.channelId)\n      const laneAgentId = current?.agentId ?? input.agentId\n      return this.#withLane(input.channelId, laneAgentId, async () => {\n        if (current !== undefined && current.agentId !== input.agentId) {\n          const episode = this.#runtimeRepository.getActiveEpisode(input.channelId, current.agentId)\n          if (episode?.dshSessionId !== undefined) {\n            this.#feedback.markEndReason(episode.id, 'cancelled')\n            await this.#sessionDriver.cancelSession(episode.dshSessionId, 'binding-replaced')\n            await this.#feedback.cleanupEpisodeFeedback(episode.id)\n            this.#runtimeRepository.closeEpisode(\n              episode.id,\n              'binding-replaced',\n              episode.lastAdmittedEventId ?? episode.openedAtEventId,\n              this.#timestamp(),\n            )\n          }\n        }\n        const next = this.#core.replaceBinding({\n          ...input,\n          processingFeedback: input.processingFeedback ?? current?.processingFeedback ?? 'auto',\n          localAgentMessages: input.localAgentMessages ?? current?.localAgentMessages ?? 'observe',\n          activityTriggerOverrides: input.activityTriggerOverrides ?? current?.activityTriggerOverrides ?? {},\n          responseTiming: input.responseTiming ?? current?.responseTiming ?? {},\n        })\n        this.#timing.clearLane(laneKey(input.channelId, laneAgentId))\n        return next\n      })\n    })\n  }\n\n  async clearBinding(channelId: ChannelId): Promise<void> {\n    await this.#withBindingTransition(channelId, async () => {\n      const current = this.#coreRepository.getBinding(channelId)\n      if (!current) return\n      await this.#withLane(channelId, current.agentId, async () => {\n        this.#timing.clearLane(laneKey(channelId, current.agentId))\n        const episode = this.#runtimeRepository.getActiveEpisode(channelId, current.agentId)\n        if (episode?.status === 'active' && episode.dshSessionId !== undefined) {\n          this.#feedback.markEndReason(episode.id, 'cancelled')\n          await this.#sessionDriver.cancelSession(episode.dshSessionId, 'stopped')\n          await this.#feedback.cleanupEpisodeFeedback(episode.id)\n          this.#runtimeRepository.closeEpisode(\n            episode.id,\n            'stopped',\n            episode.lastAdmittedEventId ?? episode.openedAtEventId,\n            this.#timestamp(),\n          )\n        }\n        this.#core.clearBinding(channelId)\n      })\n    })\n  }\n\n  /** Stops the live lane while preserving the Channel and its Binding for a later Connection restore. */\n  async suspendChannel(channelId: ChannelId): Promise<void> {\n    await this.#withBindingTransition(channelId, async () => {\n      const current = this.#coreRepository.getBinding(channelId)\n      if (!current) return\n      await this.#withLane(channelId, current.agentId, async () => {\n        const episode = this.#runtimeRepository.getActiveEpisode(channelId, current.agentId)\n        if (episode?.dshSessionId !== undefined) {\n          this.#feedback.markEndReason(episode.id, 'cancelled')\n          await this.#sessionDriver.cancelSession(episode.dshSessionId, 'stopped')\n          await this.#feedback.cleanupEpisodeFeedback(episode.id)\n        }\n        if (episode !== undefined) {\n          this.#runtimeRepository.closeEpisode(\n            episode.id,\n            'stopped',\n            episode.lastAdmittedEventId ?? episode.openedAtEventId,\n            this.#timestamp(),\n          )\n        }\n      })\n    })\n  }\n\n  /** Stops the live lane before removing a Channel from active product state. */\n  async deleteChannel(channelId: ChannelId): Promise<void> {\n    await this.#withBindingTransition(channelId, async () => {\n      if (!this.#coreRepository.getChannel(channelId)) throw new Error(`Unknown channel: ${channelId}`)\n      const current = this.#coreRepository.getBinding(channelId)\n      if (!current) {\n        this.#core.deleteChannel(channelId)\n        return\n      }\n      await this.#withLane(channelId, current.agentId, async () => {\n        const episode = this.#runtimeRepository.getActiveEpisode(channelId, current.agentId)\n        if (episode?.dshSessionId !== undefined) {\n          this.#feedback.markEndReason(episode.id, 'cancelled')\n          await this.#sessionDriver.cancelSession(episode.dshSessionId, 'channel-deleted')\n          await this.#feedback.cleanupEpisodeFeedback(episode.id)\n        }\n        if (episode !== undefined) {\n          this.#runtimeRepository.closeEpisode(\n            episode.id,\n            'channel-deleted',\n            episode.lastAdmittedEventId ?? episode.openedAtEventId,\n            this.#timestamp(),\n          )\n        }\n        this.#core.deleteChannel(channelId)\n      })\n    })\n  }\n  /**\n   * Stops the channel's live conversation, then runs `purge` while no message can be admitted, so 「彻底清除」 never\n   * races a turn that is still writing to the conversation it removes. The Binding stays; the next message opens a\n   * fresh Episode. `guard` runs inside the lane before anything is stopped and may refuse by throwing.\n   */\n  async purgeChannelHistory<T>(channelId: ChannelId, purge: () => Promise<T>, guard?: () => void): Promise<T> {\n    return this.#withBindingTransition(channelId, async () => {\n      if (!this.#coreRepository.getChannel(channelId)) throw new Error(`Unknown channel: ${channelId}`)\n      const current = this.#coreRepository.getBinding(channelId)\n      const run = async (): Promise<T> => {\n        guard?.()\n        this.#activityWakes.delete(channelId)\n        if (current !== undefined) {\n          this.#timing.clearLane(laneKey(channelId, current.agentId))\n          const episode = this.#runtimeRepository.getActiveEpisode(channelId, current.agentId)\n          if (episode?.dshSessionId !== undefined) {\n            this.#feedback.markEndReason(episode.id, 'cancelled')\n            await this.#sessionDriver.cancelSession(episode.dshSessionId, 'context-cleared')\n            await this.#feedback.cleanupEpisodeFeedback(episode.id)\n          }\n          if (episode !== undefined) {\n            this.#runtimeRepository.closeEpisode(\n              episode.id,\n              'context-cleared',\n              episode.lastAdmittedEventId ?? episode.openedAtEventId,\n              this.#timestamp(),\n            )\n            this.#deferredRecoveryEpisodes.delete(episode.id)\n          }\n        }\n        return purge()\n      }\n      return current === undefined ? run() : this.#withLane(channelId, current.agentId, run)\n    })\n  }\n\n  async sendMessage(input: SendMessageInput): Promise<SendMessageResult> {\n    const result = await this.#delivery.sendMessage(input)\n    if (result.status === 'sent' || result.status === 'partially-sent') {\n      const episode = this.#runtimeRepository.getEpisode(input.episodeId)\n      const binding = episode === undefined ? undefined : this.#coreRepository.getBinding(episode.channelId)\n      if (episode !== undefined && binding?.agentId === episode.agentId) {\n        this.#timing.agentSpoke(\n          laneKey(episode.channelId, episode.agentId),\n          resolveResponseTiming(binding.responseTiming).attentionSeconds * 1000,\n        )\n      }\n    }\n    return result\n  }\n\n  async sendAdminConsoleMessage(input: {\n    readonly channelId: ChannelId\n    readonly parts: readonly MessagePart[]\n    readonly clientRequestId?: string\n    readonly signal?: AbortSignal\n  }): Promise<SendMessageResult> {\n    const channel = this.#coreRepository.getChannel(input.channelId)\n    if (!channel) throw new Error(`Unknown channel: ${input.channelId}`)\n    if (channel.kind === 'internal') {\n      throw new Error('Web channels accept inbound conversation, not robot-account delivery.')\n    }\n    const binding = this.#coreRepository.getBinding(channel.id)\n    if (!binding) throw new Error('Channel has no Binding.')\n    const adapter = this.#resolveAdapter(channel.connectionId)\n    if (!adapter) throw new Error(`Connection adapter is not running: ${channel.connectionId}`)\n    if (!adapter.capabilities.outbound.proactiveSend) {\n      throw new Error('Adapter does not allow proactive send.')\n    }\n    return this.#withLane(channel.id, binding.agentId, async () => {\n      const openedAt = this.#consoleOpenedAtEvent(channel)\n      const episode = await this.#ensureActiveEpisode(binding, openedAt)\n      const result = await this.sendMessage({\n        episodeId: episode.id,\n        parts: input.parts,\n        sourceTurnId: ADMIN_CONSOLE_SOURCE_TURN,\n        ...(input.clientRequestId === undefined ? {} : { clientRequestId: input.clientRequestId }),\n        ...(input.signal === undefined ? {} : { signal: input.signal }),\n      })\n      if (\n        episode.dshSessionId &&\n        (result.status === 'sent' || result.status === 'partially-sent' || result.status === 'unknown')\n      ) {\n        await this.#sessionDriver.notifyConsoleOutbound({\n          dshSessionId: episode.dshSessionId,\n          channelId: channel.id,\n          logicalMessageId: result.logicalMessageId,\n          parts: input.parts,\n        })\n      }\n      return result\n    })\n  }\n\n  recover(): Promise<RuntimeRecoveryReport> {\n    return this.#recover()\n  }\n\n  async #recover(onlyDeferred = false): Promise<RuntimeRecoveryReport> {\n    const report = {\n      resumedEpisodes: 0,\n      recoveredAdmissions: 0,\n      recoveredOutbounds: 0,\n      unknownDeliveries: 0,\n    }\n    if (this.#admissionState === 'closed' || this.#admissionState === 'disposed') return report\n    for (const recoverable of this.#runtimeRepository.listRecoverableEpisodes()) {\n      if (onlyDeferred && !this.#deferredRecoveryEpisodes.has(recoverable.id)) continue\n      await this.#withLane(recoverable.channelId, recoverable.agentId, async () => {\n        if (!this.#admissionAllowed(recoverable.agentId)) {\n          this.#deferredRecoveryEpisodes.add(recoverable.id)\n          return\n        }\n        let episode = recoverable\n        const handoff = this.#runtimeRepository.getEpisodeHandoffTo(episode.id)\n        const recoverableAdmissions = this.#runtimeRepository.listRecoverableAdmissions(episode.id)\n        if (episode.status === 'opening' && handoff !== undefined) {\n          const previous = this.#runtimeRepository.getEpisode(handoff.fromEpisodeId)\n          if (previous?.dshSessionId !== undefined) {\n            this.#feedback.markEndReason(previous.id, 'cancelled')\n            await this.#sessionDriver.cancelSession(previous.dshSessionId, previous.closeReason ?? 'manual')\n            await this.#feedback.cleanupEpisodeFeedback(previous.id)\n          }\n        }\n        const recentEvents =\n          handoff?.recentEventIds\n            .map((eventId) => this.#coreRepository.getChannelEvent(eventId))\n            .filter((event): event is ChannelEventRecord => event !== undefined) ?? []\n        let dshSessionId: string\n        let rolledOver = false\n        try {\n          dshSessionId = await this.#sessionDriver.createSession({\n            episodeId: episode.id,\n            channelId: episode.channelId,\n            agentId: episode.agentId,\n            agentRevisionId: episode.agentRevisionId,\n            ...(handoff === undefined\n              ? {}\n              : {\n                  handoff: {\n                    id: handoff.id,\n                    fromEpisodeId: handoff.fromEpisodeId,\n                    sourceEventIds: handoff.sourceEventIds,\n                    createdAt: handoff.createdAt,\n                    provider: handoff.provider,\n                    model: handoff.model,\n                    summary: handoff.summary,\n                    recentEvents,\n                  },\n                }),\n          })\n        } catch (error) {\n          if (error instanceof SessionModelUnavailableError) {\n            const resumed = await this.#handOffUnresumable(episode, error)\n            if (resumed === undefined) {\n              this.#deferredRecoveryEpisodes.add(episode.id)\n              return\n            }\n            if (resumed.dshSessionId === undefined) throw new Error(`Handed-off Episode has no Session: ${resumed.id}`)\n            episode = resumed\n            dshSessionId = resumed.dshSessionId\n            rolledOver = true\n          } else {\n            if (!(error instanceof UnrecoverableSessionError)) throw error\n            console.error(`[nekro-nxt] 频道 ${episode.channelId} 的对话记录无法读取，已结束这段对话：`, error)\n            this.#feedback.markEndReason(episode.id, 'cancelled')\n            await this.#feedback.cleanupEpisodeFeedback(episode.id)\n            this.#runtimeRepository.closeEpisode(\n              episode.id,\n              'unrecoverable-session',\n              episode.lastAdmittedEventId ?? episode.openedAtEventId,\n              this.#timestamp(),\n            )\n            this.#deferredRecoveryEpisodes.delete(episode.id)\n            return\n          }\n        }\n        // A handed-off Episode is already active; the old one's pending input follows it below.\n        if (!rolledOver && episode.status === 'opening') {\n          episode = this.#runtimeRepository.activateEpisode(episode.id, dshSessionId)\n        } else if (!rolledOver && episode.dshSessionId !== dshSessionId) {\n          throw new Error(`Recovered DSH Session identity changed for Episode ${episode.id}.`)\n        }\n        report.resumedEpisodes += 1\n\n        for (const admission of recoverableAdmissions) {\n          if (!this.#admissionAllowed(episode.agentId)) {\n            this.#deferredRecoveryEpisodes.add(episode.id)\n            return\n          }\n          if (admission.state === 'pending') this.#runtimeRepository.claimAdmission(admission.id)\n          const existing = this.#sessionDriver.findAdmissionMessage(dshSessionId, admission.id)\n          const lastEventId = admission.eventIds.at(-1)\n          if (!lastEventId) throw new Error(`Recoverable Admission has no Channel Events: ${admission.id}`)\n          if (existing) {\n            this.#runtimeRepository.completeAdmission(admission.id, existing, lastEventId)\n            report.recoveredAdmissions += 1\n            continue\n          }\n          const events = admission.eventIds.map((id) => {\n            const event = this.#coreRepository.getChannelEvent(id)\n            if (!event) throw new Error(`Admission references a missing Channel Event: ${id}`)\n            return event\n          })\n          const binding = this.#coreRepository.getBinding(episode.channelId)\n          const current = binding?.agentId === episode.agentId ? binding : undefined\n          const visible = current === undefined ? events : this.#visibleEvents(current, events)\n          const annotations = current === undefined ? new Map() : this.#annotations(current, visible)\n          const result = await this.#sessionDriver.admit({\n            dshSessionId,\n            admissionId: admission.id,\n            events: visible,\n            mode: admission.mode,\n            replyRequired: current !== undefined && this.#replyRequired(current, visible),\n            ...(annotations.size === 0 ? {} : { annotations }),\n          })\n          this.#runtimeRepository.completeAdmission(admission.id, result.dshMessageId, lastEventId)\n          report.recoveredAdmissions += 1\n        }\n        await this.#recoverTriggeredBacklog(episode.channelId, episode.agentId)\n        this.#deferredRecoveryEpisodes.delete(episode.id)\n      })\n    }\n\n    if (onlyDeferred) return report\n    for (const outboundId of this.#runtimeRepository.listUnsettledOutboundIds()) {\n      if (!this.#runtimeAdmissionOpen()) break\n      const result = await this.#delivery.dispatchOutbound(outboundId, new AbortController().signal)\n      report.recoveredOutbounds += 1\n      report.unknownDeliveries += result.unknownDeliveries\n    }\n    return report\n  }\n\n  async stopEpisode(\n    episodeId: EpisodeId,\n    reason: Extract<EpisodeCloseReason, 'permission-revoked' | 'stopped'> = 'stopped',\n  ): Promise<EpisodeRecord> {\n    const initial = this.#runtimeRepository.getEpisode(episodeId)\n    if (!initial) throw new Error(`Unknown Episode: ${episodeId}`)\n    return this.#withLane(initial.channelId, initial.agentId, async () => {\n      const episode = this.#runtimeRepository.getEpisode(episodeId)\n      if (!episode || episode.status !== 'active' || !episode.dshSessionId) {\n        throw new Error(`Episode is not active: ${episodeId}`)\n      }\n      this.#feedback.markEndReason(episode.id, 'cancelled')\n      await this.#sessionDriver.cancelSession(episode.dshSessionId, reason)\n      await this.#feedback.cleanupEpisodeFeedback(episode.id)\n      return this.#runtimeRepository.closeEpisode(\n        episode.id,\n        reason,\n        episode.lastAdmittedEventId ?? episode.openedAtEventId,\n        this.#timestamp(),\n      )\n    })\n  }\n\n  /**\n   * Stops the bound Agent's current turn in this Channel without resetting its context. Admitted input stays\n   * queued for the next turn. An idle Channel reports `idle` instead of failing.\n   */\n  async stopCurrentTurn(\n    channelId: ChannelId,\n    expectedEpisodeId?: EpisodeId,\n    guard?: () => void,\n  ): Promise<{\n    readonly result: 'stopped' | 'idle'\n    readonly episodeId?: EpisodeId\n    readonly retainedPending: number\n  }> {\n    const binding = this.#coreRepository.getBinding(channelId)\n    if (!binding) {\n      guard?.()\n      return { result: 'idle', retainedPending: 0 }\n    }\n    return this.#withLane(channelId, binding.agentId, async () => {\n      guard?.()\n      return this.#interruptActiveTurn(channelId, binding.agentId, expectedEpisodeId)\n    })\n  }\n\n  /** The body of `stopCurrentTurn`; callers already hold the Channel lane. */\n  async #interruptActiveTurn(\n    channelId: ChannelId,\n    agentId: AgentId,\n    expectedEpisodeId?: EpisodeId,\n  ): Promise<{\n    readonly result: 'stopped' | 'idle'\n    readonly episodeId?: EpisodeId\n    readonly retainedPending: number\n  }> {\n    const episode = this.#runtimeRepository.getActiveEpisode(channelId, agentId)\n    if (expectedEpisodeId !== undefined && episode?.id !== expectedEpisodeId) {\n      throw new ChannelStopConflictError('频道上下文已发生变化，请刷新后重试。')\n    }\n    if (!episode || episode.status !== 'active' || episode.dshSessionId === undefined) {\n      return { result: 'idle' as const, retainedPending: 0 }\n    }\n    if (this.#sessionDriver.sessionStatus(episode.dshSessionId) === 'idle') {\n      return {\n        result: 'idle' as const,\n        episodeId: episode.id,\n        retainedPending: this.#sessionDriver.listPendingAdmissions(episode.dshSessionId).length,\n      }\n    }\n    this.#feedback.markEndReason(episode.id, 'cancelled')\n    const outcome = await this.#sessionDriver.interruptTurn(episode.dshSessionId, 'stopped-by-administrator')\n    return {\n      result: outcome.interrupted ? ('stopped' as const) : ('idle' as const),\n      episodeId: episode.id,\n      retainedPending: outcome.retainedPending,\n    }\n  }\n\n  /** Fails before any state change when the Outbound cannot be dispatched again now. */\n  assertOutboundDispatchable(id: OutboundIntentId): void {\n    const snapshot = this.#runtimeRepository.getOutbound(id)\n    const episode =\n      snapshot.intent.episodeId === undefined\n        ? undefined\n        : this.#runtimeRepository.getEpisode(snapshot.intent.episodeId)\n    const channelId = snapshot.intent.channelId ?? episode?.channelId\n    const channel = channelId === undefined ? undefined : this.#coreRepository.getChannel(channelId)\n    if (!channel) throw new Error('这条消息所属的频道已不存在。')\n    if (!this.#resolveAdapter(channel.connectionId)) throw new Error('平台连接当前未运行，暂时无法重新发送。')\n  }\n\n  /** Dispatches an Outbound that an administrator returned to `planned`; idempotent through the delivery states. */\n  async redispatchOutbound(id: OutboundIntentId): Promise<OutboundSnapshot> {\n    return (await this.#delivery.dispatchOutbound(id, new AbortController().signal)).snapshot\n  }\n\n  /** Re-announces an Outbound so clients refresh its projection after an administrator resolution. */\n  publishOutboundFact(id: OutboundIntentId): void {\n    const intent = this.#runtimeRepository.getOutbound(id).intent\n    const episode = intent.episodeId === undefined ? undefined : this.#runtimeRepository.getEpisode(intent.episodeId)\n    const channelId = intent.channelId ?? episode?.channelId\n    if (channelId) this.#publishFact({ channelId, kind: 'outbound', sourceId: id })\n  }\n\n  /** Admitted input waiting in the bound Agent's live Session, in DSH consumption order. */\n  listPendingContext(channelId: ChannelId): {\n    readonly episodeId?: EpisodeId\n    readonly items: readonly {\n      readonly admissionId: AdmissionId\n      readonly target: 'next-step' | 'next-turn'\n      readonly events: readonly ChannelEventRecord[]\n    }[]\n  } {\n    const binding = this.#coreRepository.getBinding(channelId)\n    const episode =\n      binding === undefined ? undefined : this.#runtimeRepository.getActiveEpisode(channelId, binding.agentId)\n    if (!episode || episode.status !== 'active' || episode.dshSessionId === undefined) return { items: [] }\n    return {\n      episodeId: episode.id,\n      items: this.#sessionDriver.listPendingAdmissions(episode.dshSessionId).map((item) => ({\n        admissionId: item.admissionId,\n        target: item.target,\n        events: item.channelEventIds.flatMap((eventId) => {\n          const event = this.#coreRepository.getChannelEvent(eventId)\n          return event === undefined || event.channelId !== channelId ? [] : [event]\n        }),\n      })),\n    }\n  }\n\n  async rolloverEpisode(episodeId: EpisodeId): Promise<EpisodeRecord> {\n    return this.#rolloverEpisodeWithReason(episodeId, 'manual')\n  }\n\n  /**\n   * Immediately cancels the current run, then either closes without handoff or\n   * opens a compacted handoff Episode. Channel facts remain durable and future\n   * admissions wait behind this lane boundary.\n   */\n  async resetEpisode(episodeId: EpisodeId, mode: ContextResetMode, guard?: () => void): Promise<ContextResetResult> {\n    const initial = this.#runtimeRepository.getEpisode(episodeId)\n    if (!initial) throw new Error(`Unknown Episode: ${episodeId}`)\n    return this.#withLane(initial.channelId, initial.agentId, async () => {\n      guard?.()\n      const episode = this.#runtimeRepository.getEpisode(episodeId)\n      if (!episode || episode.status !== 'active' || !episode.dshSessionId) {\n        throw new Error(`Episode is not active: ${episodeId}`)\n      }\n      const binding = this.#coreRepository.getBinding(episode.channelId)\n      if (!binding || binding.agentId !== episode.agentId) throw new Error('Episode Binding no longer exists.')\n      const anchorId = episode.lastAdmittedEventId ?? episode.openedAtEventId\n      const anchor = this.#coreRepository.getChannelEvent(anchorId)\n      if (!anchor) throw new Error(`Episode anchor Event no longer exists: ${anchorId}`)\n      const reason = mode === 'clear' ? 'context-cleared' : 'context-compacted'\n\n      this.#feedback.markEndReason(episode.id, 'cancelled')\n      await this.#sessionDriver.cancelSession(episode.dshSessionId, reason)\n      await this.#feedback.cleanupEpisodeFeedback(episode.id)\n      if (mode === 'clear') {\n        return {\n          mode,\n          closedEpisode: this.#runtimeRepository.closeEpisode(episode.id, reason, anchorId, this.#timestamp()),\n        }\n      }\n\n      const sourceEvents = [\n        ...new Map(\n          [\n            this.#coreRepository.getChannelEvent(episode.openedAtEventId),\n            episode.lastAdmittedEventId === undefined\n              ? undefined\n              : this.#coreRepository.getChannelEvent(episode.lastAdmittedEventId),\n          ]\n            .filter((sourceEvent): sourceEvent is ChannelEventRecord => sourceEvent !== undefined)\n            .map((sourceEvent) => [sourceEvent.id, sourceEvent]),\n        ).values(),\n      ]\n      const recentEvents = this.#runtimeRepository.listAdmittedEvents(episode.id, HANDOFF_RECENT_EVENT_LIMIT)\n      const previousHandoff = this.#runtimeRepository.getEpisodeHandoffTo(episode.id)\n      const handoffCreatedAt = this.#timestamp()\n      const previousRevision = this.#coreRepository.getAgentRevision(episode.agentRevisionId)\n      if (!previousRevision) throw new Error(`Episode Agent Revision no longer exists: ${episode.agentRevisionId}`)\n      let summary = deterministicHandoffFallback(episode, previousRevision, sourceEvents)\n      try {\n        summary = await this.#sessionDriver.createHandoffSummary({\n          dshSessionId: episode.dshSessi