ventHistory, sessionEvents } from './session-event-history.js'\nimport { mountRequestTiming } from './request-timing.js'\nimport { NekroNxtSessionWorkingDirectory } from './session-working-directory.js'\nimport { mountCodeRunRuntime } from './code-run.js'\nimport {\n  COMMUNITY_FEEDBACK_PROMPT,\n  FeedbackTurnOrigin,\n  feedbackAdmissionOrigin,\n  mountFeedbackTools,\n} from './feedback-tools.js'\nimport type { CommunityFeedbackService } from './community-feedback.js'\nimport { createWorkspaceFileSystem } from './workspace-file-system.js'\nimport { mountWorkspaceFileTools } from './workspace-file-tools.js'\nimport type { ActiveAddonProgram } from './addons.js'\nimport {\n  commandCredentialEnvironment,\n  commandCredentialPrompt,\n  createEnvForwardingExecutor,\n  createPwshEnvForwardingExecutor,\n  type CommandCredentialSources,\n} from './command-account-env.js'\nimport {\n  confinedGitEnvironment,\n  createConfinedSandboxProvider,\n  dataRootCommandConfinement,\n  type CommandConfinement,\n} from './command-confinement.js'\nimport {\n  commandHostPrompt,\n  commandToolEnvironment,\n  detectCommandHost,\n  toolsRootOf,\n  type CommandHost,\n} from './command-host.js'\nimport { readFile, realpath, stat } from 'node:fs/promises'\nimport { createReadStream } from 'node:fs'\nimport type { LlmProviderRemovalCoordinator, RemovalImpact } from './llm-provider-removal.js'\nimport type { LlmProviderTestResults } from './llm-provider-test-results.js'\nimport { Context, Service } from '@deepseek-ai/cordis'\nimport { AgentRegistry, type Agent, type AgentOptions, type AgentStatus } from '@deepseek-ai/dsh-agent'\nimport '@deepseek-ai/dsh-agent-loop'\nimport { type ImageAttachmentRef } from '@deepseek-ai/dsh-attachment'\nimport * as ImageOffload from '@deepseek-ai/dsh-compaction-image-offload'\nimport ToolResultPruner from '@deepseek-ai/dsh-compaction-tool-result-pruner'\nimport {\n  type CordisDynamicRunMode,\n  type CordisErrorDetails,\n  type DynamicCordisClientSource,\n  type