ter from '@deepseek-ai/dsh-token-meter'\nimport * as BashTool from '@deepseek-ai/dsh-tool-bash'\nimport * as ToolCallTimeoutPolicy from '@deepseek-ai/dsh-tool-call-timeout-policy'\nimport * as CordisTool from '@deepseek-ai/dsh-tool-cordis'\nimport * as FsTool from '@deepseek-ai/dsh-tool-fs'\nimport * as PwshTool from '@deepseek-ai/dsh-tool-pwsh'\nimport * as SkillTool from '@deepseek-ai/dsh-tool-skill'\nimport * as ToolWeb from '@deepseek-ai/dsh-tool-web'\nimport { defineTool, ToolArgsError, ToolRuntime } from '@deepseek-ai/dsh-tools'\nimport WebRuntime from '@deepseek-ai/dsh-web'\nimport {\n  type AgentSessionDriver,\n  type ChannelHistoryEntry,\n  type ChannelHistoryFilter,\n  type ChannelHistoryRepository,\n  type ChannelInteractionResult,\n  type ChannelRuntime,\n  type EpisodeCloseReason,\n  type SendMessageInput,\n  type SendMessageResult,\n  UnrecoverableSessionError,\n  SessionModelUnavailableError,\n} from '@nekro-nxt/channel-runtime'\nimport {\n  type ExtensionCapabilities,\n  type ExtensionId,\n  AdmissionIdSchema,\n  AssetIdSchema,\n  ChannelEventIdSchema,\n  DshPluginEntryIdSchema,\n  ChannelMemberIdSchema,\n  DEFAULT_CHANNEL_CONTEXT_POLICY,\n  CommandDefinitionSchema,\n  ExtensionLayeredConfigSchema,\n  HostPageContributionSchema,\n  ExtensionPermissionsSchema,\n  JsonValueSchema,\n  LogicalMessageIdSchema,\n  messagePartsSearchText,\n  parseJsonValue,\n  parseMessageParts,\n  type AdmissionId,\n  type AgentId,\n  type AgentRevisionId,\n  type AssetId,\n  type AuthoringTaskId,\n  type ChannelContextPolicy,\n  type ChannelEventId,\n  type ChannelId,\n  type ChannelMemberId,\n  type ConnectionId,\n  type DshCredentialView,\n  type DshPluginActivationRecord,\n  type DshPluginCatalogEntry,\n  type DshPluginEntryId,\n  type DshPluginPackageId,\n  type DshSettingsNamespaceView,\n  type DshSettingsPathOperation,\n  type EpisodeId,\n  DEFAULT_SUB_CONVERSATION_RETENTION,\n  type SubConversationRetention,\n  type JsonValue,\n  type ScheduledTask,\n  type Logical