erverName, { state: 'connected', toolCount: outcome.toolCount })\n                  return\n                }\n                const message =\n                  'error' in outcome\n                    ? outcome.error instanceof Error\n                      ? outcome.error.message\n                      : String(outcome.error)\n                    : '没有可用的工具：连接失败或服务没有提供工具'\n                status(serverName, { state: 'unavailable', message })\n                console.warn(`[nekro-nxt] MCP 服务 ${serverName}（${described.displayName}）：${message}`)\n              })\n            },\n          },\n    )\n    // Third-party plugins allowed to submit images put them in the channel of the tool call that runs.\n    trackToolCallSessions(context)\n    this.#dshPluginLifecycle =\n      options.dshPlugins === undefined\n        ? undefined\n        : new DshPluginLifecycleCoordinator({\n            ...(options.logs === undefined ? {} : { logs: options.logs }),\n            repository: options.dshPlugins.repository,\n            rootContext: context,\n            serviceAccess: dshPluginServiceAccess,\n            isolatedServices: DSH_PLUGIN_ISOLATED_SERVICE_KEYS,\n            imageSubmission: {\n              attachments: channelImageSubmission({\n                store: () => requireNekroAssetAttachmentStore(this.#context.attachments),\n                channelOf: (sessionId) => this.#sessions.get(sessionId)?.channelId,\n                assets: this.#assets,\n                assetService: this.#assetService,\n              }),\n            },\n            resolveModule: options.dshPlugins.resolveModule,\n            listAgentSessions: (agentId) =>\n              [...this.#sessions.handles()]\n                .filter(([sessionId]) => this.#sessions.get(sessionId)?.revision.agentId === agentId)\n                .map(([sessionId, handle]) => ({\n                  sessionId,\n                  context: handle.agent.ctx,\n                  waitUntilSafe: () => handle.agent.whenIdle(),\n                })),\n          })\n    const compaction = context.compaction\n    if (!(compaction instanceof NekroNxtCompactionEngine)) {\n      throw new Error('NekroNxt visual restoration requires its public DSH compaction wrapper.')\n    }\n    compaction.setVisualRestore((result, agent) =>\n      this.#imageContext.restoreVisualContext(agent, String(result.compactionId)),\n    )\n    this.#mountModelFallback(context)\n    compaction.setModelChoice((agent) => {\n      const revision = this.#sessions.get(String(agent.id))?.revision\n      if (!revision) return undefined\n      const model = this.#compactionModel('inSession', revision)\n      return {\n        provider: model.provider,\n        model: model.model,\n        ...(model.reasoningEffort === undefined ? {} : { reasoningEffort: model.reasoningEffort }),\n      }\n    })\n    compaction.setThresholdChoice((agent, contextWindow) =>\n      this.compactionThresholdRatio(String(agent.id), contextWindow),\n    )\n    // A `/threshold` override lasts until the conversation next compacts.\n    compaction.setCompactedListener((agent) => this.#thresholdOverrides.set(String(agent.id), undefined))\n  }\n\n  static async create(options: DshHostRuntimeOptions): Promise<DshHostRuntime> {\n    assertHostDshPackageVersions()\n    if (!path.isAbsolute(options.sessionDatabasePath)) {\n      throw new TypeError('DSH Session database path must be absolute.')\n    }\n    if (options.developmentWorkspaceRoot !== undefined && !path.isAbsolute(options.developmentWorkspaceRoot)) {\n      throw new TypeError('Development workspace root must be absolute when configured.')\n    }\n    if ((options.llmSettingsPath === undefined) !== (options.llmCredentialPath === undefined)) {\n      throw new TypeError('DSH LLM settings and credential paths must be configured together.')\n    }\n    if (\n      (options.llmSettingsPath !== undefined && !path.isAbsolute(options.llmSettingsPath)) ||\n      (options.llmCredentialPath !== undefined && !path.isAbsolute(options.llmCredentialPath))\n    ) {\n      throw new TypeError('DSH LLM settings and credential paths must be absolute.')\n    }\n    const context = new Context()\n    // Filled once the runtime exists; until then failures log without a session scope.\n    let scopeOfSession: ((sessionId: string) => HostLogScope | undefined) | undefined\n    const llmRuntime =\n      options.logs === undefined\n        ? LlmRuntime\n        : diagnosedLlmRuntime({ logs: options.logs, scopeOf: (sessionId) => scopeOfSession?.(sessionId) })\n    try {\n      if (options.logs) {\n        for (const [plugin, name] of [\n          [llmRuntime, 'llm'],\n          [SessionStore, 'session'],\n          [ToolRuntime, 'tools'],\n          [AgentRegistry, 'agent'],\n          [SkillRegistry, 'skill'],\n          [SystemPrompt, 'system-prompt'],\n          [TokenMeter, 'token-meter'],\n          [LlmRetry, 'llm-retry'],\n          [ToolCallTimeoutPolicy, 'tool-call-timeout-policy'],\n          [WebRuntime, 'web'],\n          [SubagentSpawnInProcess, 'subagent-spawn-in-process'],\n          [SessionStats, 'session-stats'],\n          [DeepSeekLlmApiExtensionRegistry, 'deepseek-llm-api-extensions'],\n          [SessionCheckpointPolicy, 'session-checkpoint-policy'],\n          [ToolResultPruner, 'compaction-tool-result-pruner'],\n          [ImageOffload, 'compaction-image-offload'],\n        ] as const)\n          registerLogModule(plugin, {\n            kind: 'dsh-plugin',\n            id: `plugin:@deepseek-ai/dsh-${name}`,\n            name: `DSH · ${name}`,\n            version: DEEPSEEK_HARNESS_VERSION,\n          })\n        attachCordisLogs(context, options.logs)\n      }\n      await context.plugin(NekroAssetAttachmentStore, {\n        assets: options.assets,\n        assetService: options.assetService,\n        requestImageRoot: path.join(path.dirname(options.sessionDatabasePath), 'dsh', 'request-images'),\n      })\n      const secrets = options.secrets ?? new SecretRegistry()\n      const observeSecret = (value: string): void => {\n        secrets.register(value)\n        options.logs?.registerSecret?.(value)\n      }\n      await prepareDshHostProfile(context, {\n        observeSecret,\n        ...(options.logs === undefined ? {} : { logs: options.logs }),\n        ...(options.llmSettingsPath === undefined ? {} : { settingsPath: options.llmSettingsPath }),\n        ...(options.llmCredentialPath === undefined ? {} : { credentialPath: options.llmCredentialPath }),\n      })\n      if (options.llmCredentialPath !== undefined)\n        await preloadCredentialDocument(options.llmCredentialPath, observeSecret)\n      // DSH sign-in flows; subscription sign-in uses one when it offers a browser login for the provider.\n      if (options.llmCredentialPath !== undefined) await context.plugin(AuthorizationService)\n      await context.plugin(llmRuntime)\n      await context.plugin(DeepSeekLlmApiExtensionRegistry)\n      await options.configureLlm?.(context)\n      const conversationScripts = new ConversationScriptModel()\n      context.llm.registerAdapter([CONVERSATION_SCRIPT_PROVIDER], conversationScripts)\n      await context.plugin(SessionStore)\n      await context.plugin(NekroJsonlSessionPersistence, {\n        root: path.join(path.dirname(options.sessionDatabasePath), 'dsh', 'sessions'),\n      })\n      mountSessionEventHistory(context)\n      mountRequestTiming(\n        context,\n        options.logs === undefined\n          ? undefined\n          : { logs: options.logs, scopeOf: (sessionId) => scopeOfSession?.(sessionId) },\n      )\n      context.on('agent/created', async ({ agent }) => {\n        await restoreShutdownInbox(\n          path.join(path.dirname(options.sessionDatabasePath), 'dsh', 'shutdown-inbox'),\n          context,\n          agent,\n        )\n        return undefined\n      })\n      await context.plugin(SessionProjectionRegistry)\n      await context.plugin(SqliteSessionQueryEngine, { path: ':memory:', openAt: 'never' })\n      await context.plugin(SessionStats)\n      // The persona introduces the agent; DSH's generic \"AI agent\" opening would contradict it.\n      await context.plugin(SystemPrompt, { personaPrefix: '', includeHarnessIdentity: false })\n      await context.plugin(ToolRuntime, { mode: 'native' })\n      await context.plugin(SkillRegistry)\n      await context.plugin(AgentRegistry)\n      await context.plugin(NekroNxtAgentScopeInheritance)\n      await context.plugin(NekroNxtSessionWorkingDirectory, {\n        defaultDirectory: path.join(path.dirname(options.sessionDatabasePath), 'dsh'),\n      })\n      registerDshHostProfileEntry(context, {\n        id: 'subagent',\n        name: '@deepseek-ai/dsh-subagent',\n        config: { maxDepth: 1, maxActiveSubagents: 8 },\n        required: true,\n      })\n      await context.plugin(TokenMeter)\n      await context.plugin(ToolResultPruner, {\n        thresholdChars: 8192,\n        headChars: 4096,\n        tailChars: 1024,\n      })\n      // A route over its image budget asks for the oldest images to be replaced by placeholders and the request retried;\n      // without this the turn ends with that error and every later turn of the session hits it again.\n      await context.plugin(ImageOffload)\n      await context.plugin(NekroNxtCompactionEngine, { auto: true })\n      registerDshHostProfileEntry(context, {\n        id: 'agent-loop',\n        name: '@deepseek-ai/dsh-agent-loop',\n        config: { agents: [] },\n        required: true,\n      })\n      const channelReplyGuard = mountChannelReplyGuard(context)\n      await context.plugin(LlmRetry)\n      // The model now and then streams a tool call whose arguments are not valid JSON. The request itself was fine,\n      // so retrying the step at once usually recovers instead of leaving the channel without a reply.\n      const malformedRetries = new Map<string, number>()\n      context.on('agent/request-error', async (payload, next) => {\n        if (payload.failure.code !== 'MALFORMED_RESPONSE' || payload.signal.aborted) return next()\n        const key = `${payload.agent.id}:${payload.turn}:${payload.step}`\n        const attempts = malformedRetries.get(key) ?? 0\n        if (attempts >= MALFORMED_RESPONSE_RETRIES) return next()\n        if (malformedRetries.size > 1024) malformedRetries.clear()\n        malformedRetries.set(key, attempts + 1)\n        return Promise.resolve({ kind: 'retry' as const })\n      })\n      await context.plugin(ToolCallTimeoutPolicy)\n      await context.plugin(QuotaLocalSpillStore, { root: spillRootOf(options.sessionDatabasePath) })\n      registerDshHostProfileEntry(context, {\n        id: 'spill-policy',\n        name: '@deepseek-ai/dsh-spill-policy',\n        config: { maxInlineTokens: 12_500 },\n        required: true,\n      })\n      await context.plugin(WebRuntime, { searchProvider: 'deepseek-official' })\n      registerDshHostProfileEntry(context, {\n        id: 'web-search-deepseek',\n        name: '@deepseek-ai/dsh-web-search-deepseek',\n        config: { apiKeyEnv: 'DEEPSEEK_API_KEY', maxTokens: 1024, maxUses: 2 },\n        required: true,\n      })\n      await context.plugin(SessionCheckpointPolicy)\n      await activateDshHostProfile(context)\n      // After the spill policy and the dispatch wrappers, so the ordering documented on the mount holds.\n      mountCredentialRedaction(context, {\n        secrets,\n        protectedPaths: [\n          ...(options.credentialPaths ?? []),\n          ...(options.llmCredentialPath === undefined ? [] : [options.llmCredentialPath]),\n        ],\n      })\n      // A command the sandbox stopped gets a plain explanation for the agent; a sandbox that cannot start at all is\n      // also logged for the administrator, at most every ten minutes (#96).\n      let sandboxLoggedAt = 0\n      mountSandboxHints(context, {\n        onUnavailable: (detail) => {\n          if (Date.now() - sandboxLoggedAt < 10 * 60 * 1000) return\n          sandboxLoggedAt = Date.now()\n          options.logs?.write({\n            level: 'warn',\n            message:\n              '命令沙箱没能启动，开了「运行命令」的智能体现在无法执行任何命令。可以改用「完整访问」，或检查数据目录所在的磁盘。',\n            source: { kind: 'system', id: 'command-sandbox', name: '命令沙箱' },\n            details: { detail },\n          })\n        },\n      })\n      await context.plugin(SubagentSpawnInProcess, { providerName: 'spawn' })\n      const runtime = new DshHostRuntime(context, { ...options, secrets }, channelReplyGuard, conversationScripts)\n      scopeOfSession = (sessionId) => {\n        const record = runtime.#sessions.get(sessionId)\n        return record === undefined\n          ? { sessionId }\n          : { agentId: record.revision.agentId, channelId: record.channelId, sessionId, episodeId: record.episodeId }\n      }\n      await runtime.#dshPluginLifecycle?.initialize()\n      return runtime\n    } catch (error) {\n      try {\n        await disposeDshPluginFiber(context, context.fiber)\n      } catch (disposeError) {\n        throw new AggregateError([error, disposeError], 'DSH Host 启动失败，且资源未完整静止。')\n      }\n      throw error\n    }\n  }\n  registerLlmAdapter(providers: string[], adapter: LlmAdapter): () => void {\n    this.#assertActive()\n    return this.#modelSettings.registerLlmAdapter(providers, adapter)\n  }\n\n  canRunAgent(agentId: AgentId): boolean {\n    return !this.#incompatibleAgents.has(agentId)\n  }\n\n  setAgentCompatibility(agentId: AgentId, compatible: boolean): void {\n    if (compatible) this.#incompatibleAgents.delete(agentId)\n    else this.#incompatibleAgents.add(agentId)\n  }\n\n  /**\n   * The model route and thinking level for a conversation. A level the model no longer offers (its list changed\n   * after the agent was saved) is left out, so the model's own default applies instead of the request failing.\n   */\n  async #agentOptions(revision: AgentRevisionRecord): Promise<AgentOptions> {\n    const { provider, model, reasoningEffort } = revision.model\n    if (reasoningEffort === undefined) return { provider, model }\n    const offered = await this.#context.llm\n      .resolveModelInfo(provider, model)\n      .then((info) => info.reasoning?.efforts.some((effort) => String(effort.id) === reasoningEffort) === true)\n      .catch(() => false)\n    return offered ? { provider, model, reasoningEffort: ReasoningEffortId(reasoningEffort) } : { provider, model }\n  }\n\n  async checkModelCompatibility(revision: AgentRevisionRecord): Promise<string | undefined> {\n    const diagnostics = getDshHostProfileDiagnostics(this.#context)\n    if (\n      diagnostics.some(\n        (item) =>\n          item.objectKind === 'model-provider' &&\n          (item.objectId === revision.model.provider || item.objectId === 'llm-pi-ai'),\n      )\n    ) {\n      return '模型供应商配置需要适配当前引擎。请修复设置后重试；原模型未被替换。'\n    }\n    try {\n      await this.#context.llm.resolveModelInfo(revision.model.provider, revision.model.model)\n      return undefined\n    } catch (error) {\n      const code = error instanceof Error && 'code' in error ? error.code : undefined\n      if (\n        typeof code === 'string' &&\n        [\n          'TRANSPORT',\n          'NETWORK',\n          'TIMEOUT',\n          'AUTH',\n          'RATE_LIMIT',\n          'SERVER',\n          'MISSING_CREDENTIAL',\n          'INVALID_CREDENTIAL',\n        ].includes(code)\n      )\n        return undefined\n      return '当前引擎无法解析此智能体的模型配置。请在模型设置中检查供应商和模型后重试。'\n    }\n  }\n\n  compatibilityDiagnostics() {\n    return [\n      ...getDshHostProfileDiagnostics(this.#context),\n      ...(this.#dshPluginLifecycle?.compatibilityDiagnostics() ?? []),\n    ]\n  }\n\n  async retryCompatibility(kind: 'model-provider' | 'dsh-plugin', objectId: string): Promise<void> {\n    const profileIssue = getDshHostProfileDiagnostics(this.#context).some(\n      (item) => item.objectKind === kind && item.objectId === objectId,\n    )\n    if (kind === 'model-provider' || profileIssue) {\n      await run