er.provider)) return provider\n          const status = await subscriptions.status(provider.provider)\n          if (!status.available) return provider\n          return {\n            ...provider,\n            ...(status.mode === 'subscription' && !subscriptions.hasModelSelection(provider.provider)\n              ? { models: [] }\n              : {}),\n            subscription: {\n              label: status.label,\n              active: status.mode === 'subscription',\n              accountLabel: status.accounts.find((account) => account.id === status.activeAccountId)?.label ?? null,\n            },\n          }\n        }),\n      ),\n    }\n  }\n\n  subscriptionStatus(provider: string): Promise<SubscriptionStatusView> {\n    this.#assertActive()\n    return this.#requireSubscriptions().status(this.#subscriptionProvider(provider))\n  }\n\n  /** Runs one account or sign-in action; the result is the provider's status after it. */\n  async subscriptionAction(\n    provider: string,\n    action:\n      | { readonly action: 'use-subscription'; readonly expectedRevision: number }\n      | { readonly action: 'login' | 'cancel' }\n      | { readonly action: 'answer'; readonly promptId: string; readonly value: string }\n      | { readonly action: 'activate' | 'remove'; readonly accountId: string }\n      | { readonly action: 'rename'; readonly accountId: string; readonly label: string },\n  ): Promise<{ readonly status: SubscriptionStatusView; readonly revocationConfirmed?: boolean }> {\n    this.#assertActive()\n    const subscriptions = this.#requireSubscriptions()\n    const id = this.#subscriptionProvider(provider)\n    let revocationConfirmed: boolean | undefined\n    switch (action.action) {\n      case 'use-subscription':\n        await subscriptions.useSubscription(id, action.expectedRevision)\n        break\n      case 'login':\n        await subscriptions.login(id)\n        break\n      case 'cancel':\n        subscriptions.cancel(id)\n        break\n      case 'answer':\n        subscriptions.answer(id, action.promptId, action.value)\n        break\n      case 'activate':\n        await subscriptions.activate(id, action.accountId)\n        break\n      case 'rename':\n        await subscriptions.rename(id, action.accountId, action.label)\n        break\n      case 'remove':\n        revocationConfirmed = (await subscriptions.remove(id, action.accountId)).revocationConfirmed\n    }\n    return {\n      status: await subscriptions.status(id),\n      ...(revocationConfirmed === undefined ? {} : { revocationConfirmed }),\n    }\n  }\n\n  onSubscriptionsChanged(listener: () => void): () => void {\n    this.#subscriptionListeners.add(listener)\n    return () => this.#subscriptionListeners.delete(listener)\n  }\n\n  #requireSubscriptions(): SubscriptionLogins {\n    if (!this.#subscriptions) throw new Error('这台主机没有凭据存储，不能登录模型套餐。')\n    return this.#subscriptions\n  }\n\n  #subscriptionProvider(provider: string): SubscriptionProvider {\n    if (!isSubscriptionProvider(provider)) throw new Error(`没有可以登录的套餐：${provider}`)\n    return provider\n  }\n\n  getWebSearchCapabilityStatus(): Promise<WebSearchCapabilityStatus> {\n    this.#assertActive()\n    return this.#modelSettings.getWebSearchCapabilityStatus()\n  }\n\n  listDshPlugins(): readonly DshPluginCatalogEntry[] {\n    this.#assertActive()\n    return this.#modelSettings.listDshPlugins()\n  }\n\n  activateInstalledDshPlugin(\n    input: Parameters<DshPluginLifecycleCoordinator['activate']>[0],\n  ): Promise<DshPluginActivationRecord> {\n    this.#assertActive()\n    if (!this.#dshPluginLifecycle) return Promise.reject(new Error('DSH 用户插件生命周期未配置。'))\n    return this.#dshPluginLifecycle.activate(input)\n  }\n\n  inspectInstalledDshPluginConfig(entryId: DshPluginEntryId) {\n    this.#assertActive()\n    if (!this.#dshPluginLifecycle) return Promise.reject(new Error('DSH 用户插件生命周期未配置。'))\n    return this.#dshPluginLifecycle.inspectConfig(entryId)\n  }\n\n  disableInstalledDshPlugin(entryId: DshPluginEntryId, targetKey: string): Promise<void> {\n    this.#assertActive()\n    if (!this.#dshPluginLifecycle) return Promise.reject(new Error('DSH 用户插件生命周期未配置。'))\n    return this.#dshPluginLifecycle.disable(entryId, targetKey)\n  }\n\n  disableInstalledDshPluginPackage(packageId: DshPluginPackageId): Promise<void> {\n    this.#assertActive()\n    if (!this.#dshPluginLifecycle) return Promise.reject(new Error('DSH 用户插件生命周期未配置。'))\n    return this.#dshPluginLifecycle.disablePackage(packageId)\n  }\n\n  /** Refuses when stored conversations contain content only these plugin entries can read back. */\n  assertInstalledDshPluginConversationsIndependent(\n    entryIds: readonly DshPluginEntryId[],\n    action: '关闭' | '移除',\n  ): Promise<void> {\n    this.#assertActive()\n    if (!this.#dshPluginLifecycle) return Promise.resolve()\n    return this.#dshPluginLifecycle.assertSessionIndependent(entryIds, action)\n  }\n\n  /** Whether third-party plugins of this package may submit images; undefined when this Host cannot offer it. */\n  dshPluginImageSubmission(packageName: string): boolean | undefined {\n    return this.#dshPluginLifecycle?.imageSubmissionAllowed(packageName)\n  }\n\n  setDshPluginImageSubmission(packageId: DshPluginPackageId, allowed: boolean): Promise<void> {\n    this.#assertActive()\n    if (!this.#dshPluginLifecycle) return Promise.reject(new Error('DSH 用户插件生命周期未配置。'))\n    return this.#dshPluginLifecycle.setImageSubmission(packageId, allowed)\n  }\n\n  installedDshPluginServiceView(\n    entryId: DshPluginEntryId,\n    targetKey?: string,\n  ): ReturnType<DshPluginLifecycleCoordinator['serviceView']> {\n    return this.#dshPluginLifecycle?.serviceView(entryId, targetKey) ?? {}\n  }\n  listDshSettings(): readonly DshSettingsNamespaceView[] {\n    this.#assertActive()\n    return this.#modelSettings.listDshSettings()\n  }\n\n  mutateDshSettings(\n    ns: string,\n    expectedRevision: number,\n    ops: readonly DshSettingsPathOperation[],\n  ): Promise<DshSettingsNamespaceView> {\n    this.#assertActive()\n    return runDshSettingsMaintenance(this.#context, async () => {\n      this.#assertActive()\n      return this.#modelSettings.mutateDshSettings(ns, expectedRevision, ops)\n    })\n  }\n\n  describeDshCredentials(refs: readonly string[]): Promise<Readonly<Record<string, DshCredentialView>>> {\n    this.#assertActive()\n    return this.#modelSettings.describeDshCredentials(refs)\n  }\n\n  setDshCredential(ref: string, value: string): Promise<DshCredentialView> {\n    this.#assertActive()\n    return this.#modelSettings.setDshCredential(ref, value)\n  }\n\n  unsetDshCredential(ref: string): Promise<DshCredentialView> {\n    this.#assertActive()\n    return this.#modelSettings.unsetDshCredential(ref)\n  }\n\n  onDshSettingsChanged(listener: (ns: string, revision: number) => void): () => void {\n    this.#assertActive()\n    return this.#modelSettings.onDshSettingsChanged(listener)\n  }\n\n  onDshCredentialChanged(listener: (ref: string) => void): () => void {\n    this.#assertActive()\n    return this.#modelSettings.onDshCredentialChanged(listener)\n  }\n\n  getLlmProviderRemovalImpact(provider: string): Promise<RemovalImpact> {\n    this.#assertActive()\n    return this.#modelSettings.getLlmProviderRemovalImpact(provider)\n  }\n\n  async removeLlmProvider(provider: string, expectedRevision: number): Promise<LlmProviderSettingsView> {\n    this.#assertActive()\n    return this.#withSubscriptions(await this.#modelSettings.removeLlmProvider(provider, expectedRevision))\n  }\n\n  async saveLlmProvider(input: SaveLlmProviderInput): Promise<LlmProviderSettingsView> {\n    this.#assertActive()\n    return this.#withSubscriptions(await this.#modelSettings.saveLlmProvider(input))\n  }\n\n  async restoreLlmProviderModels(provider: string, expectedRevision: number): Promise<LlmProviderSettingsView> {\n    this.#assertActive()\n    if (isSubscriptionProvider(provider) && this.#subscriptions?.mode(provider) === 'subscription') {\n      const models = await this.#subscriptions.discoverModels(provider)\n      if (models.length === 0) throw new Error('这个账号没有可用模型，请检查 ChatGPT 套餐后重试。')\n      return this.saveLlmProvider({ provider, expectedRevision, models })\n    }\n    return this.#withSubscriptions(await this.#modelSettings.restoreLlmProviderModels(provider, expectedRevision))\n  }\n\n  discoverLlmProviderModels(input: {\n    readonly provider?: string\n    readonly settingsNs?: string\n    readonly baseURL?: string\n    readonly api?: string\n    readonly apiKey?: string\n  }): Promise<readonly SaveLlmProviderModel[]> {\n    this.#assertActive()\n    const provider = input.provider\n    const saved = provider === undefined ? undefined : this.#subscriptions?.savedProfile(provider)\n    const draft =\n      input.apiKey !== undefined ||\n      (input.baseURL !== undefined && input.baseURL !== saved?.['baseURL']) ||\n      (input.api !== undefined && input.api !== saved?.['api'])\n    if (provider !== undefined && isSubscriptionProvider(provider) && !draft) {\n      // A signed-in route lists what the account may use; the catalog lists every model the provider has.\n      if (this.#subscriptions?.mode(provider) === 'subscription') return this.#subscriptions.discoverModels(provider)\n    }\n    return this.#modelSettings.discoverLlmProviderModels(input)\n  }\n\n  testLlmProvider(input: TestLlmProviderInput): Promise<{ readonly provider: string; readonly model: string }> {\n    this.#assertActive()\n    const signedIn =\n      isSubscriptionProvider(input.provider) && this.#subscriptions?.mode(input.provider) === 'subscription'\n    // The page sends the saved address and protocol back with every test; only a different value is a draft.\n    const saved = signedIn ? this.#subscriptions?.savedProfile(input.provider) : undefined\n    const changesRoute =\n      input.apiKey !== undefined ||\n      (input.baseURL !== undefined && input.baseURL !== saved?.['baseURL']) ||\n      (input.api !== undefined && input.api !== saved?.['api'])\n    if (signedIn && !changesRoute) {\n      // A draft is tested in a throwaway runtime that holds no sign-in; the saved route carries the account.\n      return this.#modelSettings.testLlmProvider({ provider: input.provider, model: input.model })\n    }\n    return this.#modelSettings.testLlmProvider(input)\n  }\n\n  async createSession(input: Parameters<AgentSessionDriver['createSession']>[0]): Promise<string> {\n    this.#assertActive()\n    const sessionId = SessionId(`nxt-${input.episodeId}`)\n    if (this.#context.agents.get(sessionId)) return sessionId\n    const revision = this.#resolveAgentRevision(input.agentRevisionId)\n    if (!revision || revision.id !== input.agentRevisionId || revision.agentId !== input.agentId) {\n      throw new Error(`Cannot resolve the pinned Agent Revision: ${input.agentRevisionId}`)\n    }\n    const channelContext = resolveSessionChannelContext(this.#history, input.channelId, input.episodeId)\n    const hasDevelopmentCapabilities = revision.capabilities.developmentShell || revision.capabilities.fileTools\n    const developmentWorkspace =\n      hasDevelopmentCapabilities && this.#developmentWorkspaceRoot !== undefined\n        ? resolveAgentWorkspace(this.#developmentWorkspaceRoot, revision.agentId)\n        : undefined\n    if (developmentWorkspace !== undefined) {\n      await mkdir(developmentWorkspace, { recursive: true, mode: 0o700 })\n    }\n    const modelInfo = await this.#context.llm\n      .resolveModelInfo(revision.model.provider, revision.model.model)\n      .catch((cause: unknown) => {\n        if (cause instanceof Error && 'code' in cause && cause.code === 'NO_ADAPTER')\n          throw new SessionModelUnavailableError(`模型供应商 ${revision.model.provider} 尚未启用。`, { cause })\n        throw cause\n      })\n    const supportsImage = modelInfo.inputModalities?.includes('image') === true\n    const requestedAuxiliary = revision.imagePolicy.textModel\n    let auxiliary: