    {
      "path": "apps/server/src/workspace-projections.ts",
      "content": "import { optionalProjection, unavailableImageDiagnostics } from './auxiliary-projections.js'\nimport {\n  activityDurationMs,\n  AgentIdSchema,\n  AgentRevisionIdSchema,\n  CHANNEL_UNREAD_COUNT_CAP,\n  ChannelIdSchema,\n  HostApiContracts,\n  OutboundIntentIdSchema,\n  type AgentId,\n  type AgentRevisionHistory,\n  type AgentRevisionId,\n  type AttentionItem,\n  type ChannelActivitySeries,\n  type ChannelActivitySummary,\n  type ChannelId,\n  type ChannelPendingContext,\n  type ConnectionId,\n  type HostApiRequest,\n  type HostApiResponse,\n  type HostSseEvent,\n  type MessagePart,\n  type OutboundIntentId,\n} from '@nekro-nxt/contracts'\nimport { ChannelStopConflictError, isAdminConsoleOutbound } from '@nekro-nxt/channel-runtime'\nimport type { ChannelEventRecord } from '@nekro-nxt/core'\nimport { OutboundResolutionError, type ChannelReadPosition } from '@nekro-nxt/storage-sqlite'\nimport { createHash, randomUUID } from 'node:crypto'\nimport { readFile } from 'node:fs/promises'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { NekroRuntime } from './bootstrap.js'\nimport { viewerKeyFromRequest } from './viewer.js'\nimport { assembleChannelRuntime } from './host-queries.js'\nimport {\n  readBinaryBody,\n  readJsonBody,\n  writeContractJson,\n  writeError,\n  type HostRouteContext,\n} from './host-route-support.js'\n\nconst PREVIEW_MAX = 80\nconst ATTENTION_DELIVERY_WINDOW_MS = 7 * 24 * 60 * 60 * 1000\nconst ATTENTION_DELIVERY_LIMIT = 50\nconst ATTENTION_DISMISSAL_RETENTION_MS = 30 * 24 * 60 * 60 * 1000\n/** Dismissal fingerprints of causes kept quiet until they recover, next to the item fingerprints. */\nconst QUIET_CAUSE_PREFIX = 'cause:'\n\n/**\n * Whether a cause is still there. A connection recovers when it is connected again, whatever deliveries it failed\n * meanwhile; an agent recovers once none of its problems remain.\n */\nexport const causeOngoing = (key: string, items: readonly AttentionItem[]): boolean =>\n  items.some(\n    (item) => item.cause?.key === key && (!key.startsWith('connection:') || item.kind === 'connection-unhealthy'),\n  )\nconst ATTENTION_RECHECK_DEBOUNCE_MS = 400\nconst ATTENTION_SAFETY_INTERVAL_MS = 30_000\nconst AVATAR_MAX_BYTES = 2 * 1024 * 1024\nconst AVATAR_MEDIA_TYPES = new Set(['image/png', 'image/jpeg', 'image/webp', 'image/gif'])\n\nconst truncate = (value: string, max: number): string => {\n  const characters = [...value]\n  return characters.length <= max ? value : `${characters.slice(0, max - 1).join('')}…`\n}\n\nconst channelDisplayName = (runtime: NekroRuntime, channelId: ChannelId): string => {\n  const channel = runtime.repository.getChannel(channelId)\n  if (channel === undefined) return '已删除的频道'\n  return (\n    channel.displayName ??\n    (channel.kind === 'group' ? '未命名群聊' : channel.kind === 'direct' ? '未命名私聊' : '未命名内置频道')\n  )\n}\n\nconst agentDisplayName = (runtime: NekroRuntime, agentId: AgentId): string =>\n  runtime.repository.getAgent(agentId)?.revision.displayName ?? '已删除的智能体'\n\n/** One line of safe plain text for list previews; media become bracketed labels. */\nexport const previewMessageParts = (runtime: NekroRuntime, parts: readonly MessagePart[]): string => {\n  const text = parts\n    .map((part) => {\n      switch (part.type) {\n        case 'text':\n          return part.text\n        case 'mention':\n          return `@${runtime.repository.getChannelMember(part.memberId)?.displayName ?? '成员'}`\n        case 'image':\n          return part.sticker ? '[表情包]' : '[图片]'\n        case 'file':\n          return part.name === undefined ? '[文件]' : `[文件] ${part.name}`\n        case 'audio':\n          return '[语音]'\n        case 'quote':\n          return ''\n        case 'rich':\n          return part.summary\n      }\n    })\n    .join(' ')\n    .replaceAll(/\\s+/gu, ' ')\n    .trim()\n  return truncate(text, PREVIEW_MAX)\n}\n\nconst memberName = (runtime: NekroRuntime, event: ChannelEventRecord): string =>\n  (event.senderMemberId === undefined\n    ? undefined\n    : runtime.repository.getChannelMember(event.senderMemberId)?.displayName) ?? '成员'\n\ntype ActivityQuery = ReturnType<typeof HostApiContracts.getChannelActivity.parseParams>\n\n/**\n * Client workspace read models over durable facts: per-viewer unread positions, activity series, the attention\n * queue and administrator delivery resolutions. None of them introduces a second source of channel truth.\n */\nexport class WorkspaceProjections {\n  readonly #runtime: NekroRuntime\n  readonly #broadcast: (event: HostSseEvent) => void\n  readonly #now: () => number\n  readonly #unhealthySince = new Map<string, { readonly state: string; readonly since: number }>()\n  #attentionRevision: string | undefined\n  #attentionTimer: ReturnType<typeof setTimeout> | undefined\n  #attentionCheck: Promise<void> | undefined\n  #attentionDirty = false\n  #logFailureAt: number | undefined\n  readonly #safetyTimer: ReturnType<typeof setInterval>\n  readonly #unsubscribeFeedback: () => void\n  readonly #unsubscribeSync: () => void\n  #disposed = false\n\n  constructor(runtime: NekroRuntime, broadcast: (event: HostSseEvent) => void, now: () => number = Date.now) {\n    this.#runtime = runtime\n    this.#broadcast = broadcast\n    this.#now = now\n    this.#unsubscribeFeedback = runtime.feedback.subscribe(() => this.scheduleAttentionCheck())\n    this.#unsubscribeSync = runtime.communitySync.subscribe(() => this.scheduleAttentionCheck())\n    this.#safetyTimer = setInterval(() => this.scheduleAttentionCheck(), ATTENTION_SAFETY_INTERVAL_MS)\n    this.#safetyTimer.unref?.()\n  }\n\n  dispose(): void {\n    this.#disposed = true\n    this.#unsubscribeFeedback()\n    this.#unsubscribeSync()\n    clearInterval(this.#safetyTimer)\n    if (this.#attentionTimer !== undefined) clearTimeout(this.#attentionTimer)\n  }\n\n  // ---------------------------------------------------------------- channel activity\n\n  /** Activity for every listed Channel from one viewer's perspective. */\n  channelActivity(viewerKey: string, channelIds: readonly ChannelId[]): ReadonlyMap<ChannelId, ChannelActivitySummary> {\n    const projections = this.#runtime.repository.projections\n    const baseline = projections.ensureReadViewer(viewerKey, this.#now())\n    const positions = projections.listChannelReadPositions(viewerKey)\n    return new Map(\n      channelIds.map((channelId) => [\n        channelId,\n        this.#summarize(channelId, positions.get(channelId) ?? { readAt: baseline, readSourceId: '' }),\n      ]),\n    )\n  }\n\n  #summarize(channelId: ChannelId, position: ChannelReadPosition): ChannelActivitySummary {\n    const projections = this.#runtime.repository.projections\n    const inbound = projections.getLatestVisibleInbound(channelId)\n    const outbound = projections.getLatestOutbound(channelId)\n    const unread = projections.countUnreadMemberMessages(channelId, position, CHANNEL_UNREAD_COUNT_CAP)\n    let lastMessage: ChannelActivitySummary['lastMessage']\n    if (inbound !== undefined && (outbound === undefined || inbound.receivedAt >= outbound.createdAt)) {\n      lastMessage = {\n        role: inbound.activityKey === undefined ? 'member' : 'system',\n        author: truncate(inbound.activityKey === undefined ? memberName(this.#runtime, inbound) : '频道活动', 120),\n        preview: previewMessageParts(this.#runtime, inbound.parts),\n        occurredAt: inbound.receivedAt,\n      }\n    } else if (outbound !== undefined) {\n      const admin = isAdminConsoleOutbound(outbound.sourceTurnId)\n      lastMessage = {\n        role: admin ? 'admin' : 'agent',\n        author: truncate(\n          admin\n            ? '管理员'\n            : outbound.agentRevisionId === undefined\n              ? '命令结果'\n              : (this.#runtime.repository.getAgentRevision(outbound.agentRevisionId)?.displayName ?? '智能体'),\n          120,\n        ),\n        preview: previewMessageParts(this.#runtime, outbound.parts),\n        occurredAt: outbound.createdAt,\n      }\n    }\n    return {\n      ...(lastMessage === undefined ? {} : { lastActivityAt: lastMessage.occurredAt, lastMessage }),\n      unreadCount: unread.count,\n      unreadCapped: unread.capped,\n    }\n  }\n\n  markRead(\n    viewerKey: string,\n    channelId: ChannelId,\n    upTo?: { readonly occurredAt: number; readonly sourceId: string },\n  ): ChannelActivitySummary {\n    if (this.#runtime.repository.getChannel(channelId) === undefined) throw new NotFoundError('频道不存在或已被删除。')\n    const projections = this.#runtime.repository.projections\n    projections.ensureReadViewer(viewerKey, this.#now())\n    let target = upTo === undefined ? undefined : { readAt: upTo.occurredAt, readSourceId: upTo.sourceId }\n    if (target === undefined) {\n      const latest = projections.getLatestMemberMessage(channelId)\n      target =\n        latest === undefined\n          ? { readAt: this.#now(), readSourceId: '' }\n          : { readAt: latest.receivedAt, readSourceId: latest.id }\n    }\n    const position = projections.advanceChannelReadPosition(viewerKey, channelId, target, this.#now())\n    return this.#summarize(channelId, position)\n  }\n\n  // ---------------------------------------------------------------- runtime controls\n\n  pending(channelId: ChannelId): ChannelPendingContext {\n    if (this.#runtime.repository.getChannel(channelId) === undefined) throw new NotFoundError('频道不存在或已被删除。')\n    const context = this.#runtime.channels.listPendingContext(channelId)\n    return {\n      channelId,\n      ...(context.episodeId === undefined ? {} : { episodeId: context.episodeId }),\n      items: context.items.map((item) => ({\n        admissionId: item.admissionId,\n        target: item.target,\n        events: item.events.map((event) => ({\n          eventId: event.id,\n          author: truncate(memberName(this.#runtime, event), 120),\n          preview: previewMessageParts(this.#runtime, event.parts),\n          receivedAt: event.receivedAt,\n        })),\n      })),\n    }\n  }\n\n  async stop(\n    channelId: ChannelId,\n    expectedEpisodeId?: Parameters<NekroRuntime['channels']['stopCurrentTurn']>[1],\n  ): Promise<HostApiResponse<'stopChannelTask'>> {\n    if (this.#runtime.repository.getChannel(channelId) === undefined) throw new NotFoundError('频道不存在或已被删除。')\n    const result = await this.#runtime.channels.stopCurrentTurn(channelId, expectedEpisodeId)\n    this.scheduleAttentionCheck()\n    return {\n      result: result.result,\n      ...(result.episodeId === undefined ? {} : { episodeId: result.episodeId }),\n      retainedPending: result.retainedPending,\n    }\n  }\n\n  async resolveOutbound(\n    outboundId: OutboundIntentId,\n    action: 'retry' | 'confirm-delivered',\n    viewerKey: string,\n  ): Promise<HostApiResponse<'resolveOutbound'>> {\n    if (action === 'retry') this.#runtime.channels.assertOutboundDispatchable(outboundId)\n    const resolution = this.#runtime.repository.projections.resolveOutbound({\n      id: `ores_${randomUUID()}`,\n      intentId: outboundId,\n      action,\n      viewerKey,\n      now: this.#now(),\n    })\n    if (action === 'retry') await this.#runtime.channels.redispatchOutbound(outboundId)\n    else this.#runtime.channels.publishOutboundFact(outboundId)\n    this.scheduleAttentionCheck()\n    return {\n      outboundId,\n      action,\n      deliveryState: this.#runtime.repository.getOutbound(outboundId).intent.state,\n      resolvedAt: resolution.createdAt,\n    }\n  }\n\n  activity(query: ActivityQuery): ChannelActivitySeries {\n    const windowMs = activityDurationMs(query.window)\n    const bucketMs = activityDurationMs(query.bucket)\n    const bucketCount = Math.ceil(windowMs / bucketMs)\n    // Align to bucket boundaries so repeated polls share buckets; the last bucket contains \"now\".\n    const to = (Math.floor(this.#now() / bucketMs) + 1) * bucketMs\n    const from = to - bucketCount * bucketMs\n    const live = new Set(\n      this.#runtime.core\n        .listConnections()\n        .flatMap((connection) => this.#runtime.core.listChannelsByConnection(connection.id).map(({ id }) => id)),\n    )\n    const counts = this.#runtime.repository.projections.countChannelActivity(from, to, bucketMs)\n    return {\n      from,\n      to,\n      bucketMs,\n      channels: [...counts]\n        .filter(([channelId]) => live.has(channelId))\n        .map(([channelId, buckets]) => {\n          const series = Array.from({ length: bucketCount }, (_, index) => buckets.get(index) ?? 0)\n          return { channelId, counts: series, total: series.reduce((sum, value) => sum + value, 0) }\n        })\n        .sort((left, right) => right.total - left.total || left.channelId.localeCompare(right.channelId)),\n    }\n  }\n\n  // ---------------------------------------------------------------- agent revision history\n\n  revisionHistory(agentId: AgentId): AgentRevisionHistory {\n    const agent = this.#runtime.repository.getAgent(agentId)\n    if (agent === undefined) throw new NotFoundError('智能体不存在或已被删除。')\n    const currentRevisionId = agent.definition.currentRevisionId\n    return {\n      agentId,\n      currentRevisionId,\n      revisions: this.#runtime.core\n        .listAgentRevisionHistory(agentId)\n        .map(({ revision, changedFields }) => ({\n          id: revision.id,\n          revision: revision.revision,\n          createdAt: revision.createdAt,\n          displayName: revision.displayName,\n          model: { provider: revision.model.provider, model: revision.model.model },\n          changedFields: [...changedFields],\n          current: revision.id === currentRevisionId,\n        }))\n        .reverse(),\n    }\n  }\n\n  restoreRevision(agentId: AgentId, revisionId: AgentRevisionId, expectedCurrentRevisionId: AgentRevisionId) {\n    const agent = this.#runtime.repository.getAgent(agentId)\n    if (agent === undefined) throw new NotFoundError('智能体不存在或已被删除。')\n    if (agent.definition.currentRevisionId !== expectedCurrentRevisionId) {\n      throw new RevisionConflictError('智能体配置已在其他位置更新，请刷新后重试。')\n    }\n    const target = this.#runtime.repository.getAgentRevision(revisionId)\n    if (target === undefined || target.agentId !== agentId) throw new NotFoundError('这个版本不存在。')\n    return this.#runtime.core.restoreAgentRevision(agentId, revisionId, expectedCurrentRevisionId).revision.id\n  }\n\n  // ---------------------------------------------------------------- agent appearance\n\n  updateAppearance(\n    agentId: AgentId,\n    patch: { readonly hue?: number | null | undefined; readonly avatarAssetId?: null | undefined },\n  ) {\n    if (this.#runtime.repository.getAgent(agentId) === undefined) throw new NotFoundError('智能体不存在或已被删除。')\n    return this.#runtime.core.updateAgentAppearance(agentId, patch)\n  }\n\n  async uploadAvatar(agentId: AgentId, bytes: Uint8Array) {\n    if (this.#runtime.repository.getAgent(agentId) === undefined) throw new NotFoundError('智能体不存在或已被删除。')\n    if (bytes.byteLength === 0) throw new BadRequestError('头像文件为空。')\n    const prepared = await this.#runtime.assetService.prepare({ bytes })\n    if (!AVATAR_MEDIA_TYPES.has(prepared.asset.mediaType)) {\n      throw new BadRequestError('头像只支持 PNG、JPEG、WebP 或 GIF 图片。')\n    }\n    return this.#runtime.core.updateAgentAppearance(agentId, { avatarAssetId: prepared.asset.id })\n  }\n\n  avatarAsset(agentId: AgentId) {\n    const assetId = this.#runtime.repository.getAgent(agentId)?.definition.appearance?.avatarAssetId\n    return assetId === undefined ? undefined : this.#runtime.repository.getAssetById(assetId)\n  }\n\n  // ---------------------------------------------------------------- attention\n\n  async listAttention(): Promise<HostApiResponse<'listAttention'>> {\n    const projections = this.#runtime.repository.projections\n    const dismissed = projections.listAttentionDismissals()\n    const collected = await this.#collectAttention()\n    const quiet = new Set<string>()\n    for (const fingerprint of dismissed) {\n      if (!fingerprint.startsWith(QUIET_CAUSE_PREFIX)) continue\n      const key = fingerprint.slice(QUIET_CAUSE_PREFIX.length)\n      if (causeOngoing(key, collected)) quiet.add(key)\n      else projections.forgetAttentionDismissal(fingerprint)\n    }\n    const items = collected\n      .filter((item) => !dismissed.has(item.id) && (item.cause === undefined || !quiet.has(item.cause.key)))\n      .sort(\n        (left, right) =>\n          severityRank(left.severity) - severityRank(right.severity) || right.occurredAt - left.occurredAt,\n      )\n      .slice(0, 200)\n    const revision = createHash('sha256')\n      .update(items.map(({ id }) => id).join('\\n'))\n      .digest('hex')\n      .slice(0, 16)\n    return { revision, items }\n  }\n\n  /** Dismisses items and keeps their causes quiet: new items of a cause stay hidden until it recovers. */\n  async dismissAttentionBatch(\n    input: HostApiRequest<'dismissAttentionBatch'>,\n  ): Promise<HostApiResponse<'dismissAttentionBatch'>> {\n    const now = this.#now()\n    const retainSince = now - ATTENTION_DISMISSAL_RETENTION_MS\n    for (const id of input.ids) this.#runtime.repository.projections.dismissAttention(id, now, retainSince)\n    for (const cause of input.causes) {\n      this.#runtime.repository.projections.dismissAttention(`${QUIET_CAUSE_PREFIX}${cause}`, now, retainSince)\n    }\n    const { revision } = await this.listAttention()\n    this.#publishAttention(revision)\n    return { dismissed: true, revision }\n  }\n\n  async dismissAttention(fingerprint: string): Promise<HostApiResponse<'dismissAttention'>> {\n    const now = this.#now()\n    this.#runtime.repository.projections.dismissAttention(fingerprint, now, now - ATTENTION_DISMISSAL_RETENTION_MS)\n    const { revision } = await this.listAttention()\n    this.#publishAttention(revision)\n    return { dismissed: true, revision }\n  }\n\n  /** Coalesces attention recomputation and broadcasts only when the visible set changed. */\n  scheduleAttentionCheck(): void {\n    if (this.#disposed) return\n    this.#attentionDirty = true\n    if (this.#attentionTimer !== undefined) return\n    this.#attentionTimer = setTimeout(() => {\n      this.#attentionTimer = undefined\n      void this.#runAttentionCheck()\n    }, ATTENTION_RECHECK_DEBOUNCE_MS)\n    this.#attentionTimer.unref?.()\n  }\n\n  async #runAttentionCheck(): Promise<void> {\n    if (this.#attentionCheck !== undefined) return\n    this.#attentionCheck = (async () => {\n      while (this.#attentionDirty && !this.#disposed) {\n        this.#attentionDirty = false\n        try {\n          const { revision } = await this.listAttention()\n          this.#publishAttention(revision)\n        } catch (error) {\n          console.error('[nekro-nxt] 关注事项计算失败：', error)\n        }\n      }\n    })()\n    try {\n      await this.#attentionCheck\n    } finally {\n      this.#attentionCheck = undefined\n    }\n  }\n\n  #publishAttention(revision: string): void {\n    if (this.#disposed || revision === this.#attentionRevision) return\n    this.#attentionRevision = revision\n    this.#broadcast({ event: 'attention-changed', data: { revision } })\n  }\n\n  #connectionCause(connectionId: ConnectionId | undefined): AttentionItem['cause'] {\n    if (connectionId === undefined) return undefined\n    const connection = this.#runtime.core.getConnection(connectionId)\n    if (connection === undefined) return undefined\n    const adapterName =\n      this.#runtime.adapters.get(connection.adapterKey)?.descriptor.displayName ?? connection.adapterKey\n    return { key: `connection:${connection.id}`, label: connection.alias ?? adapterName }\n  }\n\n  #agentCause(agentId: AgentId): NonNullable<AttentionItem['cause']> {\n    return { key: `agent:${agentId}`, label: agentDisplayName(this.#runtime, agentId) }\n  }\n\n  async #collectAttention(): Promise<AttentionItem[]> {\n    const runtime = this.#runtime\n    const items: AttentionItem[] = []\n    const now = this.#now()\n    if (runtime.logs) {\n      const status = runtime.logs.currentStatus()\n      if (status.state === 'degraded') {\n        this.#logFailureAt ??= now\n        items.push({\n          id: `logs:${status.runId}:${this.#logFailureAt}`,\n          kind: 'logs-unavailable',\n          severity: 'warning',\n          subject: { kind: 'logs', id: 'logging' },\n          related: {},\n          title: '日志保存异常',\n          detail: status.error ?? '日志暂时无法保存，聊天仍可继续。',\n          action: { kind: 'open-logs', label: '查看日志' },\n          occurredAt: this.#logFailureAt,\n        })\n      } else this.#logFailureAt = undefined\n    }\n    const feedback = await runtime.feedback.list()\n    const awaitingFeedback = feedback.drafts.filter((draft) => draft.state === 'awaiting' || draft.state === 'failed')\n    const unreadFeedback = feedback.items.filter((item) => item.unread)\n    if (awaitingFeedback.length > 0) {\n      const version = createHash('sha256')\n        .update(JSON.stringify(awaitingFeedback.map((draft) => [draft.id, draft.updatedAt])))\n        .digest('hex')\n        .slice(0, 20)\n      items.push({\n        id: `feedback:drafts:${version}`,\n        kind: 'community-feedback',\n        severity: 'info',\n        subject: { kind: 'community-feedback', id: 'drafts' },\n        related: {},\n        title: `${awaitingFeedback.length} 条反馈等待确认`,\n        detail: '查看草稿和将发送的内容。',\n        action: { kind: 'open-community-feedback', label: '查看草稿' },\n        occurredAt: Math.max(...awaitingFeedback.map((draft) => draft.updatedAt)),\n      })\n    }\n    if (unreadFeedback.length > 0) {\n      const version = createHash('sha256')\n        .update(\n          JSON.stringify(\n            unreadFeedback.map((item) => [item.communityUrl, item.communityUserId, item.ref, item.lastEventSeq]),\n          ),\n        )\n        .digest('hex')\n        .slice(0, 20)\n      items.push({\n        id: `feedback:updates:${version}`,\n        kind: 'community-feedback',\n        severity: 'info',\n        subject: { kind: 'community-feedback', id: 'updates' },\n        related: {},\n        title: `${unreadFeedback.length} 条反馈有更新`,\n        detail: '查看社区回复和处理进展。',\n        action: { kind: 'open-community-feedback', label: '查看反馈' },\n        occurredAt: Math.max(...unreadFeedback.map((item) => item.updatedAt)),\n      })\n    }\n    const updates = runtime.communitySync.pending()\n    if (updates.length > 0) {\n      const version = createHash('sha256')\n        .update(JSON.stringify(updates.map((item) => [item.extensionId, item.latest?.id ?? null])))\n        .digest('hex')\n        .slice(0, 20)\n      items.push({\n        id: `extension-updates:${version}`,\n        kind: 'extension-update',\n        severity: 'info',\n        subject: { kind: 'extension-update', id: 'community' },\n        related: {},\n        title: updates.length === 1 ? `「${updates[0]!.displayName}」有新版本` : `${updates.length} 个扩展有新版本`,\n        detail:\n          updates.length === 1\n            ? '作者在社区发布了新版本，确认后更新。'\n            : `${updates.map((item) => `「${item.displayName}」`).join('')}在社区发布了新版本。`,\n        action: { kind: 'open-extension-updates', label: '查看更新' },\n        occurredAt: Math.max(...updates.map((item) => item.latest?.createdAt ?? 0)),\n      })\n    }\n\n    for (const record of runtime.repository.projections.listUnsettledAttentionOutbounds(\n      now - ATTENTION_DELIVERY_WINDOW_MS,\n      ATTENTION_DELIVERY_LIMIT,\n    )) {\n      const deliveries = runtime.repository.getOutbound(record.intent.id).deliveries\n      const unconfirmed =\n        record.intent.state === 'unknown' || deliveries.some((delivery) => delivery.state === 'unknown')\n      const channelName = channelDisplayName(runtime, record.channelId)\n      const agentId = AgentIdSchema.parse(record.agentId)\n      const author = isAdminConsoleOutbound(record.intent.sourceTurnId) ? '管理员' : agentDisplayName(runtime, agentId)\n      const cause = this.#connectionCause(runtime.core.getChannel(record.channelId)?.connectionId)\n      items.push({\n        id: `delivery:${record.intent.id}:${record.resolutionCount}`,\n        kind: unconfirmed ? 'delivery-unconfirmed' : 'delivery-failed',\n        severity: 'critical',\n        subject: { kind: 'outbound', id: record.intent.id },\n        related: { channelId: record.channelId, agentId, outboundId: record.intent.id },\n        title: channelName,\n        detail: truncate(\n          `${author}的一条消息${unconfirmed ? '未确认送达' : '发送失败'}：${previewMessageParts(runtime, record.intent.parts)}`,\n          400,\n        ),\n        action: { kind: 'resolve-delivery', label: '处理' },\n        ...(cause === undefined ? {} : { cause }),\n        occurredAt: record.intent.createdAt,\n      })\n    }\n\n    for (const connection of runtime.core.listConnections()) {\n      for (const channel of runtime.core.listChannelsByConnection(connection.id)) {\n        const binding = runtime.core.listBindings(channel.id)[0]\n        if (binding === undefined) continue\n        const projection = assembleChannelRuntime(runtime, channel.id, { binding })\n        const latest = projection.turns.at(-1)\n        if (projection.episodeId === undefined || latest === undefined) continue\n        const failed = latest.state === 'error' || latest.state === 'max-tokens' || latest.state === 'interrupted'\n        if (!failed) continue\n        items.push({\n          id: `turn:${projection.episodeId}:${latest.turn}`,\n          kind: 'turn-failed',\n          severity: latest.state === 'error' ? 'critical' : 'warning',\n          subject: { kind: 'channel', id: channel.id },\n          related: { channelId: channel.id, agentId: binding.agentId },\n          title: channelDisplayName(runtime, channel.id),\n          detail: truncate(\n            latest.state === 'error'\n              ? `${agentDisplayName(runtime, binding.agentId)}本轮失败：${latest.error?.message ?? '未知错误'}`\n              : latest.state === 'max-tokens'\n                ? `${agentDisplayName(runtime, binding.agentId)}的回复超出了输出长度上限。`\n                : `${agentDisplayName(runtime, binding.agentId)}的处理被中断，可能没有完成回复。`,\n            400,\n          ),\n          action: { kind: 'open-channel', label: '查看' },\n          cause: this.#agentCause(binding.agentId),\n          occurredAt: now,\n        })\n      }\n\n      const status = runtime.adapterConnectionDiagnostic(connection.id)?.status\n      if (status === 'failed' || status === 'reconnecting') {\n        const previous = this.#unhealthySince.get(connection.id)\n        const since = previous?.state === status ? previous.since : now\n        this.#unhealthySince.set(connection.id, { state: status, since })\n        const adapterName = runtime.adapters.get(connection.adapterKey)?.descriptor.displayName ?? connection.adapterKey\n        items.push({\n          id: `connection:${connection.id}:${status}:${since}`,\n          kind: 'connection-unhealthy',\n          severity: status === 'failed' ? 'critical' : 'warning',\n          subject: { kind: 'connection', id: connection.id },\n          related: { connectionId: connection.id },\n          title: connection.alias ?? adapterName,\n          detail:\n            status === 'failed' ? `${adapterName} 连接异常，收不到新消息。` : `${adapterName} 连接中断，正在重连。`,\n          action: { kind: 'open-connection', label: '查看连接' },\n          cause: { key: `connection:${connection.id}`, label: connection.alias ?? adapterName },\n          occurredAt: since,\n        })\n      } else {\n        this.#unhealthySince.delete(connection.id)\n      }\n    }\n\n    for (const task of runtime.repository.listAuthoringTasks()) {\n      if (task.status !== 'awaiting-approval') continue\n      const attempt = runtime.repository\n        .listAuthoringAttempts()\n        .filter((candidate) => candidate.taskId === task.id)\n        .at(-1)\n      items.push({\n        id: `authoring:${task.id}:${attempt?.id ?? 'none'}`,\n        kind: 'authoring-approval',\n        severity: 'warning',\n        subject: { kind: 'authoring-task', id: task.id },\n        related: { taskId: task.id, agentId: task.agentId, channelId: task.channelId },\n        title: task.title,\n        detail: `${agentDisplayName(runtime, task.agentId)}做好了新版本，等待你试运行。`,\n        action: { kind: 'open-authoring-task', label: '去试运行' },\n        occurredAt: task.updatedAt,\n      })\n    }\n\n    const models = await optionalProjection(() => runtime.host.listAvailableLlmModels(), undefined)\n    for (const commit of runtime.core.listAgents()) {\n      const agentId = commit.definition.id\n      const name = commit.revision.displayName\n      const available = models?.some(\n        (model) => model.provider === commit.revision.model.provider && model.id === commit.revision.model.model,\n      )\n      if (!available) {\n        items.push({\n          id: `agent-model:${agentId}:${commit.revision.id}`,\n          kind: 'agent-model-unavailable',\n          severity: models === undefined ? 'warning' : 'critical',\n          subject: { kind: 'agent', id: agentId },\n          related: { agentId },\n          title: name,\n          detail:\n            models === undefined\n              ? '模型列表暂时无法读取，请稍后重试。'\n              : `主模型 ${commit.revision.model.provider}/${commit.revision.model.model} 当前不可用，${name}无法回复。`,\n          action: { kind: 'open-agent', label: models === undefined ? '查看智能体' : '选择模型' },\n          cause: { key: `agent:${agentId}`, label: name },\n          occurredAt: commit.revision.createdAt,\n        })\n        continue\n      }\n      const diagnostics = await optionalProjection(\n        () => runtime.host.getAgentImageDiagnostics(commit.revision),\n        unavailableImageDiagnostics,\n      )\n      if (diagnostics.route.mode === 'unavailable') {\n        items.push({\n          id: `agent-vision:${agentId}:${commit.revision.id}`,\n          kind: 'agent-vision-unavailable',\n          severity: 'info',\n          subject: { kind: 'agent', id: agentId },\n          related: { agentId },\n          title: name,\n          detail: truncate(diagnostics.blockers[0] ?? '主模型看不懂图片，群里的图片会被跳过。', 400),\n          action: { kind: 'open-agent', label: '添加视觉模型' },\n          cause: { key: `agent:${agentId}`, label: name },\n          occurredAt: commit.revision.createdAt,\n        })\n      }\n    }\n    return items\n  }\n\n  // ---------------------------------------------------------------- routes\n\n  /** `/api/channels/:channelId/(read|pending|stop|pause)` delegated from the Channel route family. */\n  async handleChannelRoute(\n    req: IncomingMessage,\n    res: ServerResponse,\n    channelId: ChannelId,\n    action: 'read' | 'pending' | 'stop' | 'pause',\n  ): Promise<void> {\n    try {\n      if (action === 'pending') {\n        if (!requireMethod(req, res, 'GET')) return\n        writeContractJson(res, 200, HostApiContracts.getChannelPending, this.pending(channelId))\n        return\n      }\n      if (!requireMethod(req, res, 'POST')) return\n      if (action === 'read') {\n        const body = HostApiContracts.markChannelRead.parseRequest((await readJsonBody(req)) ?? {})\n        writeContractJson(res, 200, HostApiContracts.markChannelRead, {\n          channelId,\n          activity: this.markRead(viewerKeyFromRequest(req), channelId, body.upTo),\n        })\n        return\n      }\n      if (action === 'pause') {\n        const body = HostApiContracts.setChannelPaused.parseRequest(await readJsonBody(req))\n        if (this.#runtime.repository.getChannel(channelId) === undefined)\n          throw new NotFoundError('频道不存在或已被删除。')\n        writeContractJson(\n          res,\n          200,\n          HostApiContracts.setChannelPaused,\n          await this.#runtime.channels.setPaused(channelId, body.paused),\n        )\n        this.scheduleAttentionCheck()\n        return\n      }\n      const body = HostApiContracts.stopChannelTask.parseRequest((await readJsonBody(req)) ?? {})\n      writeContractJson(res, 200, HostApiContracts.stopChannelTask, await this.stop(channelId, body.expectedEpisodeId))\n    } catch (error) {\n      writeProjectionError(res, error)\n    }\n  }\n\n  /** `/api/agents/:agentId/revisions[/:revisionId/restore]` delegated from the Agent route family. */\n  async handleAgentRevisionRoute(\n    req: IncomingMessage,\n    res: ServerResponse,\n    agentId: AgentId,\n    restoreRevisionId: string | undefined,\n  ): Promise<void> {\n    try {\n      if (restoreRevisionId === undefined) {\n        if (!requireMethod(req, res, 'GET')) return\n        writeContractJson(res, 200, HostApiContracts.listAgentRevisions, this.revisionHistory(agentId))\n        return\n      }\n      if (!requireMethod(req, res, 'POST')) return\n      const revisionId = AgentRevisionIdSchema.parse(restoreRevisionId)\n      const body = HostApiContracts.restoreAgentRevision.parseRequest(await readJsonBody(req))\n      writeContractJson(res, 200, HostApiContracts.restoreAgentRevision, {\n        currentRevisionId: this.restoreRevision(agentId, revisionId, body.expectedCurrentRevisionId),\n      })\n    } catch (error) {\n      writeProjectionError(res, error)\n    }\n  }\n\n  /** `/api/agents/:agentId/(appearance|avatar)` delegated from the Agent route family. */\n  async handleAgentRoute(\n    req: IncomingMessage,\n    res: ServerResponse,\n    agentId: AgentId,\n    action: 'appearance' | 'avatar',\n  ): Promise<void> {\n    try {\n      if (action === 'appearance') {\n        if (!requireMethod(req, res, 'PATCH')) return\n        const body = HostApiContracts.updateAgentAppearance.parseRequest((await readJsonBody(req)) ?? {})\n        writeContractJson(res, 200, HostApiContracts.updateAgentAppearance, {\n          agentId,\n          appearance: this.updateAppearance(agentId, body),\n        })\n        return\n      }\n      if (req.method === 'POST') {\n        const appearance = await this.uploadAvatar(agentId, await readBinaryBody(req, AVATAR_MAX_BYTES))\n        writeContractJson(res, 200, HostApiContracts.uploadAgentAvatar, { agentId, appearance })\n        return\n      }\n      if (!requireMethod(req, res, 'GET')) return\n      const asset = this.avatarAsset(agentId)\n      if (asset === undefined) {\n        writeError(res, 404, 'avatar-not-found', '这个智能体没有头像。')\n        return\n      }\n      const bytes = await readFile(this.#runtime.assetService.blobPath(asset))\n      res.writeHead(200, {\n        'content-type': asset.mediaType,\n        'content-length': String(bytes.byteLength),\n        'cache-control': 'private, no-cache',\n        etag: `\"${asset.contentDigest}\"`,\n        'x-content-type-options': 'nosniff',\n      })\n      res.end(bytes)\n    } catch (error) {\n      writeProjectionError(res, error)\n    }\n  }\n\n  registerRoutes({ registerRoute }: Pick<HostRouteContext, 'registerRoute'>): void {\n    registerRoute({\n      kind: 'prefix',\n      path: '/api/attention',\n      handler: async (req, res) => {\n        const url = new URL(req.url ?? '/', 'http://localhost')\n        try {\n          if (url.pathname === '/api/attention') {\n            if (!requireMethod(req, res, 'GET')) return\n            writeContractJson(res, 200, HostApiContracts.listAttention, await this.listAttention())\n            return\n          }\n          if (url.pathname === '/api/attention/dismiss') {\n            if (!requireMethod(req, res, 'POST')) return\n            const body = HostApiContracts.dismissAttentionBatch.parseRequest(await readJsonBody(req))\n            writeContractJson(res, 200, HostApiContracts.dismissAttentionBatch, await this.dismissAttentionBatch(body))\n            return\n          }\n          const match = /^\\/api\\/attention\\/([^/]+)\\/dismiss$/u.exec(url.pathname)\n          if (!match) {\n            writeError(res, 404, 'not-found', `Unknown route: ${req.method} ${url.pathname}`)\n            return\n          }\n          if (!requireMethod(req, res, 'POST')) return\n          const params = HostApiContracts.dismissAttention.parseParams({\n            attentionId: decodeURIComponent(match[1] ?? ''),\n          })\n          writeContractJson(\n            res,\n            200,\n            HostApiContracts.dismissAttention,\n            await this.dismissAttention(params.attentionId),\n          )\n        } catch (error) {\n          writeProjectionError(res, error)\n        }\n      },\n    })\n    registerRoute({\n      kind: 'exact',\n      path: '/api/activity',\n      handler: (req, res) => {\n        if (!requireMethod(req, res, 'GET')) return\n        const url = new URL(req.url ?? '/', 'http://localhost')\n        try {\n          const query = HostApiContracts.getChannelActivity.parseParams(Object.fromEntries(url.searchParams))\n          writeContractJson(res, 200, HostApiContracts.getChannelActivity, this.activity(query))\n        } catch (error) {\n          writeProjectionError(res, error)\n        }\n      },\n    })\n    registerRoute({\n      kind: 'prefix',\n      path: '/api/outbound',\n      handler: async (req, res) => {\n        const url = new URL(req.url ?? '/', 'http://localhost')\n        const match = /^\\/api\\/outbound\\/([^/]+)\\/resolve$/u.exec(url.pathname)\n        if (!match) {\n          writeError(res, 404, 'not-found', `Unknown route: ${req.method} ${url.pathname}`)\n          return\n        }\n        if (!requireMethod(req, res, 'POST')) return\n        try {\n          const outboundId = OutboundIntentIdSchema.parse(decodeURIComponent(match[1] ?? ''))\n          const body = HostApiContracts.resolveOutbound.parseRequest(await readJsonBody(req))\n          writeContractJson(\n            res,\n            200,\n            HostApiContracts.resolveOutbound,\n            await this.resolveOutbound(outboundId, body.action, viewerKeyFromRequest(req)),\n          )\n        } catch (error) {\n          writeProjectionError(res, error)\n        }\n      },\n    })\n  }\n}\n\nconst severityRank = (severity: AttentionItem['severity']): number =>\n  severity === 'critical' ? 0 : severity === 'warning' ? 1 : 2\n\nclass NotFoundError extends Error {}\nclass RevisionConflictError extends Error {}\nclass BadRequestError extends Error {}\n\nconst requireMethod = (req: IncomingMessage, res: ServerResponse, method: string): boolean => {\n  if (req.method === method) return true\n  writeError(res, 405, 'method-not-allowed', `只支持 ${method}。`)\n  return false\n}\n\nconst writeProjectionError = (res: ServerResponse, error: unknown): void => {\n  const message = error instanceof Error ? error.message : String(error)\n  if (error instanceof NotFoundError) writeError(res, 404, 'not-found', message)\n  else if (error instanceof ChannelStopConflictError) writeError(res, 409, 'episode-conflict', message)\n  else if (error instanceof RevisionConflictError) writeError(res, 409, 'revision-conflict', message)\n  else if (error instanceof OutboundResolutionError) {\n    writeError(res, error.code === 'not-found' ? 404 : 409, `outbound-${error.code}`, message)\n  } else writeError(res, 400, 'invalid-request', message)\n}\n\nexport const parseRouteChannelId = (raw: string): ChannelId => ChannelIdSchema.parse(decodeURIComponent(raw))\n"
    },
    {
      "path": "packages/storage-sqlite/src/repositories/projections.ts",
      "content": "import { and, asc, count, desc, eq, gt, gte, inArray, isNotNull, lt, or, sql } from 'drizzle-orm'\nimport type { ChannelId, JsonValue, OutboundIntentId } from '@nekro-nxt/contracts'\nimport type { OutboundIntentRecord } from '@nekro-nxt/channel-runtime'\nimport type { ChannelEventRecord } from '@nekro-nxt/core'\nimport type { DrizzleCoreDatabase } from '../database.js'\nimport {\n  attentionDismissals,\n  channelEvents,\n  channelReadCursors,\n  episodes,\n  outboundIntents,\n  outboundResolutions,\n  physicalDeliveries,\n  readViewers,\n} from '../schema.js'\nimport { OutboundResolutionRowSchema, PhysicalDeliveryRowSchema } from '../row-schemas.js'\nimport { toEvent } from './channels.js'\nimport { toIntent } from './outbox.js'\n\n/** Position in one Channel's inbound history, ordered by `(receivedAt, id)` with BINARY id collation. */\nexport interface ChannelReadPosition {\n  readonly readAt: number\n  readonly readSourceId: string\n}\n\nexport interface OutboundResolutionRecord {\n  readonly id: string\n  readonly intentId: OutboundIntentId\n  readonly action: 'retry' | 'confirm-delivered'\n  readonly previousState: 'partially-sent' | 'failed' | 'unknown'\n  readonly previousDeliveries: JsonValue\n  readonly viewerKey: string\n  readonly createdAt: number\n}\n\nexport interface UnsettledOutboundRecord {\n  readonly intent: OutboundIntentRecord\n  readonly channelId: ChannelId\n  readonly agentId: string\n  /** Number of earlier administrator resolutions, so a renewed failure gets a new attention fingerprint. */\n  readonly resolutionCount: number\n}\n\nexport type ResolvableOutboundState = OutboundResolutionRecord['previousState']\n\nconst RESOLVABLE_STATES = ['partially-sent', 'failed', 'unknown'] as const\n\nconst isResolvable = (state: string): state is ResolvableOutboundState =>\n  (RESOLVABLE_STATES as readonly string[]).includes(state)\n\nconst visibleInbound = sql`coalesce(json_type(${channelEvents.facts}, '$.consoleAnchor'), 'null') != 'true'`\nconst memberMessage = and(\n  eq(channelEvents.kind, 'message-created'),\n  isNotNull(channelEvents.senderMemberId),\n  visibleInbound,\n  sql`coalesce(json_type(${channelEvents.facts}, '$.selfInteraction'), 'null') != 'true'`,\n)\nconst afterPosition = (position: ChannelReadPosition) =>\n  or(\n    gt(channelEvents.receivedAt, position.readAt),\n    and(\n      eq(channelEvents.receivedAt, position.readAt),\n      sql`${channelEvents.id} > ${position.readSourceId} collate binary`,\n    ),\n  )\n\nconst toResolution = (input: typeof outboundResolutions.$inferSelect): OutboundResolutionRecord => {\n  const row = OutboundResolutionRowSchema.parse(input)\n  return {\n    id: row.id,\n    intentId: row.intentId,\n    action: row.action,\n    previousState: row.previousState,\n    previousDeliveries: row.previousDeliveries,\n    viewerKey: row.viewerKey,\n    createdAt: row.createdAt,\n  }\n}\n\n/** Read models for the client workspace: read positions, activity, attention and delivery resolutions. */\nexport function createProjectionRepository(database: DrizzleCoreDatabase) {\n  const latestResolution = (intentId: OutboundIntentId): OutboundResolutionRecord | undefined => {\n    const row = database\n      .select()\n      .from(outboundResolutions)\n      .where(eq(outboundResolutions.intentId, intentId))\n      .orderBy(desc(outboundResolutions.createdAt), desc(outboundResolutions.id))\n      .get()\n    return row === undefined ? undefined : toResolution(row)\n  }\n\n  return {\n    /** Registers a viewer on first use; its creation time is the unread baseline for Channels it never read. */\n    ensureReadViewer(viewerKey: string, now: number): number {\n      if (viewerKey.trim().length === 0 || viewerKey.length > 200) throw new TypeError('Invalid viewer key.')\n      database.insert(readViewers).values({ viewerKey, createdAt: now }).onConflictDoNothing().run()\n      const row = database.select().from(readViewers).where(eq(readViewers.viewerKey, viewerKey)).get()\n      if (row === undefined) throw new Error(`Viewer was not persisted: ${viewerKey}`)\n      return row.createdAt\n    },\n\n    listChannelReadPositions(viewerKey: string): ReadonlyMap<ChannelId, ChannelReadPosition> {\n      return new Map(\n        database\n          .select()\n          .from(channelReadCursors)\n          .where(eq(channelReadCursors.viewerKey, viewerKey))\n          .all()\n          .map((row) => [row.channelId, { readAt: row.readAt, readSourceId: row.readSourceId }] as const),\n      )\n    },\n\n    /** Moves the cursor forward only; a stale request from another tab never marks newer messages unread. */\n    advanceChannelReadPosition(\n      viewerKey: string,\n      channelId: ChannelId,\n      position: ChannelReadPosition,\n      now: number,\n    ): ChannelReadPosition {\n      return database.transaction(\n        (tx) => {\n          const current = tx\n            .select()\n            .from(channelReadCursors)\n            .where(and(eq(channelReadCursors.viewerKey, viewerKey), eq(channelReadCursors.channelId, channelId)))\n            .get()\n          const advances =\n            current === undefined ||\n            position.readAt > current.readAt ||\n            (position.readAt === current.readAt && position.readSourceId > current.readSourceId)\n          if (!advances) return { readAt: current.readAt, readSourceId: current.readSourceId }\n          tx.insert(channelReadCursors)\n            .values({ viewerKey, channelId, ...position, updatedAt: now })\n            .onConflictDoUpdate({\n              target: [channelReadCursors.viewerKey, channelReadCursors.channelId],\n              set: { ...position, updatedAt: now },\n            })\n            .run()\n          return position\n        },\n        { behavior: 'immediate' },\n      )\n    },\n\n    getLatestMemberMessage(channelId: ChannelId): ChannelEventRecord | undefined {\n      const row = database\n        .select()\n        .from(channelEvents)\n        .where(and(eq(channelEvents.channelId, channelId), memberMessage))\n        .orderBy(desc(channelEvents.receivedAt), desc(channelEvents.id))\n        .get()\n      return row === undefined ? undefined : toEvent(row)\n    },\n\n    getLatestVisibleInbound(channelId: ChannelId): ChannelEventRecord | undefined {\n      const row = database\n        .select()\n        .from(channelEvents)\n        .where(and(eq(channelEvents.channelId, channelId), eq(channelEvents.kind, 'message-created'), visibleInbound))\n        .orderBy(desc(channelEvents.receivedAt), desc(channelEvents.id))\n        .get()\n      return row === undefined ? undefined : toEvent(row)\n    },\n\n    getLatestOutbound(channelId: ChannelId): OutboundIntentRecord | undefined {\n      const row = database\n        .select({ intent: outboundIntents })\n        .from(outboundIntents)\n        .leftJoin(episodes, eq(episodes.id, outboundIntents.episodeId))\n        .where(or(eq(episodes.channelId, channelId), eq(outboundIntents.channelId, channelId)))\n        .orderBy(desc(outboundIntents.createdAt), desc(outboundIntents.id))\n        .get()\n      return row === undefined ? undefined : toIntent(row.intent)\n    },\n\n    /** Counts member messages after the position, reading at most `cap + 1` rows. */\n    countUnreadMemberMessages(\n      channelId: ChannelId,\n      after: ChannelReadPosition,\n      cap: number,\n    ): { readonly count: number; readonly capped: boolean } {\n      const rows = database\n        .select({ id: channelEvents.id })\n        .from(channelEvents)\n        .where(and(eq(channelEvents.channelId, channelId), memberMessage, afterPosition(after)))\n        .limit(cap + 1)\n        .all()\n      return { count: Math.min(rows.length, cap), capped: rows.length > cap }\n    },\n\n    /** Member message and Agent/admin outbound counts per Channel in `[from, to)` buckets. */\n    countChannelActivity(\n      from: number,\n      to: number,\n      bucketMs: number,\n    ): ReadonlyMap<ChannelId, ReadonlyMap<number, number>> {\n      const result = new Map<ChannelId, Map<number, number>>()\n      const add = (channelId: ChannelId, bucket: number, value: number): void => {\n        const buckets = result.get(channelId) ?? new Map<number, number>()\n        buckets.set(bucket, (buckets.get(bucket) ?? 0) + value)\n        result.set(channelId, buckets)\n      }\n      const inboundBucket = sql<number>`cast((${channelEvents.receivedAt} - ${from}) / ${bucketMs} as integer)`\n      for (const row of database\n        .select({ channelId: channelEvents.channelId, bucket: inboundBucket, value: count() })\n        .from(channelEvents)\n        .where(\n          and(\n            eq(channelEvents.kind, 'message-created'),\n            visibleInbound,\n            gte(channelEvents.receivedAt, from),\n            lt(channelEvents.receivedAt, to),\n          ),\n        )\n        .groupBy(channelEvents.channelId, inboundBucket)\n        .all())\n        add(row.channelId, row.bucket, row.value)\n      const outboundBucket = sql<number>`cast((${outboundIntents.createdAt} - ${from}) / ${bucketMs} as integer)`\n      for (const row of database\n        .select({ channelId: episodes.channelId, bucket: outboundBucket, value: count() })\n        .from(outboundIntents)\n        .innerJoin(episodes, eq(episodes.id, outboundIntents.episodeId))\n        .where(and(gte(outboundIntents.createdAt, from), lt(outboundIntents.createdAt, to)))\n        .groupBy(episodes.channelId, outboundBucket)\n        .all())\n        add(row.channelId, row.bucket, row.value)\n      return result\n    },\n\n    listAttentionDismissals(): ReadonlySet<string> {\n      return new Set(\n        database\n          .select({ fingerprint: attentionDismissals.fingerprint })\n          .from(attentionDismissals)\n          .all()\n          .map(({ fingerprint }) => fingerprint),\n      )\n    },\n\n    /** Forgets one dismissal, e.g. a cause kept quiet until it recovered. */\n    forgetAttentionDismissal(fingerprint: string): void {\n      database.delete(attentionDismissals).where(eq(attentionDismissals.fingerprint, fingerprint)).run()\n    },\n\n    /** Records a dismissal and forgets dismissals older than `retainSince`. */\n    dismissAttention(fingerprint: string, now: number, retainSince: number): void {\n      if (fingerprint.length === 0 || fingerprint.length > 200) throw new TypeError('Invalid attention fingerprint.')\n      database.transaction(\n        (tx) => {\n          tx.insert(attentionDismissals).values({ fingerprint, dismissedAt: now }).onConflictDoNothing().run()\n          tx.delete(attentionDismissals).where(lt(attentionDismissals.dismissedAt, retainSince)).run()\n        },\n        { behavior: 'immediate' },\n      )\n    },\n\n    /** Outbound Intents whose final state needs an administrator, newest first, excluding confirmed ones. */\n    listUnsettledAttentionOutbounds(since: number, limit: number): readonly UnsettledOutboundRecord[] {\n      const rows = database\n        .select({ intent: outboundIntents, channelId: episodes.channelId, agentId: episodes.agentId })\n        .from(outboundIntents)\n        .innerJoin(episodes, eq(episodes.id, outboundIntents.episodeId))\n        .where(\n          and(\n            inArray(outboundIntents.state, [...RESOLVABLE_STATES]),\n            gte(outboundIntents.createdAt, since),\n            sql`not exists (select 1 from ${outboundResolutions} where ${outboundResolutions.intentId} = ${outboundIntents.id} and ${outboundResolutions.action} = 'confirm-delivered')`,\n          ),\n        )\n        .orderBy(desc(outboundIntents.createdAt), desc(outboundIntents.id))\n        .limit(limit)\n        .all()\n      return rows.map((row) => ({\n        intent: toIntent(row.intent),\n        channelId: row.channelId,\n        agentId: row.agentId,\n        resolutionCount:\n          database\n            .select({ value: count() })\n            .from(outboundResolutions)\n            .where(eq(outboundResolutions.intentId, row.intent.id))\n            .get()?.value ?? 0,\n      }))\n    },\n\n    getLatestOutboundResolution: latestResolution,\n\n    /**\n     * Atomically records the administrator's resolution. `retry` returns every unsent Physical Delivery and\n     * the Intent to `planned` so the normal dispatcher sends it again; the replaced receipts stay in the\n     * resolution row. A second concurrent request finds the Intent no longer resolvable and fails.\n     */\n    resolveOutbound(input: {\n      readonly id: string\n      readonly intentId: OutboundIntentId\n      readonly action: OutboundResolutionRecord['action']\n      readonly viewerKey: string\n      readonly now: number\n    }): OutboundResolutionRecord {\n      return database.transaction(\n        (tx) => {\n          const intentRow = tx.select().from(outboundIntents).where(eq(outboundIntents.id, input.intentId)).get()\n          if (intentRow === undefined) throw new OutboundResolutionError('not-found', '投递记录不存在。')\n          const state = intentRow.state\n          if (!isResolvable(state)) {\n            throw new OutboundResolutionError('not-resolvable', '这条消息当前不需要处理。')\n          }\n          const confirmed = tx\n            .select({ id: outboundResolutions.id })\n            .from(outboundResolutions)\n            .where(\n              and(\n                eq(outboundResolutions.intentId, input.intentId),\n                eq(outboundResolutions.action, 'confirm-delivered'),\n              ),\n            )\n            .get()\n          if (confirmed !== undefined) throw new OutboundResolutionError('not-resolvable', '这条消息已确认送达。')\n          const deliveries = tx\n            .select()\n            .from(physicalDeliveries)\n            .where(eq(physicalDeliveries.intentId, input.intentId))\n            .orderBy(asc(physicalDeliveries.sequence))\n            .all()\n            .map((row) => PhysicalDeliveryRowSchema.parse(row))\n          const previousDeliveries: JsonValue = deliveries.map((delivery) => ({\n            id: delivery.id,\n            sequence: delivery.sequence,\n            state: delivery.state,\n            ...(delivery.platformMessageId === null ? {} : { platformMessageId: delivery.platformMessageId }),\n            ...(delivery.failureKind === null ? {} : { failureKind: delivery.failureKind }),\n            ...(delivery.resultMessage === null ? {} : { resultMessage: delivery.resultMessage }),\n            ...(delivery.completedAt === null ? {} : { completedAt: delivery.completedAt }),\n          }))\n          const record = {\n            id: input.id,\n            intentId: input.intentId,\n            action: input.action,\n            previousState: state,\n            previousDeliveries,\n            viewerKey: input.viewerKey,\n            createdAt: input.now,\n          }\n          tx.insert(outboundResolutions).values(record).run()\n          if (input.action === 'retry') {\n            const retried = deliveries.filter((delivery) => delivery.state === 'failed' || delivery.state === 'unknown')\n            if (retried.length === 0) throw new OutboundResolutionError('not-resolvable', '没有需要重新发送的内容。')\n            for (const delivery of retried) {\n              tx.update(physicalDeliveries)\n                .set({\n                  state: 'planned',\n                  platformMessageId: null,\n                  capabilityOutcomes: null,\n                  failureKind: null,\n                  resultMessage: null,\n                  retryAfterMs: null,\n                  completedAt: null,\n                })\n                .where(and(eq(physicalDeliveries.id, delivery.id), eq(physicalDeliveries.state, delivery.state)))\n                .run()\n            }\n            if (\n              tx\n                .update(outboundIntents)\n                .set({ state: 'planned' })\n                .where(and(eq(outboundIntents.id, input.intentId), eq(outboundIntents.state, state)))\n                .run().changes !== 1\n            )\n              throw new OutboundResolutionError('not-resolvable', '这条消息的状态已经变化，请刷新后重试。')\n          }\n          return toResolution(record)\n        },\n        { behavior: 'immediate' },\n      )\n    },\n  }\n}\n\nexport class OutboundResolutionError extends Error {\n  constructor(\n    readonly code: 'not-found' | 'not-resolvable',\n    message: string,\n  ) {\n    super(message)\n    this.name = 'OutboundResolutionError'\n  }\n}\n\nexport type ProjectionRepository = ReturnType<typeof createProjectionRepository>\n"
    },
    {
      "path": "apps/server/src/management-edge.ts",
      "content": "import {\n  InstanceDescriptorSchema,\n  ManagementDeviceEnrollmentRequestSchema,\n  ManagementDeviceEnrollmentResponseSchema,\n  ManagementDeviceIdSchema,\n  ManagementSessionRequestSchema,\n  ManagementSessionResponseSchema,\n  ServerInstanceIdSchema,\n  managementPairProofMessage,\n  parseJsonValue,\n  type InstanceDescriptor,\n  type ManagementDeviceId,\n  type ServerInstanceId,\n} from '@nekro-nxt/contracts'\nimport type { SqliteHostSecurityRepository } from '@nekro-nxt/storage-sqlite'\nimport { X509Certificate, createHash, createHmac, randomBytes, timingSafeEqual } from 'node:crypto'\nimport { chmod, mkdir, readFile, rename, writeFile } from 'node:fs/promises'\nimport { request as httpRequest } from 'node:http'\nimport type { ClientRequest, IncomingMessage, ServerResponse } from 'node:http'\nimport { z } from 'zod'\nimport { managementLoginPage } from './management-login-page.js'\nimport { startHttpListener } from './http-listener.js'\nimport path from 'node:path'\nimport { generate } from 'selfsigned'\nimport { VIEWER_HEADER } from './viewer.js'\nimport { monotonicFactory } from 'ulid'\n\nconst SESSION_COOKIE = 'nxt_session'\nconst CSRF_COOKIE = 'nxt_csrf'\n/** A browser's device credential `<deviceId>.<secret>`; HttpOnly, so page and extension scripts cannot read it. */\nconst DEVICE_COOKIE = 'nxt_device'\nconst BROWSER_DEVICE_TTL_MS = 30 * 24 * 60 * 60 * 1_000\n/** Last activity is written at most once a minute per device. */\nconst ACTIVITY_WRITE_INTERVAL_MS = 60_000\nconst CHALLENGE_TTL_MS = 60_000\nconst SESSION_TTL_MS = 12 * 60 * 60 * 1_000\nconst MAX_JSON_BYTES = 64 * 1_024\nconst MAX_PENDING_CHALLENGES = 256\nconst CHALLENGES_PER_ADDRESS_PER_MINUTE = 10\nconst CHALLENGE_RATE_WINDOW_MS = 60_000\nconst nextUlid = monotonicFactory()\n\ninterface ChallengeRecord {\n  readonly serverNonce: string\n  readonly expiresAt: number\n}\n\ninterface SessionRecord {\n  readonly deviceId: ManagementDeviceId\n  readonly csrfToken: string\n  readonly expiresAt: number\n}\n\nexport const managementLoginRequestSchema = z\n  .object({ managementKey: z.string().min(1).max(4096), acknowledgeInsecure: z.boolean().default(false) })\n  .strict()\n\nexport interface ManagementEdgeOptions {\n  readonly host: '127.0.0.1' | '0.0.0.0'\n  readonly port: number\n  readonly internalPort: number\n  readonly dataRoot: string\n  readonly managementKey: string\n  readonly releaseId: string\n  readonly productVersion: string\n  readonly repository: SqliteHostSecurityRepository\n  /** Trust `X-Forwarded-Proto` / `X-Forwarded-Host` from a reverse proxy that terminates HTTPS in front of plain HTTP. */\n  readonly trustProxy?: boolean\n  readonly now?: () => number\n}\n\nexport interface ManagementEdgeHandle {\n  readonly port: number\n  readonly instanceId: ServerInstanceId\n  readonly spkiSha256: string\n  stop(): Promise<void>\n}\n\nconst digest = (prefix: string, value: string): string =>\n  createHash('sha256').update(prefix).update('\\0').update(value).digest('base64url')\n\nconst safeEqual = (left: string, right: string): boolean => {\n  const leftBuffer = Buffer.from(left)\n  const rightBuffer = Buffer.from(right)\n  return leftBuffer.length === rightBuffer.length && timingSafeEqual(leftBuffer, rightBuffer)\n}\n\nconst writeJson = (\n  response: ServerResponse,\n  status: number,\n  body: unknown,\n  headers?: Record<string, string | string[]>,\n): void => {\n  const encoded = JSON.stringify(body)\n  response.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'cache-control': 'no-store',\n    'content-length': Buffer.byteLength(encoded),\n    ...headers,\n  })\n  response.end(encoded)\n}\n\nconst writeProblem = (response: ServerResponse, status: number, code: string, message: string): void =>\n  writeJson(response, status, { error: { code, message } })\n\nconst readJson = (request: IncomingMessage): Promise<unknown> =>\n  new Promise((resolve, reject) => {\n    const chunks: Uint8Array[] = []\n    let size = 0\n    request.on('data', (chunk: Uint8Array) => {\n      size += chunk.length\n      if (size > MAX_JSON_BYTES) {\n        reject(new Error('请求正文过大。'))\n        request.destroy()\n        return\n      }\n      chunks.push(chunk)\n    })\n    request.on('end', () => {\n      try {\n        const text = Buffer.concat(chunks).toString('utf8').trim()\n        resolve(text.length === 0 ? undefined : parseJsonValue(JSON.parse(text)))\n      } catch (error) {\n        reject(error instanceof Error ? error : new Error(String(error)))\n      }\n    })\n    request.on('error', reject)\n  })\n\nconst parseCookies = (request: IncomingMessage): ReadonlyMap<string, string> => {\n  const cookies = new Map<string, string>()\n  for (const item of (request.headers.cookie ?? '').split(';')) {\n    const separator = item.indexOf('=')\n    if (separator < 1) continue\n    cookies.set(item.slice(0, separator).trim(), item.slice(separator + 1).trim())\n  }\n  return cookies\n}\n\n/**\n * `Secure` only over HTTPS, or browsers drop the cookie on plain HTTP. `Lax` keeps a login across links opened from\n * elsewhere; mutations stay protected by the same-origin and CSRF checks.\n */\nconst cookie = (\n  name: string,\n  value: string,\n  maxAgeSeconds: number,\n  options: { readonly httpOnly: boolean; readonly secure: boolean },\n): string =>\n  `${name}=${value}; Path=/; Max-Age=${maxAgeSeconds}; ${options.httpOnly ? 'HttpOnly; ' : ''}${options.secure ? 'Secure; ' : ''}SameSite=Lax`\n\n/**\n * Anonymous pages passed to the product server: health, the brand icon the login page shows, the web app manifest\n * with its icons (browsers fetch the manifest without cookies), and the community sign-in callback. The callback\n * completes only a sign-in this instance started, matched by a one-time state; the browser that returns from the\n * community (often the system browser of a Desktop user) carries no session here.\n */\nconst publicProxyPath = (pathname: string): boolean =>\n  pathname === '/health/live' ||\n  pathname === '/health/ready' ||\n  pathname === '/favicon.svg' ||\n  pathname === '/brand/mark.svg' ||\n  pathname === '/site.webmanifest' ||\n  pathname === '/pwa-192.png' ||\n  pathname === '/pwa-512.png' ||\n  pathname === '/pwa-maskable-512.png' ||\n  pathname === '/community/callback'\n\n/** A short device name from the browser's User-Agent, e.g. 「浏览器 · Chrome · macOS」. */\nexport const browserDeviceLabel = (userAgent: string | undefined): string => {\n  const agent = userAgent ?? ''\n  const browser = /Edg\\//u.test(agent)\n    ? 'Edge'\n    : /Firefox\\//u.test(agent)\n      ? 'Firefox'\n      : /Chrome\\//u.test(agent)\n        ? 'Chrome'\n        : /Safari\\//u.test(agent)\n          ? 'Safari'\n          : undefined\n  const system = /iPhone|iPad/u.test(agent)\n    ? 'iOS'\n    : /Android/u.test(agent)\n      ? 'Android'\n      : /Mac OS X|Macintosh/u.test(agent)\n        ? 'macOS'\n        : /Windows/u.test(agent)\n          ? 'Windows'\n          : /Linux/u.test(agent)\n            ? 'Linux'\n            : undefined\n  return ['浏览器', browser, system].filter((part) => part !== undefined).join(' · ')\n}\n\n/** Relative path inside this site to return to after login; anything else falls back to the root. */\nconst safeNext = (value: string | null): string =>\n  value !== null && value.startsWith('/') && !value.startsWith('//') && !value.startsWith('/login') ? value : '/'\n\nconst wantsPage = (request: IncomingMessage, pathname: string): boolean =>\n  (request.method === 'GET' || request.method === 'HEAD') &&\n  !pathname.startsWith('/api/') &&\n  (request.headers.accept ?? '').includes('text/html')\n\nconst methodIsSafe = (method: string | undefined): boolean =>\n  method === 'GET' || method === 'HEAD' || method === 'OPTIONS'\n\nexport const loadOrCreateCertificate = async (\n  dataRoot: string,\n  instanceId: ServerInstanceId | 'recovery',\n): Promise<{ readonly key: string; readonly cert: string; readonly spkiSha256: string }> => {\n  const tlsRoot = path.join(dataRoot, 'host', 'tls')\n  const keyPath = path.join(tlsRoot, 'server-key.pem')\n  const certPath = path.join(tlsRoot, 'server-cert.pem')\n  await mkdir(tlsRoot, { recursive: true, mode: 0o700 })\n  let key: string\n  let cert: string\n  try {\n    ;[key, cert] = await Promise.all([readFile(keyPath, 'utf8'), readFile(certPath, 'utf8')])\n  } catch (error) {\n    const code = error instanceof Error && 'code' in error ? error.code : undefined\n    if (code !== 'ENOENT') throw error\n    const generated = await generate([{ name: 'commonName', value: `NekroNxt ${instanceId}` }], {\n      keyType: 'ec',\n      curve: 'P-256',\n      algorithm: 'sha256',\n      notAfterDate: new Date(Date.now() + 10 * 365 * 24 * 60 * 60 * 1_000),\n      extensions: [\n        { name: 'basicConstraints', cA: false, critical: true },\n        { name: 'keyUsage', digitalSignature: true, keyAgreement: true, critical: true },\n        { name: 'extKeyUsage', serverAuth: true },\n        {\n          name: 'subjectAltName',\n          altNames: [\n            { type: 2, value: 'localhost' },\n            { type: 7, ip: '127.0.0.1' },\n            { type: 7, ip: '::1' },\n          ],\n        },\n      ],\n    })\n    key = generated.private\n    cert = generated.cert\n    const suffix = randomBytes(8).toString('hex')\n    const temporaryKey = `${keyPath}.${suffix}.tmp`\n    const temporaryCert = `${certPath}.${suffix}.tmp`\n    await writeFile(temporaryKey, key, { mode: 0o600, flag: 'wx' })\n    await writeFile(temporaryCert, cert, { mode: 0o600, flag: 'wx' })\n    await rename(temporaryKey, keyPath)\n    await rename(temporaryCert, certPath)\n  }\n  await Promise.all([chmod(keyPath, 0o600), chmod(certPath, 0o600)])\n  const certificate = new X509Certificate(cert)\n  const publicKey = certificate.publicKey.export({ type: 'spki', format: 'der' })\n  return { key, cert, spkiSha256: createHash('sha256').update(publicKey).digest('base64url') }\n}\n\nexport const initializeServerIdentity = (\n  repository: SqliteHostSecurityRepository,\n  managementKey: string | undefined,\n  now: number,\n): ServerInstanceId => {\n  const keyDigest = digest(\n    managementKey === undefined ? 'nxt-management-key-unconfigured-v1' : 'nxt-management-key-v1',\n    managementKey ?? '',\n  )\n  const current = repository.getMetadata()\n  if (current !== undefined) {\n    if (!safeEqual(current.managementKeyDigest, keyDigest)) {\n      repository.revokeAllDevices(now)\n      repository.putMetadata({ ...current, managementKeyDigest: keyDigest, updatedAt: now })\n    }\n    return current.instanceId\n  }\n  const instanceId = ServerInstanceIdSchema.parse(`nxt_instance_${nextUlid()}`)\n  repository.putMetadata({ instanceId, managementKeyDigest: keyDigest, createdAt: now, updatedAt: now })\n  return instanceId\n}\n\nexport const startManagementEdge = async (options: ManagementEdgeOptions): Promise<ManagementEdgeHandle> => {\n  const now = options.now ?? Date.now\n  const instanceId = initializeServerIdentity(options.repository, options.managementKey, now())\n  const certificate = await loadOrCreateCertificate(options.dataRoot, instanceId)\n  const descriptor: InstanceDescriptor = InstanceDescriptorSchema.parse({\n    format: 'nxt.instance-descriptor',\n    descriptorVersion: 1,\n    instanceId,\n    releaseId: options.releaseId,\n    productVersion: options.productVersion,\n    managementProtocol: 1,\n    desktopChromeProtocol: 1,\n    transport: 'auto-tls-pinned-v1',\n  })\n  const challenges = new Map<string, ChallengeRecord>()\n  const sessions = new Map<string, SessionRecord>()\n  const challengeRequests = new Map<string, number[]>()\n  const lastActivityWrite = new Map<ManagementDeviceId, number>()\n  const upstreamRequests = new Set<ClientRequest>()\n  let stopping = false\n  let stopPromise: Promise<void> | undefined\n\n  /** Pairing challenges and browser logins share one per-address budget of attempts per minute. */\n  const allowAttempt = (address: string): boolean => {\n    cleanExpired()\n    const recent = challengeRequests.get(address) ?? []\n    if (recent.length >= CHALLENGES_PER_ADDRESS_PER_MINUTE) return false\n    challengeRequests.set(address, [...recent, now()])\n    return true\n  }\n\n  const cleanExpired = (): void => {\n    const timestamp = now()\n    for (const [id, challenge] of challenges) if (challenge.expiresAt <= timestamp) challenges.delete(id)\n    for (const [id, session] of sessions) if (session.expiresAt <= timestamp) sessions.delete(id)\n    for (const [address, requests] of challengeRequests) {\n      const retained = requests.filter((requestedAt) => requestedAt > timestamp - CHALLENGE_RATE_WINDOW_MS)\n      if (retained.length === 0) challengeRequests.delete(address)\n      else challengeRequests.set(address, retained)\n    }\n  }\n\n  const header = (request: IncomingMessage, name: string): string | undefined => {\n    const value = request.headers[name]\n    const first = Array.isArray(value) ? value[0] : value\n    return first?.split(',')[0]?.trim() || undefined\n  }\n\n  /** HTTPS on this socket, or a trusted reverse proxy that terminated HTTPS in front of it. */\n  const secureRequest = (request: IncomingMessage): boolean =>\n    ('encrypted' in request.socket && request.socket.encrypted === true) ||\n    (options.trustProxy === true && header(request, 'x-forwarded-proto') === 'https')\n\n  const publicHost = (request: IncomingMessage): string | undefined =>\n    (options.trustProxy === true ? header(request, 'x-forwarded-host') : undefined) ?? request.headers.host\n\n  const touchActivity = (deviceId: ManagementDeviceId): void => {\n    const timestamp = now()\n    if (timestamp - (lastActivityWrite.get(deviceId) ?? 0) < ACTIVITY_WRITE_INTERVAL_MS) return\n    lastActivityWrite.set(deviceId, timestamp)\n    options.repository.touchDevice(deviceId, timestamp)\n  }\n\n  const openSession = (\n    request: IncomingMessage,\n    deviceId: ManagementDeviceId,\n  ): { readonly token: string; readonly session: SessionRecord; readonly cookies: readonly string[] } => {\n    const token = randomBytes(32).toString('base64url')\n    const csrfToken = randomBytes(24).toString('base64url')\n    const session = { deviceId, csrfToken, expiresAt: now() + SESSION_TTL_MS }\n    sessions.set(token, session)\n    touchActivity(deviceId)\n    const secure = secureRequest(request)\n    return {\n      token,\n      session,\n      cookies: [\n        cookie(SESSION_COOKIE, token, SESSION_TTL_MS / 1_000, { httpOnly: true, secure }),\n        cookie(CSRF_COOKIE, csrfToken, SESSION_TTL_MS / 1_000, { httpOnly: false, secure }),\n      ],\n    }\n  }\n\n  const deviceFromCookie = (request: IncomingMessage): ManagementDeviceId | undefined => {\n    const value = parseCookies(request).get(DEVICE_COOKIE)\n    const separator = value?.indexOf('.') ?? -1\n    if (value === undefined || separator < 1) return undefined\n    const deviceId = ManagementDeviceIdSchema.safeParse(value.slice(0, separator))\n    if (!deviceId.success) return undefined\n    const device = options.repository.getActiveDevice(deviceId.data)\n    return device !== undefined &&\n      safeEqual(device.secretDigest, digest('nxt-device-secret-v1', value.slice(separator + 1)))\n      ? device.id\n      : undefined\n  }\n\n  /**\n   * The request's live session; a browser whose session expired but still carries its device cookie gets a new one,\n   * with the cookies queued on `response`.\n   */\n  const authenticatedSession = (\n    request: IncomingMessage,\n    response?: ServerResponse,\n  ): { readonly token: string; readonly session: SessionRecord } | undefined => {\n    cleanExpired()\n    const token = parseCookies(request).get(SESSION_COOKIE)\n    const session = token === undefined ? undefined : sessions.get(token)\n    if (token !== undefined && session !== undefined && options.repository.getActiveDevice(session.deviceId)) {\n      touchActivity(session.deviceId)\n      return { token, session }\n    }\n    const deviceId = response === undefined ? undefined : deviceFromCookie(request)\n    if (deviceId === undefined || response === undefined) return undefined\n    const opened = openSession(request, deviceId)\n    response.setHeader('set-cookie', [...opened.cookies])\n    return opened\n  }\n\n  const validateMutation = (request: IncomingMessage, session: SessionRecord): boolean => {\n    if (methodIsSafe(request.method)) return true\n    const host = publicHost(request)\n    const origin = request.headers.origin\n    if (host === undefined || origin !== `${secureRequest(request) ? 'https' : 'http'}://${host}`) return false\n    const cookieToken = parseCookies(request).get(CSRF_COOKIE)\n    const headerToken = request.headers['x-nxt-csrf']\n    return (\n      typeof headerToken === 'string' && cookieToken === session.csrfToken && safeEqual(headerToken, session.csrfToken)\n    )\n  }\n\n  const proxy = (request: IncomingMessage, response: ServerResponse, viewer: string | undefined): void => {\n    if (stopping) {\n      writeProblem(response, 503, 'server_stopping', '服务实例正在关闭。')\n      return\n    }\n    const upstream = httpRequest(\n      {\n        host: '127.0.0.1',\n        port: options.internalPort,\n        method: request.method,\n        path: request.url,\n        headers: {\n          ...Object.fromEntries(Object.entries(request.headers).filter(([name]) => name !== VIEWER_HEADER)),\n          host: `127.0.0.1:${options.internalPort}`,\n          'x-forwarded-proto': secureRequest(request) ? 'https' : 'http',\n          // The edge is the only place that knows the paired device; clients cannot claim another viewer.\n          ...(viewer === undefined ? {} : { [VIEWER_HEADER]: viewer }),\n        },\n      },\n      (upstreamResponse) => {\n        // Keep a session the edge just renewed from the device cookie alongside the product server's own cookies.\n        const renewed = response.getHeader('set-cookie')\n        const upstreamCookies = upstreamResponse.headers['set-cookie'] ?? []\n        response.writeHead(upstreamResponse.statusCode ?? 502, {\n          ...upstreamResponse.headers,\n          ...(Array.isArray(renewed) ? { 'set-cookie': [...renewed, ...upstreamCookies] } : {}),\n        })\n        upstreamResponse.once('aborted', () => response.destroy(new Error('上游响应提前中断。')))\n        upstreamResponse.once('error', (error) => response.destroy(error))\n        upstreamResponse.pipe(response)\n      },\n    )\n    upstreamRequests.add(upstream)\n    const detach = (): void => {\n      upstreamRequests.delete(upstream)\n      request.off('aborted', abortUpstream)\n      response.off('close', abortUpstream)\n    }\n    const abortUpstream = (): void => {\n      if (!upstream.destroyed) upstream.destroy(new Error('下游连接已经关闭。'))\n    }\n    request.once('aborted', abortUpstream)\n    response.once('close', abortUpstream)\n    upstream.once('close', detach)\n    upstream.on('error', () => {\n      if (response.headersSent) response.destroy()\n      else writeProblem(response, 502, 'upstream_unavailable', '服务实例正在启动，请稍后重试。')\n    })\n    request.pipe(upstream)\n  }\n\n  const handle = (request: IncomingMessage, response: ServerResponse): void => {\n    void (async () => {\n      const url = new URL(request.url ?? '/', 'http://edge.invalid')\n      if ((request.method === 'GET' || request.method === 'HEAD') && url.pathname === '/.well-known/nekro-nxt') {\n        writeJson(response, 200, descriptor)\n        return\n      }\n      if (request.method === 'POST' && url.pathname === '/api/management/pairing/challenge') {\n        cleanExpired()\n        const address = request.socket.remoteAddress ?? 'unknown'\n        const recent = challengeRequests.get(address) ?? []\n        if (challenges.size >= MAX_PENDING_CHALLENGES || recent.length >= CHALLENGES_PER_ADDRESS_PER_MINUTE) {\n          writeProblem(response, 429, 'pairing_rate_limited', '配对请求过于频繁，请稍后重试。')\n          return\n        }\n        challengeRequests.set(address, [...recent, now()])\n        const challengeId = randomBytes(24).toString('base64url')\n        const serverNonce = randomBytes(32).toString('base64url')\n        const expiresAt = now() + CHALLENGE_TTL_MS\n        challenges.set(challengeId, { serverNonce, expiresAt })\n        writeJson(response, 200, {\n          challengeId,\n          serverNonce,\n          instanceId,\n          spkiSha256: certificate.spkiSha256,\n          expiresAt,\n        })\n        return\n      }\n      if (request.method === 'POST' && url.pathname === '/api/management/devices/enroll') {\n        const input = ManagementDeviceEnrollmentRequestSchema.parse(await readJson(request))\n        const challenge = challenges.get(input.challengeId)\n        challenges.delete(input.challengeId)\n        if (challenge === undefined || challenge.expiresAt <= now()) {\n          writeProblem(response, 401, 'challenge_invalid', '配对挑战已失效，请重新连接。')\n          return\n        }\n        const message = managementPairProofMessage({\n          challengeId: input.challengeId,\n          serverNonce: challenge.serverNonce,\n          clientNonce: input.clientNonce,\n          instanceId,\n          spkiSha256: certificate.spkiSha256,\n        })\n        const expected = createHmac('sha256', options.managementKey).update(message).digest('base64url')\n        if (!safeEqual(expected, input.proof)) {\n          writeProblem(response, 401, 'management_key_invalid', '管理密钥不正确。')\n          return\n        }\n        const deviceId = ManagementDeviceIdSchema.parse(`nxt_device_${nextUlid()}`)\n        const deviceSecret = randomBytes(32).toString('base64url')\n        options.repository.putDevice({\n          id: deviceId,\n          label: input.label,\n          secretDigest: digest('nxt-device-secret-v1', deviceSecret),\n          createdAt: now(),\n        })\n        writeJson(response, 201, ManagementDeviceEnrollmentResponseSchema.parse({ deviceId, deviceSecret }))\n        return\n      }\n      if (request.method === 'POST' && url.pathname === '/api/management/session') {\n        cleanExpired()\n        const input = ManagementSessionRequestSchema.parse(await readJson(request))\n        const device = options.repository.getActiveDevice(input.deviceId)\n        if (\n          device === undefined ||\n          !safeEqual(device.secretDigest, digest('nxt-device-secret-v1', input.deviceSecret))\n        ) {\n          writeProblem(response, 401, 'device_credential_invalid', '设备会话已经失效，请重新认证。')\n          return\n        }\n        const opened = openSession(request, device.id)\n        writeJson(\n          response,\n          200,\n          ManagementSessionResponseSchema.parse({\n            authenticated: true,\n            deviceId: device.id,\n            csrfToken: opened.session.csrfToken,\n          }),\n          { 'set-cookie': [...opened.cookies] },\n        )\n        return\n      }\n      if (request.method === 'POST' && url.pathname === '/api/management/login') {\n        if (!allowAttempt(request.socket.remoteAddress ?? 'unknown')) {\n          writeProblem(response, 429, 'login_rate_limited', '登录尝试过于频繁，请一分钟后再试。')\n          return\n        }\n        const input = managementLoginRequestSchema.parse(await readJson(request))\n        const secure = secureRequest(request)\n        if (!secure && !input.acknowledgeInsecure) {\n          writeProblem(response, 400, 'insecure_not_acknowledged', '当前连接未加密，请先确认了解风险。')\n          return\n        }\n        if (!safeEqual(digest('nxt-login-key', input.managementKey), digest('nxt-login-key', options.managementKey))) {\n          writeProblem(response, 401, 'management_key_invalid', '管理密钥不正确。')\n          return\n        }\n        const deviceId = ManagementDeviceIdSchema.parse(`nxt_device_${nextUlid()}`)\n        const deviceSecret = randomBytes(32).toString('base64url')\n        options.repository.putDevice({\n          id: deviceId,\n          label: browserDeviceLabel(request.headers['user-agent']),\n          secretDigest: digest('nxt-device-secret-v1', deviceSecret),\n          createdAt: now(),\n        })\n        const opened = openSession(request, deviceId)\n        writeJson(\n          response,\n          200,\n          { authenticated: true, deviceId },\n          {\n            'set-cookie': [\n              cookie(DEVICE_COOKIE, `${deviceId}.${deviceSecret}`, BROWSER_DEVICE_TTL_MS / 1_000, {\n                httpOnly: true,\n                secure,\n              }),\n              ...opened.cookies,\n            ],\n          },\n        )\n        return\n      }\n      if (request.method === 'GET' && url.pathname === '/login') {\n        const next = safeNext(url.searchParams.get('next'))\n        if (authenticatedSession(request, response) !== undefined) {\n          response.writeHead(302, { location: next, 'cache-control': 'no-store' })\n          response.end()\n          return\n        }\n        const page = managementLoginPage({ secure: secureRequest(request), next })\n        response.writeHead(200, {\n          'content-type': 'text/html; charset=utf-8',\n          'cache-control': 'no-store',\n          'content-length': Buffer.byteLength(page),\n          'x-frame-options': 'DENY',\n          'content-security-policy':\n            \"default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; form-action 'self'; frame-ancestors 'none'\",\n        })\n        response.end(page)\n        return\n      }\n\n      const authenticated = authenticatedSession(request, response)\n      if (request.method === 'GET' && url.pathname === '/api/management/session') {\n        if (authenticated === undefined) {\n          writeProblem(response, 401, 'authentication_required', '请先建立设备会话。')\n          return\n        }\n        writeJson(response, 200, {\n          authenticated: true,\n          deviceId: authenticated.session.deviceId,\n          csrfToken: authenticated.session.csrfToken,\n        })\n        return\n      }\n      if (authenticated === undefined && !publicProxyPath(url.pathname)) {\n        if (wantsPage(request, url.pathname)) {\n          response.writeHead(302, {\n            location: `/login?next=${encodeURIComponent(`${url.pathname}${url.search}`)}`,\n            'cache-control': 'no-store',\n          })\n          response.end()\n          return\n        }\n        writeProblem(response, 401, 'authentication_required', '请先登录。')\n        return\n      }\n      if (authenticated !== undefined && !validateMutation(request, authenticated.session)) {\n        writeProblem(response, 403, 'request_origin_invalid', '请求来源验证失败。')\n        return\n      }\n      if (request.method === 'DELETE' && url.pathname === '/api/management/session') {\n        const session = authenticated!.session\n        sessions.delete(authenticated!.token)\n        // A browser logs out for good: its device is revoked with the session. Desktop keeps its paired device.\n        const browserDevice = deviceFromCookie(request)\n        if (browserDevice !== undefined && browserDevice === session.deviceId) {\n          options.repository.revokeDevice(browserDevice, now())\n          for (const [token, other] of sessions) if (other.deviceId === browserDevice) sessions.delete(token)\n        }\n        const secure = secureRequest(request)\n        writeJson(\n          response,\n          200,\n          { authenticated: false },\n          {\n            'set-cookie': [\n              cookie(SESSION_COOKIE, '', 0, { httpOnly: true, secure }),\n              cookie(CSRF_COOKIE, '', 0, { httpOnly: false, secure }),\n              ...(browserDevice === undefined ? [] : [cookie(DEVICE_COOKIE, '', 0, { httpOnly: true, secure })]),\n            ],\n          },\n        )\n        return\n      }\n      if (request.method === 'GET' && url.pathname === '/api/management/devices') {\n        writeJson(response, 200, {\n          devices: options.